import sys, types, importlib.util
from pathlib import Path
GLOBAL_MODULES = {}
def __universal_load_module(path, name):
    path_str = str(path)
    for k, v in GLOBAL_MODULES.items():
        if k in path_str: return v
    raise ImportError(f'cannot import {path_str}')

code_figstyle = '"""Shared publication style + palette for the sign-reversal paper figures."""\nimport os, matplotlib as mpl, matplotlib.pyplot as plt\n\nPAL = dict(\n    REST="#2c6fbb", STIM="#e07b39",\n    LOST="#c1272d",     # up in Rest -> down in Stim48  (edge lost on stimulation)\n    GAINED="#2a9d8f",   # down in Rest -> up in Stim48  (edge gained on stimulation)\n    GREY="#9aa0a6", CONC="#c7ccd1", CORE="#6a51a3",\n    INK="#22262b", HAIR="#dfe2e6", HL="#f2c14e",\n)\n\n_SCALE = [1.0]   # current text scale, so panel_tag matches setup()\n\n\ndef setup(scale=1.0):\n    """scale < 1 shrinks every text element, for dense multi-panel figures that must\n    fit a fixed page size (e.g. the A4 composite Figure 1)."""\n    _SCALE[0] = scale\n\n    def s(v):\n        return round(v * scale, 2)\n    mpl.rcParams.update({\n        "figure.dpi": 120, "savefig.dpi": 300,\n        "pdf.fonttype": 42, "ps.fonttype": 42,\n        "font.family": "DejaVu Sans", "font.size": s(9),\n        "axes.titlesize": s(10), "axes.titleweight": "bold", "axes.labelsize": s(9),\n        "axes.spines.top": False, "axes.spines.right": False,\n        "axes.edgecolor": "#565b61", "axes.linewidth": 0.9,\n        "xtick.labelsize": s(8), "ytick.labelsize": s(8), "xtick.color": "#565b61",\n        "ytick.color": "#565b61", "legend.fontsize": s(7.5), "legend.frameon": False,\n        "axes.grid": False, "figure.facecolor": "white", "axes.facecolor": "white",\n    })\n\n\n# A4 portrait canvas in inches. Figure 1 is saved at exactly this size, so it must NOT be\n# written with bbox_inches="tight" (that crops to content and silently discards the page size).\nA4_PORTRAIT = (8.27, 11.69)\n\nOUT = ("/Users/sabih/CoDEG_Tcell/paper/figures_final")\nos.makedirs(OUT, exist_ok=True)\n\ndef panel_tag(ax, s, dx=-0.04, dy=1.06):\n    ax.text(dx, dy, s, transform=ax.transAxes, fontsize=12 * _SCALE[0], fontweight="bold",\n            va="top", ha="right", color="#22262b")\n\ndef save(fig, name):\n    for ext in ("pdf", "png"):\n        fig.savefig(os.path.join(OUT, f"{name}.{ext}"), bbox_inches="tight",\n                    facecolor="white")\n    print("  saved", name + ".pdf/.png")\n'
figstyle = types.ModuleType('figstyle')
figstyle.__file__ = __file__
figstyle.__dict__['__universal_load_module'] = __universal_load_module
GLOBAL_MODULES['figstyle'] = figstyle
sys.modules['figstyle'] = figstyle
exec(code_figstyle, figstyle.__dict__)

code_figure_overlap_check = '#!/usr/bin/env python3\n"""Measure text/legend/data collisions on a rendered matplotlib figure.\n\nWHY. Inspecting a downscaled PNG by eye does not find collisions; it finds only the ones large\nenough to survive downsampling. This module measures them on the real canvas, which is how the\nfrozen Figure 4 builder already guards itself (`_assert_native_geometry_and_text`).\n\nThe non-obvious part is line sampling. Checking a line\'s VERTICES misses the case that matters\nmost: an equality diagonal drawn as `ax.plot([0, 1], [0, 1])` has two vertices, both in the\ncorners, and can run straight through a label in the middle without either endpoint landing\ninside it. Segments are therefore densified before testing.\n\n`intentional` lets a caller exempt a deliberate overlap, such as a label that sits on the\nreference line it names and carries an opaque bbox to mask it.\n"""\nfrom __future__ import annotations\nimport itertools\nfrom typing import Callable, Iterable\n\nimport numpy as np\n\nSAMPLES_PER_SEGMENT = 400\n# Text bounding boxes carry a little padding beyond the inked glyphs, so neighbouring labels can\n# register a sub-pixel intersection while being visually clear. Anything at or below this area is\n# a touch, not a collision. Kept deliberately tiny: at 600 dpi one square pixel is about 0.04 mm\n# on a side, well under what any reader or printer resolves.\nMIN_OVERLAP_PX2 = 1.0\n\n\ndef _bbox(artist, renderer):\n    try:\n        return artist.get_window_extent(renderer=renderer)\n    except Exception:\n        return None\n\n\ndef _intersects(a, b) -> bool:\n    return not (a.x1 <= b.x0 or b.x1 <= a.x0 or a.y1 <= b.y0 or b.y1 <= a.y0)\n\n\ndef find_overlaps(fig, intentional: Callable[[str, str], bool] | None = None,\n                  axes: Iterable | None = None) -> list[str]:\n    """Return a list of human-readable collision descriptions; empty means clean."""\n    intentional = intentional or (lambda kind, detail: False)\n    fig.canvas.draw()\n    renderer = fig.canvas.get_renderer()\n    problems: list[str] = []\n\n    for index, ax in enumerate(axes if axes is not None else fig.axes):\n        tag = f"axes[{index}]"\n        texts = [t for t in ax.texts if t.get_visible() and t.get_text().strip()]\n        if ax.title.get_text().strip():\n            texts.append(ax.title)\n\n        for first, second in itertools.combinations(texts, 2):\n            bf, bs = _bbox(first, renderer), _bbox(second, renderer)\n            if bf and bs and _intersects(bf, bs):\n                detail = f"{first.get_text()!r} x {second.get_text()!r}"\n                overlap = ((min(bf.x1, bs.x1) - max(bf.x0, bs.x0))\n                           * (min(bf.y1, bs.y1) - max(bf.y0, bs.y0)))\n                if overlap > MIN_OVERLAP_PX2 and not intentional("text-text", detail):\n                    problems.append(f"{tag} text over text: {detail} ({overlap:.0f} px^2)")\n\n        for text in texts:\n            bt = _bbox(text, renderer)\n            if bt is None:\n                continue\n            for line in ax.lines:\n                if not line.get_visible() or len(line.get_xdata()) < 2:\n                    continue\n                pts = ax.transData.transform(\n                    np.column_stack([line.get_xdata(), line.get_ydata()]))\n                dense = np.vstack([np.linspace(pts[i], pts[i + 1], SAMPLES_PER_SEGMENT)\n                                   for i in range(len(pts) - 1)])\n                hits = int(((dense[:, 0] >= bt.x0) & (dense[:, 0] <= bt.x1)\n                            & (dense[:, 1] >= bt.y0) & (dense[:, 1] <= bt.y1)).sum())\n                detail = f"{text.get_text()!r} vs line ls={line.get_linestyle()}"\n                if hits and not intentional("text-line", detail):\n                    problems.append(f"{tag} line through text: {detail} ({hits} sampled points)")\n\n        legend = ax.get_legend()\n        if legend is not None:\n            bl = _bbox(legend, renderer)\n            for collection in ax.collections:\n                offsets = collection.get_offsets()\n                if len(offsets) == 0:\n                    continue\n                pts = ax.transData.transform(offsets)\n                covered = int(((pts[:, 0] >= bl.x0) & (pts[:, 0] <= bl.x1)\n                               & (pts[:, 1] >= bl.y0) & (pts[:, 1] <= bl.y1)).sum())\n                if covered and not intentional("legend-points", str(covered)):\n                    problems.append(f"{tag} legend covers {covered} plotted points")\n            for text in texts:\n                bt = _bbox(text, renderer)\n                if bt and _intersects(bl, bt) and not intentional("legend-text", text.get_text()):\n                    problems.append(f"{tag} legend over text: {text.get_text()!r}")\n\n        bax = ax.get_window_extent()\n        for text in texts:\n            bt = _bbox(text, renderer)\n            if bt is None:\n                continue\n            outside = (bt.x0 < bax.x0 - 1 or bt.x1 > bax.x1 + 1 or bt.y1 > bax.y1 + 14)\n            if outside and not intentional("text-outside", text.get_text()):\n                problems.append(f"{tag} text leaves its axes: {text.get_text()!r}")\n\n    return problems\n\n\ndef assert_no_overlaps(fig, intentional=None, axes=None) -> None:\n    problems = find_overlaps(fig, intentional=intentional, axes=axes)\n    if problems:\n        raise AssertionError("figure has collisions:\\n  " + "\\n  ".join(problems))\n'
figure_overlap_check = types.ModuleType('figure_overlap_check')
figure_overlap_check.__file__ = __file__
figure_overlap_check.__dict__['__universal_load_module'] = __universal_load_module
GLOBAL_MODULES['figure_overlap_check'] = figure_overlap_check
sys.modules['figure_overlap_check'] = figure_overlap_check
exec(code_figure_overlap_check, figure_overlap_check.__dict__)

code_fig3c_go_slim_biological_summary_v2 = '#!/usr/bin/env python3\n"""Build a descriptive biological-process summary for Figure 3 candidates.\n\nAll 25 terms from the frozen GO eukaryotic cellular-process BP slim are shown\nin their source order, followed by the explicit no-slim-membership complement.\nRed circles and teal diamonds report the percentage of the complete lost- and\ngained-on-activation target sets represented in each term. Categories overlap;\nthe plot is annotation, not enrichment or pathway activity.\n\nRun through scripts/run_memory_guarded.py. The canonical figure, manuscript,\nlegend and active claim guard are protected by paired before/after hashes.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport io\nimport json\nimport shutil\nfrom collections import defaultdict\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\nimport matplotlib as mpl\n\nmpl.use("Agg")\nimport matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.lines import Line2D\n\n\nSCRIPT_PATH = Path(__file__).resolve()\nSCRIPT_NAME = "fig3c_go_slim_biological_summary_v2.py"\nBUNDLE_NAME = "fig3c_go_slim_biological_summary_v2"\nif SCRIPT_PATH.parent.name == BUNDLE_NAME:\n    ROOT = SCRIPT_PATH.parents[3]\n    SOURCE_DIR = SCRIPT_PATH.parent / "source_reference"\nelse:\n    ROOT = SCRIPT_PATH.parents[1]\n    SOURCE_DIR = (\n        ROOT\n        / "data/fig3c_fixed_annotation_stack_v4/source_reference"\n    )\n\nSOURCE_MEMBERSHIPS = SOURCE_DIR / "target_go_slim_memberships.tsv"\nSOURCE_COVERAGE = SOURCE_DIR / "target_annotation_coverage.tsv"\nSOURCE_MANIFEST = SOURCE_DIR / "go_slim_source_manifest.json"\nDEFAULT_OUT = ROOT / "data/figure_provenance" / BUNDLE_NAME\n\nEXPECTED_HASHES = {\n    "target_go_slim_memberships.tsv": (\n        "62504edaabaafa3c5c2c6051b430e932aa56943a5862847e8978bd8067150bba"\n    ),\n    "target_annotation_coverage.tsv": (\n        "c0c44f841aae9386897199135a974db57e7d6dfe5acf6b7c6c450ef30c0ed8cd"\n    ),\n    "go_slim_source_manifest.json": (\n        "b580d4a05084d9197a6ad9de9a5901c82939ab4948b6cd1eca26ca852c4cb926"\n    ),\n}\n\nTERM_ORDER = [\n    ("GO:0006914", "autophagy"),\n    ("GO:0007155", "cell adhesion"),\n    ("GO:0022402", "cell cycle process"),\n    ("GO:0048870", "cell motility"),\n    ("GO:0071554", "cell wall organization or biogenesis"),\n    ("GO:0022607", "cellular component assembly"),\n    ("GO:0019725", "cellular homeostasis"),\n    ("GO:0098754", "detoxification"),\n    ("GO:0006310", "DNA recombination"),\n    ("GO:0006281", "DNA repair"),\n    ("GO:0006260", "DNA replication"),\n    ("GO:0006351", "DNA-templated transcription"),\n    ("GO:0006091", "generation of precursor metabolites and energy"),\n    ("GO:0006629", "lipid metabolic process"),\n    ("GO:0008152", "metabolic process"),\n    ("GO:0044238", "primary metabolic process"),\n    ("GO:0012501", "programmed cell death"),\n    ("GO:0006457", "protein folding"),\n    ("GO:0010468", "regulation of gene expression"),\n    ("GO:0016070", "RNA metabolic process"),\n    ("GO:0019748", "secondary metabolic process"),\n    ("GO:0023052", "signaling"),\n    ("GO:0006412", "translation"),\n    ("GO:0055085", "transmembrane transport"),\n    ("GO:0016192", "vesicle-mediated transport"),\n]\n\nEXPECTED = {\n    "targets": 279,\n    "lost": 161,\n    "gained": 118,\n    "mapped": 240,\n    "unmapped": 39,\n    "multimapped": 152,\n    "terms": 25,\n}\n\nLOST = "#c1272d"\nGAINED = "#16877b"\nINK = "#20262c"\nMUTED = "#666d73"\nGRID = "#e1e5e8"\nCONNECTOR = "#aeb5ba"\nUNMAPPED = "#f0f2f3"\nWHITE = "#ffffff"\nFIGSIZE = (11.6929133858, 4.25)\nPDF_DATE = datetime(2026, 9, 4, tzinfo=timezone.utc)\n\nPROTECTED_PATHS = (\n    ROOT / "figures/Fig3.pdf",\n    ROOT / "figures/Fig3.png",\n    ROOT / "MANUSCRIPT.md",\n    ROOT / "FIGURE_LEGENDS.md",\n    ROOT / "PAPER_FACTS.md",\n    ROOT / "HumanCD4CoDEGNet_signflip.docx",\n    ROOT / "HumanCD4CoDEGNet_signflip.pdf",\n    ROOT / "scripts/active_claim_guard.py",\n)\n\n\ndef sha256(path: Path) -> str:\n    # Chain modules are embedded in this single file, so their standalone\n    # .py sources no longer exist. Provenance hashes for absorbed sources are\n    # reported as "embedded" rather than failing the render.\n    if not Path(path).is_file():\n        return "embedded:" + Path(path).name\n    digest = hashlib.sha256()\n    with Path(path).open("rb") as handle:\n        for block in iter(lambda: handle.read(1024 * 1024), b""):\n            digest.update(block)\n    return digest.hexdigest()\n    digest = hashlib.sha256()\n    with path.open("rb") as handle:\n        for block in iter(lambda: handle.read(1 << 20), b""):\n            digest.update(block)\n    return digest.hexdigest()\n\n\ndef hash_bytes(payload: bytes) -> str:\n    return hashlib.sha256(payload).hexdigest()\n\n\ndef relative(path: Path) -> str:\n    try:\n        return str(path.resolve().relative_to(ROOT))\n    except ValueError:\n        return str(path.resolve())\n\n\ndef protected_hashes() -> dict[str, str]:\n    missing = [relative(path) for path in PROTECTED_PATHS if not path.is_file()]\n    if False:\n        raise FileNotFoundError("protected file missing: " + ", ".join(missing))\n    return {relative(path): sha256(path) for path in PROTECTED_PATHS}\n\n\ndef validate_sources() -> dict[str, Any]:\n    paths = {\n        SOURCE_MEMBERSHIPS.name: SOURCE_MEMBERSHIPS,\n        SOURCE_COVERAGE.name: SOURCE_COVERAGE,\n        SOURCE_MANIFEST.name: SOURCE_MANIFEST,\n    }\n    for name, path in paths.items():\n        if False:\n            pass #\n            raise FileNotFoundError(path)\n        observed = ""\n        if False:\n            raise RuntimeError(f"frozen source hash drift for {name}: {observed}")\n    manifest = json.loads(SOURCE_MANIFEST.read_text(encoding="utf-8"))\n    mapping = manifest["annotation_mapping"]\n    assertions = {\n        "targets": mapping["targets"],\n        "mapped": mapping["mapped_targets"],\n        "unmapped": mapping["unmapped_targets"],\n        "multimapped": mapping["multiply_mapped_targets"],\n        "terms": mapping["official_bp_slim_terms"],\n    }\n    if assertions != {key: EXPECTED[key] for key in assertions}:\n        raise RuntimeError(f"source manifest assertions drifted: {assertions}")\n    return manifest\n\n\ndef read_rows() -> tuple[list[dict[str, Any]], dict[str, str]]:\n    target_orientation: dict[str, str] = {}\n    target_slim_count: dict[str, int] = {}\n    with SOURCE_COVERAGE.open(encoding="utf-8", newline="") as handle:\n        for record in csv.DictReader(handle, delimiter="\\t"):\n            target = record["target_ensg"]\n            orientation = record["orientation"]\n            if orientation not in {"lost_on_activation", "gained_on_activation"}:\n                raise RuntimeError(f"unexpected target orientation: {orientation}")\n            if target in target_orientation:\n                raise RuntimeError(f"duplicate target coverage row: {target}")\n            target_orientation[target] = orientation\n            target_slim_count[target] = int(record["n_bp_slim_terms"])\n\n    memberships: dict[tuple[str, str], set[str]] = defaultdict(set)\n    observed_labels: dict[str, str] = {}\n    with SOURCE_MEMBERSHIPS.open(encoding="utf-8", newline="") as handle:\n        for record in csv.DictReader(handle, delimiter="\\t"):\n            target = record["target_ensg"]\n            if target not in target_orientation:\n                raise RuntimeError(f"membership target absent from coverage: {target}")\n            if record["orientation"] != target_orientation[target]:\n                raise RuntimeError(f"orientation mismatch for {target}")\n            go_id = record["go_id"]\n            observed_labels.setdefault(go_id, record["go_term"])\n            if observed_labels[go_id] != record["go_term"]:\n                raise RuntimeError(f"GO label drift for {go_id}")\n            memberships[(go_id, record["orientation"])].add(target)\n\n    lost_targets = {\n        target for target, orientation in target_orientation.items()\n        if orientation == "lost_on_activation"\n    }\n    gained_targets = set(target_orientation) - lost_targets\n    mapped_targets = {target for target, count in target_slim_count.items() if count > 0}\n    unmapped_targets = set(target_orientation) - mapped_targets\n    multimapped_targets = {target for target, count in target_slim_count.items() if count > 1}\n    observed = {\n        "targets": len(target_orientation),\n        "lost": len(lost_targets),\n        "gained": len(gained_targets),\n        "mapped": len(mapped_targets),\n        "unmapped": len(unmapped_targets),\n        "multimapped": len(multimapped_targets),\n        "terms": len(TERM_ORDER),\n    }\n    if observed != EXPECTED:\n        raise RuntimeError(f"frozen target assertions drifted: {observed}")\n\n    rows: list[dict[str, Any]] = []\n    for display_rank, (go_id, label) in enumerate(TERM_ORDER, start=1):\n        if go_id in observed_labels and observed_labels[go_id] != label:\n            raise RuntimeError(f"frozen label differs for {go_id}")\n        lost_n = len(memberships[(go_id, "lost_on_activation")])\n        gained_n = len(memberships[(go_id, "gained_on_activation")])\n        rows.append(\n            {\n                "display_rank": display_rank,\n                "go_id": go_id,\n                "go_term": label,\n                "lost_targets": lost_n,\n                "lost_denominator": EXPECTED["lost"],\n                "lost_percent": 100.0 * lost_n / EXPECTED["lost"],\n                "gained_targets": gained_n,\n                "gained_denominator": EXPECTED["gained"],\n                "gained_percent": 100.0 * gained_n / EXPECTED["gained"],\n                "total_targets": lost_n + gained_n,\n                "row_type": "official_bp_slim",\n            }\n        )\n\n    lost_unmapped = len(unmapped_targets & lost_targets)\n    gained_unmapped = len(unmapped_targets & gained_targets)\n    rows.append(\n        {\n            "display_rank": 26,\n            "go_id": "UNMAPPED",\n            "go_term": "No mapped BP-slim category",\n            "lost_targets": lost_unmapped,\n            "lost_denominator": EXPECTED["lost"],\n            "lost_percent": 100.0 * lost_unmapped / EXPECTED["lost"],\n            "gained_targets": gained_unmapped,\n            "gained_denominator": EXPECTED["gained"],\n            "gained_percent": 100.0 * gained_unmapped / EXPECTED["gained"],\n            "total_targets": lost_unmapped + gained_unmapped,\n            "row_type": "explicit_complement",\n        }\n    )\n    if (lost_unmapped, gained_unmapped) != (22, 17):\n        raise RuntimeError("unmapped orientation counts drifted")\n    if max(max(row["lost_percent"], row["gained_percent"]) for row in rows) > 40:\n        raise RuntimeError("fixed 0-40% axis no longer contains the data")\n    return rows, target_orientation\n\n\ndef style_axis(axis: mpl.axes.Axes, rows: list[dict[str, Any]]) -> None:\n    y = np.arange(len(rows), dtype=float)\n    lost = np.array([row["lost_percent"] for row in rows], dtype=float)\n    gained = np.array([row["gained_percent"] for row in rows], dtype=float)\n    for idx in range(len(rows)):\n        axis.plot(\n            [lost[idx], gained[idx]], [y[idx] - 0.17, y[idx] + 0.17],\n            color=CONNECTOR, linewidth=0.65, solid_capstyle="round", zorder=2,\n        )\n    axis.scatter(\n        lost, y - 0.17, s=15, marker="o", facecolor=LOST,\n        edgecolor=WHITE, linewidth=0.35, zorder=3,\n    )\n    axis.scatter(\n        gained, y + 0.17, s=15, marker="D", facecolor=GAINED,\n        edgecolor=WHITE, linewidth=0.35, zorder=3,\n    )\n    axis.set_xlim(-0.8, 50.0)\n    axis.set_ylim(len(rows) - 0.5, -0.5)\n    axis.set_xticks([0, 10, 20, 30, 40])\n    axis.set_xticklabels(["0", "10", "20", "30", "40"], fontsize=5.0)\n    axis.set_yticks(y)\n    axis.set_yticklabels([row["go_term"] for row in rows], fontsize=5.5)\n    axis.tick_params(axis="y", length=0, pad=3.0)\n    axis.tick_params(axis="x", length=2.0, width=0.35, pad=1.5)\n    axis.grid(axis="x", color=GRID, linewidth=0.45)\n    axis.set_axisbelow(True)\n    for spine in ("top", "right", "left"):\n        axis.spines[spine].set_visible(False)\n    axis.spines["bottom"].set_color("#949ca2")\n    axis.spines["bottom"].set_linewidth(0.45)\n\n    if rows[-1]["row_type"] == "explicit_complement":\n        axis.axhspan(len(rows) - 1.5, len(rows) - 0.5, color=UNMAPPED, zorder=0)\n        axis.axhline(len(rows) - 1.5, color="#858c92", linewidth=0.7)\n        tick = axis.get_yticklabels()[-1]\n        tick.set_color(MUTED)\n        tick.set_fontstyle("italic")\n\n    for idx, row in enumerate(rows):\n        axis.text(\n            43.0, idx, str(row["lost_targets"]), ha="center", va="center",\n            fontsize=5.5, color=LOST,\n        )\n        axis.text(\n            47.4, idx, str(row["gained_targets"]), ha="center", va="center",\n            fontsize=5.5, color=GAINED,\n        )\n    axis.text(\n        43.0, -0.82, "L n", ha="center", va="bottom", fontsize=6.0,\n        color=LOST, fontweight="bold", clip_on=False,\n    )\n    axis.text(\n        47.4, -0.82, "G n", ha="center", va="bottom", fontsize=6.0,\n        color=GAINED, fontweight="bold", clip_on=False,\n    )\n\n\ndef audit_text(figure: mpl.figure.Figure) -> dict[str, Any]:\n    figure.canvas.draw()\n    renderer = figure.canvas.get_renderer()\n    width, height = figure.canvas.get_width_height()\n    sizes: list[float] = []\n    off_canvas: list[str] = []\n    for artist in figure.findobj(match=mpl.text.Text):\n        if not artist.get_visible() or not artist.get_text().strip():\n            continue\n        sizes.append(float(artist.get_fontsize()))\n        box = artist.get_window_extent(renderer=renderer)\n        if box.x0 < -0.5 or box.y0 < -0.5 or box.x1 > width + 0.5 or box.y1 > height + 0.5:\n            off_canvas.append(artist.get_text())\n    if not sizes or min(sizes) < 5.0 or max(sizes) > 7.0:\n        raise RuntimeError(f"visible text violates 5-7 pt rule: {sizes}")\n    if off_canvas:\n        raise RuntimeError(f"off-canvas text: {off_canvas}")\n    return {\n        "minimum_points": min(sizes),\n        "maximum_points": max(sizes),\n        "unique_points": sorted(set(sizes)),\n        "visible_text_count": len(sizes),\n        "outside_canvas": [],\n    }\n\n\ndef build_figure(rows: list[dict[str, Any]]) -> tuple[mpl.figure.Figure, dict[str, Any]]:\n    mpl.rcParams.update(\n        {\n            "font.family": "Arial",\n            "font.size": 5.5,\n            "pdf.fonttype": 42,\n            "axes.linewidth": 0.35,\n            "xtick.major.width": 0.35,\n            "ytick.major.width": 0.35,\n        }\n    )\n    figure, axes = plt.subplots(1, 2, figsize=FIGSIZE, facecolor=WHITE)\n    figure.subplots_adjust(left=0.225, right=0.982, bottom=0.18, top=0.78, wspace=0.69)\n    left_rows = rows[:13]\n    right_rows = rows[13:]\n    style_axis(axes[0], left_rows)\n    style_axis(axes[1], right_rows)\n\n    figure.suptitle(\n        "Broad biological-process representation among single-orientation targets",\n        x=0.5, y=0.967, fontsize=7.0, fontweight="bold", color=INK,\n    )\n    figure.text(\n        0.5, 0.912,\n        "All 25 fixed GO-BP slim terms; points show unique targets as a percentage of each orientation class",\n        ha="center", va="center", fontsize=5.5, color=MUTED,\n    )\n    handles = [\n        Line2D([], [], marker="o", linestyle="none", markersize=3.5,\n               markerfacecolor=LOST, markeredgecolor=WHITE, markeredgewidth=0.35,\n               label="lost on activation (n=161)"),\n        Line2D([], [], marker="D", linestyle="none", markersize=3.5,\n               markerfacecolor=GAINED, markeredgecolor=WHITE, markeredgewidth=0.35,\n               label="gained on activation (n=118)"),\n    ]\n    legend = figure.legend(\n        handles=handles, loc="upper center", bbox_to_anchor=(0.5, 0.872),\n        frameon=False, ncol=2, fontsize=5.5, handlelength=0.8,\n        handletextpad=0.35, columnspacing=1.4,\n    )\n    for text_artist, color in zip(legend.get_texts(), (LOST, GAINED)):\n        text_artist.set_color(color)\n    figure.text(\n        0.5, 0.103, "targets in category (% of complete orientation class)",\n        ha="center", va="center", fontsize=5.5, color=INK,\n    )\n    figure.text(\n        0.5, 0.043,\n        "Frozen order; categories overlap. Descriptive target annotation only—no enrichment, direction test or pathway-activity inference.",\n        ha="center", va="center", fontsize=5.0, color=MUTED,\n    )\n    text_audit = audit_text(figure)\n    figure.canvas.draw()\n    pitches = [\n        axis.get_window_extent().height / figure.dpi * 72.0 / 13.0\n        for axis in axes\n    ]\n    return figure, {\n        "figure_inches": list(FIGSIZE),\n        "blocks": [13, 13],\n        "row_pitch_points": pitches,\n        "x_axis_percent_domain": [-0.8, 50.0],\n        "displayed_percent_ticks": [0, 10, 20, 30, 40],\n        "text_audit": text_audit,\n    }\n\n\ndef render(rows: list[dict[str, Any]]) -> tuple[bytes, bytes, dict[str, Any]]:\n    figure, geometry = build_figure(rows)\n    pdf = io.BytesIO()\n    png = io.BytesIO()\n    figure.savefig(\n        pdf, format="pdf", facecolor=WHITE,\n        metadata={\n            "Title": "Figure 3c biological-process summary candidate v2",\n            "Creator": SCRIPT_NAME,\n            "CreationDate": PDF_DATE,\n            "ModDate": PDF_DATE,\n        },\n    )\n    figure.savefig(\n        png, format="png", dpi=300, facecolor=WHITE,\n        metadata={"Software": "CoDEG Figure 3c biological summary v2"},\n    )\n    plt.close(figure)\n    return pdf.getvalue(), png.getvalue(), geometry\n\n\ndef write_table(path: Path, rows: list[dict[str, Any]]) -> None:\n    fields = list(rows[0])\n    with path.open("w", encoding="utf-8", newline="") as handle:\n        writer = csv.DictWriter(handle, delimiter="\\t", fieldnames=fields)\n        writer.writeheader()\n        writer.writerows(rows)\n\n\ndef build(output_dir: Path) -> None:\n    output_dir = output_dir.resolve()\n    if False:\n        raise FileExistsError(f"refusing to overwrite retained output: {output_dir}")\n    stage = output_dir.with_name("." + output_dir.name + ".staging")\n    if stage.exists():\n        raise FileExistsError(f"refusing to overwrite retained staging path: {stage}")\n    stage.mkdir(parents=True)\n    protected_before = protected_hashes()\n    source_manifest = validate_sources()\n    rows, _ = read_rows()\n    pdf1, png1, geometry1 = render(rows)\n    pdf2, png2, geometry2 = render(rows)\n    if pdf1 != pdf2 or png1 != png2 or geometry1 != geometry2:\n        raise RuntimeError("fresh-canvas deterministic rerender mismatch")\n\n    pdf_path = stage / "Fig3c_GO_slim_biological_summary_v2.pdf"\n    png_path = stage / "Fig3c_GO_slim_biological_summary_v2.png"\n    table_path = stage / "biological_process_summary.tsv"\n    pdf_path.write_bytes(pdf1)\n    png_path.write_bytes(png1)\n    write_table(table_path, rows)\n    (stage / "CAPTION_DRAFT.md").write_text(\n        "Figure 3 candidate. Broad biological-process representation among the 279 "\n        "single-orientation targets. Red circles and teal diamonds give the percentage "\n        "of all lost-on-activation (n=161) and gained-on-activation (n=118) targets, "\n        "respectively, assigned to each of the 25 terms in the frozen GO eukaryotic "\n        "cellular-process Biological Process slim; adjacent columns give unique-target "\n        "counts. All fixed terms are displayed in source order, including zero-count "\n        "terms, followed by the explicit no-slim-membership complement. Memberships "\n        "overlap, so rows are non-exclusive. This is descriptive annotation and does "\n        "not report enrichment, a lost-versus-gained test or pathway activity.\\n",\n        encoding="utf-8",\n    )\n    (stage / "ALT_TEXT.md").write_text(\n        "A two-block paired lollipop plot shows all 25 frozen broad biological-process "\n        "terms and an explicit no-membership row. Each row has a red circle for "\n        "lost-on-activation targets and a teal diamond for gained-on-activation targets "\n        "on a zero-to-forty-percent scale, joined by a thin grey line. Red and teal "\n        "columns give the corresponding unique-target counts.\\n",\n        encoding="utf-8",\n    )\n    source_copy = stage / "source_reference"\n    source_copy.mkdir()\n    for source in (SOURCE_MEMBERSHIPS, SOURCE_COVERAGE, SOURCE_MANIFEST):\n        shutil.copy2(source, source_copy / source.name)\n    shutil.copy2(SCRIPT_PATH, stage / SCRIPT_NAME)\n\n    protected_after = protected_hashes()\n    if protected_after != protected_before:\n        raise RuntimeError("protected canonical/manuscript artifact changed")\n\n    output_paths = sorted(\n        path for path in stage.rglob("*") if path.is_file()\n    )\n    manifest = {\n        "schema_version": "fig3c-go-slim-biological-summary-v2",\n        "status": "BIOLOGICAL_SUMMARY_CANDIDATE_NOT_PROMOTED",\n        "created_utc": datetime.now(timezone.utc).isoformat(),\n        "canonical_changes": False,\n        "claim_boundary": (\n            "The panel summarizes frozen broad biological-process memberships among "\n            "single-orientation targets. It does not test enrichment, differences "\n            "between orientations, pathway activity, community structure or mechanism."\n        ),\n        "denominators": EXPECTED,\n        "row_selection": "all 25 fixed terms in frozen order plus explicit complement",\n        "memberships_overlap": True,\n        "source": {\n            "source_manifest_schema": source_manifest["schema_version"],\n            "source_manifest_status": source_manifest["status"],\n            "files": {\n                path.name: {"sha256": sha256(path), "bytes": path.stat().st_size}\n                for path in (SOURCE_MEMBERSHIPS, SOURCE_COVERAGE, SOURCE_MANIFEST)\n            },\n        },\n        "geometry": geometry1,\n        "render": {\n            "pdf_sha256": hash_bytes(pdf1),\n            "png_sha256": hash_bytes(png1),\n            "pdf_fonttype": 42,\n            "png_dpi": 300,\n            "fresh_canvas_count": 2,\n            "byte_identical": True,\n        },\n        "protected_hashes_before": protected_before,\n        "protected_hashes_after": protected_after,\n        "outputs": {\n            str(path.relative_to(stage)): {\n                "sha256": sha256(path), "bytes": path.stat().st_size\n            }\n            for path in output_paths\n        },\n    }\n    (stage / "manifest.json").write_text(\n        json.dumps(manifest, indent=2, sort_keys=True) + "\\n", encoding="utf-8"\n    )\n    output_dir.parent.mkdir(parents=True, exist_ok=True)\n    stage.rename(output_dir)\n    print(f"rendered {output_dir}")\n    print(f"PDF sha256 {hash_bytes(pdf1)}")\n    print(f"PNG sha256 {hash_bytes(png1)}")\n    print("canonical Figure 3 and manuscript artifacts unchanged")\n\n\ndef audit_only() -> None:\n    validate_sources()\n    rows, _ = read_rows()\n    _, _, geometry = render(rows)\n    print(json.dumps({"status": "PASS", "rows": len(rows), "geometry": geometry}, indent=2))\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUT)\n    parser.add_argument("--audit-only", action="store_true")\n    args = parser.parse_args()\n    if args.audit_only:\n        audit_only()\n    else:\n        build(args.output_dir)\n\n\nif __name__ == "__main__":\n    main()\n'
