code_fig3_biological_bridge_candidate = '#!/usr/bin/env python3\n"""Render the non-destructive Figure 3 biological-bridge candidate.\n\nThis is a presentation-only build from frozen or versioned result tables.  It\ndoes not rerun a permutation, bootstrap, enrichment test, or the failed\nfixed-margin two-step sampler. The five panels are:\n\n  a  external recurrence in Arce et al.;\n  b  target concentration and target-conditioned reversal direction;\n  c  lost/gained reversal counts plus descriptive target-programme counts for\n     all 49 enriched regulators;\n  d  exhaustive post-hoc CCNC-TADA2B-SUPT7L target zoom; and\n  e  exhaustive post-hoc AHR-ARNT target zoom.\n\nThe output directory is created atomically and must not already exist.  This\nscript is intentionally suitable for the repository\'s bounded local render\nguard; it should not be invoked directly for production work.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport json\nimport math\nimport os\nfrom pathlib import Path\nimport shutil\nimport sys\nimport tempfile\nfrom typing import Any, Iterable\n\nimport matplotlib as mpl\nimport matplotlib.pyplot as plt\nfrom matplotlib.colors import TwoSlopeNorm\nfrom matplotlib.patches import FancyArrowPatch, FancyBboxPatch, Rectangle\nimport numpy as np\nimport pandas as pd\nfrom PIL import Image\n\n\nROOT = Path(__file__).resolve().parents[1]\nsys.path.insert(0, str(ROOT / "scripts"))\nimport figstyle as S  # noqa: E402\n\n\nBRIDGE = ROOT / "data/census/fig3_biological_bridge"\nINPUTS = {\n    "arce": ROOT / "data/arce/arce_validation_results.json",\n    "concentration": ROOT / "data/census/convergence_test_results.json",\n    "unanimity": ROOT / "data/census/target_theory_decisive.json",\n    "all49": BRIDGE / "all49_enriched_regulators.csv",\n    "programmes": BRIDGE / "all49_target_programme_counts.csv",\n    "programme_memberships": BRIDGE / "all49_target_programme_memberships.csv",\n    "programme_manifest": BRIDGE / "all49_target_programme_manifest.json",\n    "cofactor": BRIDGE / "shared_reversal_targets_CCNC_TADA2B_SUPT7L.csv",\n    "sensor": BRIDGE / "shared_reversal_targets_AHR_ARNT.csv",\n    "bridge_manifest": BRIDGE / "manifest.json",\n}\n\nDEFAULT_OUT = (\n    ROOT / "data/figure_provenance/fig3_biological_bridge_candidate_v4"\n)\n# Exact ISO 216 A4 dimensions.  Decimal-inch approximations such as 8.27 x\n# 11.69 produce a slightly short PDF MediaBox.\nSOURCE_WIDTH_IN = 210.0 / 25.4\nSOURCE_HEIGHT_IN = 297.0 / 25.4\nTARGET_WIDTH_MM = 165.1\nMIN_SOURCE_FONT_PT = 9.0\nMIN_PRINT_FONT_PT = MIN_SOURCE_FONT_PT * (TARGET_WIDTH_MM / 25.4) / SOURCE_WIDTH_IN\n\nLOST = S.PAL["LOST"]\nGAINED = S.PAL["GAINED"]\nINK = S.PAL["INK"]\nGREY = "#6f767d"\nLIGHT_GREY = "#eef0f2"\nGOLD = "#d59b32"\nNAVY = "#33475b"\n\nPROGRAMME_ORDER = [\n    "tcr_cytokine_signalling",\n    "antigen_processing_proteasome",\n    "stress_survival",\n    "proliferation",\n    "metabolism_mitochondria",\n    "synapse_trafficking",\n    "unclassified",\n]\nPROGRAMME_LABELS = {\n    "tcr_cytokine_signalling": "TCR / cytokine",\n    "antigen_processing_proteasome": "antigen / proteasome",\n    "stress_survival": "stress / survival",\n    "proliferation": "proliferation",\n    "metabolism_mitochondria": "metabolism / mito.",\n    "synapse_trafficking": "synapse / traffic.",\n    "unclassified": "unclassified",\n}\nPROGRAMME_SHORT = {\n    "tcr_cytokine_signalling": "TCR /\\ncytokine",\n    "antigen_processing_proteasome": "antigen /\\nproteasome",\n    "stress_survival": "stress /\\nsurvival",\n    "proliferation": "prolif.",\n    "metabolism_mitochondria": "metab. /\\nmito.",\n    "synapse_trafficking": "synapse /\\ntraffic.",\n    "unclassified": "outside\\nsix",\n}\n\n\ndef sha256(path: Path) -> str:\n    # Chain modules are embedded in this single file, so their standalone\n    # .py sources no longer exist. Provenance hashes for absorbed sources are\n    # reported as "embedded" rather than failing the render.\n    if not Path(path).is_file():\n        return "embedded:" + Path(path).name\n    digest = hashlib.sha256()\n    with Path(path).open("rb") as handle:\n        for block in iter(lambda: handle.read(1024 * 1024), b""):\n            digest.update(block)\n    return digest.hexdigest()\n    digest = hashlib.sha256()\n    with path.open("rb") as handle:\n        for chunk in iter(lambda: handle.read(1024 * 1024), b""):\n            digest.update(chunk)\n    return digest.hexdigest()\n\n\ndef require_inputs() -> None:\n    missing = [str(path) for path in INPUTS.values() if not path.is_file()]\n    if False:\n        raise FileNotFoundError("required Figure 3 inputs are missing: " + ", ".join(missing))\n\n\ndef read_json(path: Path) -> dict[str, Any]:\n    with path.open(encoding="utf-8") as handle:\n        return json.load(handle)\n\n\ndef configure_style() -> None:\n    S.setup(scale=1.0)\n    mpl.rcParams.update(\n        {\n            "font.size": MIN_SOURCE_FONT_PT,\n            "axes.titlesize": 10.2,\n            "axes.labelsize": MIN_SOURCE_FONT_PT,\n            "xtick.labelsize": MIN_SOURCE_FONT_PT,\n            "ytick.labelsize": MIN_SOURCE_FONT_PT,\n            "legend.fontsize": MIN_SOURCE_FONT_PT,\n            "pdf.fonttype": 42,\n            "ps.fonttype": 42,\n            "figure.facecolor": "white",\n            "savefig.facecolor": "white",\n            "savefig.transparent": False,\n        }\n    )\n\n\ndef panel_tag(ax: mpl.axes.Axes, label: str, x: float = -0.075, y: float = 1.08) -> None:\n    ax.text(\n        x,\n        y,\n        label,\n        transform=ax.transAxes,\n        fontsize=13,\n        fontweight="bold",\n        color=INK,\n        ha="right",\n        va="top",\n        clip_on=False,\n    )\n\n\ndef panel_a_external(ax: mpl.axes.Axes, data: dict[str, Any]) -> pd.DataFrame:\n    result = data["perturbseq"]\n    frame = pd.DataFrame(result["per_regulator"]).sort_values("n_rev", ascending=True)\n    y = np.arange(len(frame))\n    values = frame["or_haldane"].to_numpy(float)\n    sizes = 24 + 72 * np.sqrt(frame["n_rev"].to_numpy(float) / frame["n_rev"].max())\n    colors = np.where(values >= 1, "#6a51a3", LOST)\n    # Keep the evidence panel visually balanced and release horizontal space\n    # for the two distinct target-organisation plots in panel b.\n    ax.set_box_aspect(1.0)\n\n    # Stop reference guides below the reserved text band.\n    ax.axvspan(\n        result["loo_or_min"],\n        result["loo_or_max"],\n        ymin=0.0,\n        ymax=0.72,\n        color="#f2c14e",\n        alpha=0.23,\n        lw=0,\n    )\n    ax.axvline(1, ymin=0.0, ymax=0.72, color=GREY, lw=1.0, ls="--")\n    ax.scatter(values, y, s=sizes, c=colors, edgecolor=INK, linewidth=0.55, zorder=3)\n\n    summary_y = len(frame) + 0.4\n    lo, hi = result["cluster_boot_ci"]\n    ax.axhline(len(frame) + 0.10, color="#d5d9dd", lw=0.9)\n    ax.errorbar(\n        result["or_mh"],\n        summary_y,\n        xerr=[[result["or_mh"] - lo], [hi - result["or_mh"]]],\n        fmt="D",\n        color=INK,\n        ecolor=INK,\n        ms=6.5,\n        elinewidth=1.8,\n        capsize=3.5,\n        zorder=4,\n    )\n    ax.set_xscale("log")\n    ax.set_xlim(0.09, 90)\n    ax.set_xticks([0.1, 1, 10])\n    ax.set_xticklabels(["0.1", "1", "10"])\n    ax.set_yticks(list(y) + [summary_y])\n    labels = [f"{r}  ({int(n)})" for r, n in zip(frame["regulator"], frame["n_rev"])]\n    ax.set_yticklabels(labels + ["pooled"])\n    ax.get_yticklabels()[-1].set_fontweight("bold")\n    # Reserve a compact band above the pooled estimate for the frozen summary,\n    # without compressing the 11 regulator rows into overlapping tick labels.\n    ax.set_ylim(-0.8, summary_y + 4.2)\n    ax.set_xlabel("odds ratio for re-reversal in Arce\\nreversing versus stable edge")\n    ax.set_title("External edge recurrence", pad=7)\n    ax.text(\n        0.985,\n        0.985,\n        f"{result[\'rev_flip_rate\']:.1%} vs {result[\'stable_flip_rate\']:.1%}\\n"\n        f"MH OR {result[\'or_mh\']:.2f} [{lo:.2f}–{hi:.2f}]\\n"\n        f"LOO {result[\'loo_or_min\']:.2f}–{result[\'loo_or_max\']:.2f} • area ∝ n",\n        transform=ax.transAxes,\n        ha="right",\n        va="top",\n        color=INK,\n        bbox={"facecolor": "white", "edgecolor": "none", "pad": 1.0},\n    )\n    panel_tag(ax, "a", x=-0.16)\n    return frame\n\n\ndef panel_b_targets(\n    parent: mpl.axes.Axes,\n    concentration: dict[str, Any],\n    unanimity: dict[str, Any],\n) -> tuple[pd.DataFrame, pd.DataFrame]:\n    parent.set_axis_off()\n    panel_tag(parent, "b", x=-0.04, y=1.08)\n    parent.text(\n        0.50,\n        1.02,\n        "Target organisation\\n4,379 reversals • 2,577 targets",\n        transform=parent.transAxes,\n        ha="center",\n        va="bottom",\n        fontsize=10.2,\n        fontweight="bold",\n        color=INK,\n    )\n\n    left = parent.inset_axes([0.04, 0.15, 0.43, 0.59])\n    right = parent.inset_axes([0.58, 0.15, 0.39, 0.59])\n\n    thresholds = [2, 3, 5]\n    keys = ["ge2", "ge3", "ge5"]\n    observed = np.array([concentration["observed"][key] for key in keys], dtype=float)\n    null_mean = np.array([concentration["null"][key]["null_mean"] for key in keys], dtype=float)\n    null_low = np.array([concentration["null"][key]["null_95"][0] for key in keys], dtype=float)\n    null_high = np.array([concentration["null"][key]["null_95"][1] for key in keys], dtype=float)\n    xpos = np.arange(len(thresholds))\n\n    left.errorbar(\n        xpos - 0.08,\n        null_mean,\n        yerr=[null_mean - null_low, null_high - null_mean],\n        fmt="o",\n        color=GOLD,\n        ecolor=GOLD,\n        ms=6.2,\n        capsize=3,\n        lw=1.5,\n        label="degree-preserving null, mean + 95%",\n    )\n    left.plot(xpos + 0.08, observed, "o-", color=NAVY, ms=6.5, lw=1.4, label="observed")\n    left.set_yscale("log")\n    left.set_ylim(7, 1600)\n    left.set_yticks([10, 100, 1000])\n    left.set_yticklabels(["10", "100", "1,000"])\n    left.set_xticks(xpos)\n    left.set_xticklabels(["≥2\\np=.339", "≥3\\np=.0004", "≥5\\np=.0004"])\n    left.set_ylabel("target count (log)")\n    left.set_xlabel("reversals / target")\n    left.set_title(\n        "Concentration\\n"\n        f"maximum {concentration[\'observed\'][\'max\']} vs null 95% "\n        f"{concentration[\'null\'][\'max\'][\'null_95\'][0]:.0f}–"\n        f"{concentration[\'null\'][\'max\'][\'null_95\'][1]:.0f}",\n        fontsize=9.4,\n        pad=4,\n    )\n\n    direction_thresholds = [2, 3, 4]\n    direction_rows = [\n        unanimity["D1_conditional_on_target_sign_composition"][f"min_rev_{threshold}"]\n        for threshold in direction_thresholds\n    ]\n    direction_x = np.arange(len(direction_thresholds), dtype=float)\n    direction_observed = np.array(\n        [row["n_unanimous_observed"] / row["n_targets"] for row in direction_rows],\n        dtype=float,\n    )\n    direction_null = np.array([row["null_mean"] for row in direction_rows], dtype=float)\n    direction_low = np.array([row["null_q025"] for row in direction_rows], dtype=float)\n    direction_high = np.array([row["null_q975"] for row in direction_rows], dtype=float)\n    for index in range(len(direction_thresholds)):\n        right.plot(\n            [direction_x[index], direction_x[index]],\n            [direction_null[index], direction_observed[index]],\n            color="#aeb4ba",\n            lw=1.1,\n            zorder=1,\n        )\n    right.errorbar(\n        direction_x,\n        direction_null,\n        yerr=[direction_null - direction_low, direction_high - direction_null],\n        fmt="o",\n        color=GOLD,\n        ecolor=GOLD,\n        ms=6.0,\n        capsize=3,\n        elinewidth=1.6,\n        zorder=3,\n    )\n    right.plot(\n        direction_x,\n        direction_observed,\n        "o-",\n        color=NAVY,\n        ms=6.2,\n        lw=1.2,\n        zorder=4,\n    )\n    for index, (observed_fraction, null_fraction) in enumerate(\n        zip(direction_observed, direction_null)\n    ):\n        right.text(\n            direction_x[index],\n            observed_fraction + 0.026,\n            f"{observed_fraction:.1%}",\n            ha="center",\n            va="bottom",\n            fontweight="bold",\n            color=NAVY,\n        )\n        right.text(\n            direction_x[index],\n            null_fraction - 0.032,\n            f"{null_fraction:.1%}",\n            ha="center",\n            va="top",\n            color="#8a5e18",\n        )\n    right.set_xlim(-0.35, 2.35)\n    right.set_ylim(0.17, 0.79)\n    right.set_xticks(direction_x)\n    right.set_xticklabels(\n        [\n            f"≥{threshold}\\nn={row[\'n_targets\']}"\n            for threshold, row in zip(direction_thresholds, direction_rows)\n        ]\n    )\n    right.set_yticks([0.2, 0.4, 0.6])\n    right.set_yticklabels(["20%", "40%", "60%"])\n    right.set_xlabel("minimum reversals / target\\nall one-sided MC p=.0002")\n    right.set_title("Direction unanimity", fontsize=9.4, pad=4)\n\n    concentration_source = pd.DataFrame(\n        {\n            "threshold": thresholds,\n            "observed_targets": observed.astype(int),\n            "null_mean": null_mean,\n            "null_q025": null_low,\n            "null_q975": null_high,\n            "p_two_sided": [concentration["null"][key]["p_two_sided"] for key in keys],\n        }\n    )\n    unanimity_source = pd.DataFrame(\n        [\n            {\n                "minimum_reversals": threshold,\n                "eligible_targets": row["n_targets"],\n                "unanimous_targets": row["n_unanimous_observed"],\n                "observed_fraction": observed_fraction,\n                "null_mean": row["null_mean"],\n                "null_q025": row["null_q025"],\n                "null_q975": row["null_q975"],\n                "one_sided_mc_p": row["p"],\n                "n_permutations": unanimity["n_perm"],\n            }\n            for threshold, row, observed_fraction in zip(\n                direction_thresholds, direction_rows, direction_observed\n            )\n        ]\n    )\n    return concentration_source, unanimity_source\n\n\ndef panel_c_direction(ax: mpl.axes.Axes, frame: pd.DataFrame) -> None:\n    expected = {"lost_on_activation", "gained_on_activation", "regulator", "total_reversals"}\n    if not expected.issubset(frame.columns):\n        raise ValueError(f"all49 table lacks columns: {sorted(expected - set(frame.columns))}")\n    if len(frame) != 49:\n        raise ValueError(f"expected 49 enriched regulators, found {len(frame)}")\n    x = np.arange(len(frame))\n    ax.bar(x, frame["gained_on_activation"], color=GAINED, width=0.78, label="gained on activation")\n    ax.bar(x, -frame["lost_on_activation"], color=LOST, width=0.78, label="lost on activation")\n    ax.axhline(0, color=INK, lw=0.9)\n    ax.set_xlim(-0.8, len(frame) - 0.2)\n    bound = int(math.ceil(max(frame["lost_on_activation"].max(), frame["gained_on_activation"].max()) / 25) * 25)\n    ax.set_ylim(-bound, bound)\n    ticks = np.arange(-bound, bound + 1, 50)\n    ax.set_yticks(ticks)\n    ax.set_yticklabels([str(abs(int(value))) for value in ticks])\n    ax.set_ylabel("reversal edges")\n    ax.set_xticks(x)\n    ax.set_xticklabels([])\n    ax.set_title("All 49 enriched regulators: reversal direction and burden", pad=4)\n    ax.legend(loc="upper right", ncol=2, columnspacing=1.1, handlelength=1.2)\n    ax.text(\n        0.01,\n        0.03,\n        f"{int(frame[\'lost_on_activation\'].sum()):,} lost; "\n        f"{int(frame[\'gained_on_activation\'].sum()):,} gained; "\n        f"{int(frame[\'total_reversals\'].sum()):,} reversals",\n        transform=ax.transAxes,\n        va="bottom",\n        color=INK,\n        bbox=dict(facecolor="white", edgecolor="none", alpha=0.88, pad=1.5),\n    )\n    one_direction = frame.loc[\n        (frame["lost_on_activation"] == 0) | (frame["gained_on_activation"] == 0), "regulator"\n    ].tolist()\n    ax.text(\n        0.99,\n        0.03,\n        "one-direction carriers: " + ", ".join(one_direction),\n        transform=ax.transAxes,\n        ha="right",\n        va="bottom",\n        color=GREY,\n        bbox=dict(facecolor="white", edgecolor="none", alpha=0.88, pad=1.5),\n    )\n    panel_tag(ax, "c", x=-0.035, y=1.10)\n\n\ndef normalize_programme_schema(programmes: pd.DataFrame, regulators: Iterable[str]) -> pd.DataFrame:\n    """Accept the frozen long table while failing on any ambiguous count column."""\n    rename = {\n        "program": "programme",\n        "program_name": "programme",\n        "programme_name": "programme",\n        "lost": "lost_on_activation",\n        "gained": "gained_on_activation",\n        "lost_count": "lost_on_activation",\n        "gained_count": "gained_on_activation",\n    }\n    programmes = programmes.rename(columns={k: v for k, v in rename.items() if k in programmes.columns})\n    required = {"regulator", "programme", "lost_on_activation", "gained_on_activation"}\n    if not required.issubset(programmes.columns):\n        raise ValueError(\n            "programme table must be long-form with columns " + ", ".join(sorted(required))\n        )\n    programmes = programmes[\n        ["regulator", "programme", "lost_on_activation", "gained_on_activation"]\n    ].copy()\n    programmes["regulator"] = programmes["regulator"].astype(str)\n    programmes["programme"] = programmes["programme"].astype(str)\n    programmes["lost_on_activation"] = programmes["lost_on_activation"].astype(int)\n    programmes["gained_on_activation"] = programmes["gained_on_activation"].astype(int)\n    if programmes.duplicated(["regulator", "programme"]).any():\n        raise ValueError("duplicate regulator-programme rows")\n    expected_regulators = list(regulators)\n    if set(programmes["regulator"]) != set(expected_regulators):\n        raise ValueError("programme table regulator set does not equal the frozen all-49 set")\n    if set(programmes["programme"]) != set(PROGRAMME_ORDER):\n        raise ValueError(\n            f"programme categories differ: observed={sorted(programmes[\'programme\'].unique())}"\n        )\n    full_index = pd.MultiIndex.from_product(\n        [expected_regulators, PROGRAMME_ORDER], names=["regulator", "programme"]\n    )\n    programmes = programmes.set_index(["regulator", "programme"]).reindex(full_index)\n    if programmes.isna().any().any():\n        raise ValueError("programme table is not a complete 49 x 7 grid")\n    return programmes.reset_index()\n\n\ndef draw_all49_block(\n    parent: mpl.axes.Axes,\n    bounds: tuple[float, float, float, float],\n    subset: pd.DataFrame,\n    lookup: pd.DataFrame,\n    rank_label: str,\n) -> None:\n    """Draw aligned direction bars and seven programme cells for one rank block."""\n    x0, y0, width, height = bounds\n    bars = parent.inset_axes([x0, y0, width * 0.63, height])\n    matrix = parent.inset_axes([x0 + width * 0.68, y0, width * 0.32, height])\n    y = np.arange(len(subset))\n\n    bars.barh(y, -subset["lost_on_activation"], color=LOST, height=0.67)\n    bars.barh(y, subset["gained_on_activation"], color=GAINED, height=0.67)\n    bars.axvline(0, color=INK, lw=0.75)\n    bars.set_xlim(-175, 175)\n    bars.set_ylim(len(subset) - 0.35, -0.65)\n    bars.set_yticks(y)\n    labels = []\n    one_direction = set(\n        subset.loc[\n            (subset["lost_on_activation"] == 0) | (subset["gained_on_activation"] == 0),\n            "regulator",\n        ]\n    )\n    for regulator in subset["regulator"].astype(str):\n        labels.append(("◇ " if regulator in one_direction else "") + regulator)\n    bars.set_yticklabels(labels)\n    for tick, regulator in zip(bars.get_yticklabels(), subset["regulator"].astype(str)):\n        if regulator in {"CCNC", "TADA2B", "SUPT7L", "AHR", "ARNT"}:\n            tick.set_fontweight("bold")\n    bars.set_xticks([])\n    bars.tick_params(axis="y", length=0, pad=2)\n    bars.grid(axis="x", color="#e4e6e8", lw=0.55, zorder=0)\n    bars.set_axisbelow(True)\n    bars.set_title(rank_label, loc="left", fontsize=9.4, pad=3)\n\n    for row, regulator in enumerate(subset["regulator"].astype(str)):\n        for col, programme in enumerate(PROGRAMME_ORDER):\n            record = lookup.loc[(regulator, programme)]\n            lost = int(record["lost_on_activation"])\n            gained = int(record["gained_on_activation"])\n            matrix.add_patch(\n                Rectangle(\n                    (col - 0.43, row - 0.39),\n                    0.86,\n                    0.37,\n                    facecolor=shade(LOST, count_bin(lost)),\n                    edgecolor="#d5d8db" if lost == 0 else "none",\n                    linewidth=0.25,\n                )\n            )\n            matrix.add_patch(\n                Rectangle(\n                    (col - 0.43, row + 0.02),\n                    0.86,\n                    0.37,\n                    facecolor=shade(GAINED, count_bin(gained)),\n                    edgecolor="#d5d8db" if gained == 0 else "none",\n                    linewidth=0.25,\n                )\n            )\n    matrix.set_xlim(-0.55, len(PROGRAMME_ORDER) - 0.45)\n    matrix.set_ylim(len(subset) - 0.35, -0.65)\n    matrix.set_yticks([])\n    matrix.set_xticks(np.arange(len(PROGRAMME_ORDER)))\n    matrix.set_xticklabels(["TCR", "Ag", "Str", "Pro", "Met", "Syn", "Out"], rotation=90)\n    matrix.tick_params(axis="x", bottom=False, top=True, labelbottom=False, labeltop=True, length=0, pad=3)\n    for spine in matrix.spines.values():\n        spine.set_visible(False)\n\n\ndef panel_c_all49(\n    parent: mpl.axes.Axes,\n    all49: pd.DataFrame,\n    programmes: pd.DataFrame,\n) -> pd.DataFrame:\n    """Complete 49-regulator landscape, split only for legibility."""\n    if len(all49) != 49:\n        raise ValueError(f"expected 49 enriched regulators, found {len(all49)}")\n    ordered = normalize_programme_schema(programmes, all49["regulator"].tolist())\n    lookup = ordered.set_index(["regulator", "programme"])\n    parent.set_axis_off()\n    panel_tag(parent, "c", x=-0.025, y=1.055)\n    parent.text(\n        0.5,\n        1.015,\n        "All 49 enriched regulators: reversal burden and target functional groups",\n        transform=parent.transAxes,\n        ha="center",\n        va="bottom",\n        fontsize=10.2,\n        fontweight="bold",\n        color=INK,\n    )\n    draw_all49_block(parent, (0.015, 0.11, 0.43, 0.78), all49.iloc[:25], lookup, "ranks 1–25 (linear; ±175)")\n    draw_all49_block(parent, (0.565, 0.11, 0.42, 0.78), all49.iloc[25:], lookup, "ranks 26–49 (same scale)")\n    parent.text(\n        0.50,\n        0.000,\n        "Bars: 1,154 lost / 921 gained; cells upper/lower; bins 0, 1–2, 3–5, 6–10, >10; ◇ one-direction.\\n"\n        "Six functional groups cover 304/2,075 edges; 1,771 (85.3%) outside; groups overlap.",\n        transform=parent.transAxes,\n        ha="center",\n        va="bottom",\n        color=GREY,\n    )\n    return ordered\n\n\ndef count_bin(value: int) -> int:\n    if value <= 0:\n        return 0\n    if value <= 2:\n        return 1\n    if value <= 5:\n        return 2\n    if value <= 10:\n        return 3\n    return 4\n\n\ndef shade(base: str, level: int) -> tuple[float, float, float, float]:\n    rgba = mpl.colors.to_rgba(base)\n    alpha = [0.0, 0.28, 0.48, 0.70, 0.95][level]\n    return (rgba[0], rgba[1], rgba[2], alpha)\n\n\ndef panel_d_programmes(\n    ax: mpl.axes.Axes,\n    programmes: pd.DataFrame,\n    all49: pd.DataFrame,\n) -> pd.DataFrame:\n    ordered = normalize_programme_schema(programmes, all49["regulator"].tolist())\n    lookup = ordered.set_index(["regulator", "programme"])\n    nreg = len(all49)\n    for x, regulator in enumerate(all49["regulator"]):\n        for y, programme in enumerate(PROGRAMME_ORDER):\n            record = lookup.loc[(regulator, programme)]\n            lost = int(record["lost_on_activation"])\n            gained = int(record["gained_on_activation"])\n            ax.add_patch(\n                Rectangle(\n                    (x - 0.43, y - 0.40),\n                    0.86,\n                    0.38,\n                    facecolor=shade(LOST, count_bin(lost)),\n                    edgecolor="#d5d8db" if lost == 0 else "none",\n                    linewidth=0.25,\n                )\n            )\n            ax.add_patch(\n                Rectangle(\n                    (x - 0.43, y + 0.02),\n                    0.86,\n                    0.38,\n                    facecolor=shade(GAINED, count_bin(gained)),\n                    edgecolor="#d5d8db" if gained == 0 else "none",\n                    linewidth=0.25,\n                )\n            )\n\n    ax.set_xlim(-0.7, nreg - 0.3)\n    ax.set_ylim(len(PROGRAMME_ORDER) - 0.45, -0.55)\n    ax.set_yticks(np.arange(len(PROGRAMME_ORDER)))\n    ax.set_yticklabels([PROGRAMME_LABELS[value] for value in PROGRAMME_ORDER])\n    ax.set_xticks(np.arange(nreg))\n    ax.set_xticklabels(all49["regulator"], rotation=90, ha="center", va="top")\n    for tick, regulator in zip(ax.get_xticklabels(), all49["regulator"]):\n        if regulator in {"CCNC", "TADA2B", "SUPT7L", "AHR", "ARNT"}:\n            tick.set_fontweight("bold")\n            tick.set_color(INK)\n    ax.tick_params(axis="x", length=0, pad=2)\n    ax.tick_params(axis="y", length=0)\n    for spine in ax.spines.values():\n        spine.set_visible(False)\n    ax.set_title("Selected canonical target programmes across the complete 49-regulator family", pad=4)\n    ax.text(\n        0.01,\n        1.01,\n        "upper red half = lost; lower teal half = gained; raw edge-count bins: 0, 1–2, 3–5, 6–10, >10",\n        transform=ax.transAxes,\n        ha="left",\n        va="bottom",\n        color=GREY,\n    )\n    ax.text(\n        0.99,\n        1.01,\n        "multi-label membership; unclassified is the complement",\n        transform=ax.transAxes,\n        ha="right",\n        va="bottom",\n        color=GREY,\n    )\n    panel_tag(ax, "d", x=-0.035, y=1.13)\n    return ordered\n\n\ndef shared_wide_to_matrix(\n    frame: pd.DataFrame, regulators: list[str]\n) -> tuple[np.ndarray, list[str]]:\n    columns: list[str] = []\n    values: list[np.ndarray] = []\n    for regulator in regulators:\n        for state, suffix in [("Rest", "lfc_Rest"), ("48 h", "lfc_Stim48")]:\n            column = f"{regulator}_{suffix}"\n            if column not in frame.columns:\n                raise ValueError(f"shared-target table lacks {column}")\n            columns.append(f"{regulator}\\n{state}")\n            values.append(frame[column].to_numpy(float))\n    return np.column_stack(values), columns\n\n\ndef draw_shared_heatmap(\n    ax: mpl.axes.Axes,\n    frame: pd.DataFrame,\n    regulators: list[str],\n    title: str,\n    norm: TwoSlopeNorm,\n    marked: dict[str, str] | None = None,\n) -> mpl.image.AxesImage:\n    matrix, _ = shared_wide_to_matrix(frame, regulators)\n    image = ax.imshow(matrix, cmap="RdBu_r", norm=norm, aspect="auto", interpolation="nearest")\n    ax.set_xticks(np.arange(matrix.shape[1]))\n    ax.set_xticklabels([value for _ in regulators for value in ("R", "48 h")])\n    ax.tick_params(axis="x", bottom=False, top=True, labelbottom=False, labeltop=True, pad=2)\n    if len(regulators) == 3:\n        # Small, symmetric offsets give the long TADA2B label a real printed\n        # gap from both neighbours while keeping each heading over its pair.\n        header_positions = [0.35, 2.65, 4.75]\n    else:\n        header_positions = [index * 2 + 0.5 for index in range(len(regulators))]\n    for index, regulator in enumerate(regulators):\n        ax.text(\n            header_positions[index],\n            1.10,\n            regulator,\n            transform=ax.get_xaxis_transform(),\n            ha="center",\n            va="bottom",\n            fontsize=9.0,\n            fontweight="bold",\n            color=INK,\n            clip_on=False,\n        )\n    for boundary in range(1, len(regulators)):\n        ax.axvline(boundary * 2 - 0.5, color="#ffffff", lw=1.3, zorder=3)\n    ylabels: list[str] = []\n    for target in frame["target"].astype(str):\n        prefix = "" if marked is None or target not in marked else marked[target]\n        ylabels.append(prefix + target)\n    ax.set_yticks(np.arange(len(frame)))\n    ax.set_yticklabels(ylabels)\n    if marked:\n        for tick, target in zip(ax.get_yticklabels(), frame["target"].astype(str)):\n            if target in marked:\n                tick.set_fontweight("bold")\n    for row in range(matrix.shape[0]):\n        for col in range(matrix.shape[1]):\n            value = matrix[row, col]\n            symbol = "+" if value > 0 else "−"\n            ax.text(\n                col,\n                row,\n                symbol,\n                ha="center",\n                va="center",\n                fontsize=9,\n                fontweight="bold",\n                color="white" if abs(value) > 0.55 * norm.vmax else INK,\n            )\n    ax.set_title(title, fontsize=9.4, pad=38)\n    for spine in ax.spines.values():\n        spine.set_linewidth(0.6)\n        spine.set_color("#a7adb2")\n    return image\n\n\ndef panel_e_zoom(\n    parent: mpl.axes.Axes,\n    cofactor: pd.DataFrame,\n    sensor: pd.DataFrame,\n) -> tuple[pd.DataFrame, pd.DataFrame]:\n    parent.set_axis_off()\n    panel_tag(parent, "e", x=-0.05, y=1.08)\n    parent.text(\n        0.50,\n        1.02,\n        "Post-hoc zooms retain every shared reversal target",\n        transform=parent.transAxes,\n        ha="center",\n        va="bottom",\n        fontsize=10.2,\n        fontweight="bold",\n        color=INK,\n    )\n    parent.text(\n        0.99,\n        1.02,\n        "hypothesis-generating",\n        transform=parent.transAxes,\n        ha="right",\n        va="bottom",\n        color="#7a5c00",\n        bbox=dict(facecolor="#fff4cc", edgecolor="none", pad=1.5),\n    )\n\n    left = parent.inset_axes([0.17, 0.18, 0.38, 0.73])\n    right = parent.inset_axes([0.70, 0.18, 0.27, 0.73])\n    max_abs = 0.0\n    for frame, regulators in [(cofactor, ["CCNC", "TADA2B", "SUPT7L"]), (sensor, ["AHR", "ARNT"])]:\n        matrix, _ = shared_wide_to_matrix(frame, regulators)\n        max_abs = max(max_abs, float(np.abs(matrix).max()))\n    norm = TwoSlopeNorm(vmin=-max_abs, vcenter=0.0, vmax=max_abs)\n    marked = {\n        "IL2RA": "† ",\n        "DDIT4": "† ",\n        "BCL2L1": "† ",\n        "PSMB9": "‡ ",\n        "PSME1": "‡ ",\n        "PSME2": "‡ ",\n    }\n    image = draw_shared_heatmap(\n        left,\n        cofactor,\n        ["CCNC", "TADA2B", "SUPT7L"],\n        "cofactor trio (16 shared targets)",\n        norm,\n        marked,\n    )\n    draw_shared_heatmap(\n        right,\n        sensor,\n        ["AHR", "ARNT"],\n        "sensor pair (17)",\n        norm,\n    )\n    cax = parent.inset_axes([0.18, 0.055, 0.78, 0.035])\n    colorbar = parent.figure.colorbar(image, cax=cax, orientation="horizontal")\n    colorbar.set_label("net knockdown coefficient (log2 fold change); sign is printed in every tile")\n    colorbar.outline.set_linewidth(0.5)\n    parent.text(\n        0.17,\n        0.115,\n        "† IL2RA / stress-survival examples     ‡ immunoproteasome examples",\n        transform=parent.transAxes,\n        ha="left",\n        va="bottom",\n        color=GREY,\n    )\n    return cofactor, sensor\n\n\ndef cofactor_target_markers(\n    memberships: pd.DataFrame, targets: Iterable[str]\n) -> dict[str, str]:\n    """Derive markers for every displayed target represented in the programme table."""\n    wanted = set(targets)\n    subset = memberships.loc[\n        memberships["target"].isin(wanted)\n        & memberships["regulator"].isin(["CCNC", "TADA2B", "SUPT7L"])\n        & ~memberships["is_unclassified_complement"].astype(bool)\n    ]\n    by_target = subset.groupby("target")["programme"].agg(lambda values: set(values))\n    markers: dict[str, str] = {}\n    for target, programmes in by_target.items():\n        if "antigen_processing_proteasome" in programmes:\n            markers[str(target)] = "‡ "\n        elif {"tcr_cytokine_signalling", "stress_survival"} & programmes:\n            markers[str(target)] = "† "\n        else:\n            raise AssertionError(\n                f"programme-mapped cofactor target has no declared marker class: "\n                f"{target} -> {sorted(programmes)}"\n            )\n    return markers\n\n\ndef panel_d_cofactor(\n    ax: mpl.axes.Axes,\n    frame: pd.DataFrame,\n    norm: TwoSlopeNorm,\n    memberships: pd.DataFrame,\n) -> mpl.image.AxesImage:\n    markers = cofactor_target_markers(memberships, frame["target"].astype(str))\n    image = draw_shared_heatmap(\n        ax,\n        frame,\n        ["CCNC", "TADA2B", "SUPT7L"],\n        "Cofactor trio\\n16 shared targets (post-hoc)",\n        norm,\n        markers,\n    )\n    ax.set_xlabel("† TCR/stress    ‡ antigen/proteasome", labelpad=3)\n    panel_tag(ax, "d", x=-0.12, y=1.16)\n    return image\n\n\ndef panel_e_sensor(\n    ax: mpl.axes.Axes,\n    frame: pd.DataFrame,\n    norm: TwoSlopeNorm,\n) -> mpl.image.AxesImage:\n    image = draw_shared_heatmap(\n        ax,\n        frame,\n        ["AHR", "ARNT"],\n        "AHR–ARNT sensor pair\\n17 shared targets (post-hoc)",\n        norm,\n    )\n    ax.set_xlabel("all shared targets shown", labelpad=3)\n    panel_tag(ax, "e", x=-0.12, y=1.16)\n    return image\n\n\ndef add_box(\n    ax: mpl.axes.Axes,\n    xy: tuple[float, float],\n    width: float,\n    height: float,\n    text: str,\n    face: str,\n    edge: str = "#80868c",\n    fontsize: float = 9.0,\n    weight: str = "normal",\n) -> FancyBboxPatch:\n    patch = FancyBboxPatch(\n        xy,\n        width,\n        height,\n        boxstyle="round,pad=0.012,rounding_size=0.015",\n        facecolor=face,\n        edgecolor=edge,\n        linewidth=0.8,\n        transform=ax.transAxes,\n    )\n    ax.add_patch(patch)\n    ax.text(\n        xy[0] + width / 2,\n        xy[1] + height / 2,\n        text,\n        transform=ax.transAxes,\n        ha="center",\n        va="center",\n        fontsize=fontsize,\n        fontweight=weight,\n        color=INK,\n    )\n    return patch\n\n\ndef add_arrow(\n    ax: mpl.axes.Axes,\n    start: tuple[float, float],\n    end: tuple[float, float],\n    dashed: bool = False,\n) -> None:\n    patch = FancyArrowPatch(\n        start,\n        end,\n        transform=ax.transAxes,\n        arrowstyle="-|>",\n        mutation_scale=10,\n        lw=1.0,\n        color=GREY,\n        linestyle="--" if dashed else "-",\n    )\n    ax.add_patch(patch)\n\n\ndef visible_text(fig: mpl.figure.Figure) -> list[mpl.text.Text]:\n    return [artist for artist in fig.findobj(mpl.text.Text) if artist.get_visible() and artist.get_text()]\n\n\ndef text_bbox_collisions(\n    artists: list[mpl.text.Text], renderer: Any, minimum_overlap_px: float = 1.0\n) -> list[tuple[str, str]]:\n    """Return every pair of visible text boxes with material intersection."""\n    boxes = [(artist, artist.get_window_extent(renderer=renderer)) for artist in artists]\n    collisions: list[tuple[str, str]] = []\n    for index, (left_artist, left_box) in enumerate(boxes):\n        for right_artist, right_box in boxes[index + 1 :]:\n            overlap_x = min(left_box.x1, right_box.x1) - max(left_box.x0, right_box.x0)\n            overlap_y = min(left_box.y1, right_box.y1) - max(left_box.y0, right_box.y0)\n            if overlap_x > minimum_overlap_px and overlap_y > minimum_overlap_px:\n                collisions.append((left_artist.get_text(), right_artist.get_text()))\n    return collisions\n\n\ndef plotted_values_outside_axes(fig: mpl.figure.Figure) -> list[str]:\n    """Audit line, scatter and error-bar coordinates against final axis limits."""\n    failures: list[str] = []\n\n    def check(ax: mpl.axes.Axes, xvalues: Any, yvalues: Any, label: str) -> None:\n        xarray = np.asarray(xvalues, dtype=float).reshape(-1)\n        yarray = np.asarray(yvalues, dtype=float).reshape(-1)\n        if xarray.size != yarray.size:\n            return\n        finite = np.isfinite(xarray) & np.isfinite(yarray)\n        if not finite.any():\n            return\n        xarray, yarray = xarray[finite], yarray[finite]\n        xmin, xmax = sorted(ax.get_xlim())\n        ymin, ymax = sorted(ax.get_ylim())\n        xtol = max(abs(xmax - xmin), 1.0) * 1e-8\n        ytol = max(abs(ymax - ymin), 1.0) * 1e-8\n        if (\n            (xarray < xmin - xtol).any()\n            or (xarray > xmax + xtol).any()\n            or (yarray < ymin - ytol).any()\n            or (yarray > ymax + ytol).any()\n        ):\n            failures.append(label)\n\n    for axis_index, ax in enumerate(fig.axes):\n        for line_index, line in enumerate(ax.lines):\n            # axhline/axvline use blended data/axes transforms; their axes-space\n            # 0..1 coordinate is not a plotted datum and must not be compared\n            # with a log/data limit.  Ordinary plotted lines use transData.\n            if line.get_transform() is ax.transData:\n                check(\n                    ax,\n                    line.get_xdata(orig=False),\n                    line.get_ydata(orig=False),\n                    f"axis{axis_index}:line{line_index}",\n                )\n        for collection_index, collection in enumerate(ax.collections):\n            # PathCollection offsets are scatter data.  LineCollection offsets\n            # default to a non-data [0, 0] sentinel, so audit its segments only.\n            if isinstance(collection, mpl.collections.PathCollection):\n                offsets = np.asarray(collection.get_offsets())\n                if offsets.ndim == 2 and offsets.shape[1] == 2 and len(offsets):\n                    check(ax, offsets[:, 0], offsets[:, 1], f"axis{axis_index}:collection{collection_index}:offsets")\n            if isinstance(collection, mpl.collections.LineCollection):\n                segments = collection.get_segments()\n                if segments:\n                    points = np.concatenate([np.asarray(segment) for segment in segments if len(segment)], axis=0)\n                    if points.ndim == 2 and points.shape[1] == 2:\n                        check(ax, points[:, 0], points[:, 1], f"axis{axis_index}:collection{collection_index}:segments")\n    return failures\n\n\ndef write_dataframe(frame: pd.DataFrame, path: Path) -> None:\n    temp = path.with_suffix(path.suffix + ".tmp")\n    frame.to_csv(temp, index=False, quoting=csv.QUOTE_MINIMAL)\n    os.replace(temp, path)\n\n\ndef write_text(text: str, path: Path) -> None:\n    temp = path.with_suffix(path.suffix + ".tmp")\n    temp.write_text(text, encoding="utf-8")\n    os.replace(temp, path)\n\n\ndef write_json(payload: dict[str, Any], path: Path) -> None:\n    temp = path.with_suffix(path.suffix + ".tmp")\n    temp.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\\n", encoding="utf-8")\n    os.replace(temp, path)\n\n\ndef build(output_dir: Path) -> None:\n    require_inputs()\n    if False:\n        raise FileExistsError(f"refusing to overwrite existing output directory: {output_dir}")\n    output_dir.parent.mkdir(parents=True, exist_ok=True)\n    staging = Path(tempfile.mkdtemp(prefix=f".{output_dir.name}.staging-", dir=output_dir.parent))\n    try:\n        arce = read_json(INPUTS["arce"])\n        concentration = read_json(INPUTS["concentration"])\n        unanimity = read_json(INPUTS["unanimity"])\n        programme_manifest = read_json(INPUTS["programme_manifest"])\n        bridge_manifest = read_json(INPUTS["bridge_manifest"])\n        all49 = pd.read_csv(INPUTS["all49"]).sort_values("display_rank").reset_index(drop=True)\n        programmes = pd.read_csv(INPUTS["programmes"])\n        memberships = pd.read_csv(INPUTS["programme_memberships"])\n        cofactor = pd.read_csv(INPUTS["cofactor"]).sort_values("display_rank").reset_index(drop=True)\n        sensor = pd.read_csv(INPUTS["sensor"]).sort_values("display_rank").reset_index(drop=True)\n\n        if list(all49["display_rank"]) != list(range(1, 50)):\n            raise ValueError("all49 display ranks are not exactly 1..49")\n        if int(all49["total_reversals"].sum()) != 2075:\n            raise ValueError("all49 reversal total changed")\n        if len(cofactor) != 16 or len(sensor) != 17:\n            raise ValueError("shared-target case-study row counts changed")\n        if len(programmes) != 343 or len(memberships) != 2141:\n            raise ValueError("all-49 programme source row counts changed")\n        membership_keys = ["regulator_ensg", "target_ensg"]\n        unique_membership_edges = memberships.drop_duplicates(membership_keys)\n        classified_edges = memberships.loc[\n            ~memberships["is_unclassified_complement"].astype(bool)\n        ].drop_duplicates(membership_keys)\n        unclassified_edges = memberships.loc[\n            memberships["is_unclassified_complement"].astype(bool)\n        ].drop_duplicates(membership_keys)\n        if (len(unique_membership_edges), len(classified_edges), len(unclassified_edges)) != (\n            2075,\n            304,\n            1771,\n        ):\n            raise ValueError("programme coverage assertions changed")\n        expected_table_hashes = {\n            "all49_target_programme_counts.csv": sha256(INPUTS["programmes"]),\n            "all49_target_programme_memberships.csv": sha256(INPUTS["programme_memberships"]),\n        }\n        for table_name, observed_hash in expected_table_hashes.items():\n            manifest_hash = programme_manifest["tables"][table_name]["sha256"]\n            if observed_hash != manifest_hash:\n                raise ValueError(f"programme source hash mismatch for {table_name}")\n        if programme_manifest.get("status") not in {\n            "DESCRIPTIVE_SOURCE_TABLES_ONLY",\n            "PASS",\n            "FROZEN_DESCRIPTIVE",\n            "DESCRIPTIVE_MULTI_LABEL_SOURCE_TABLES",\n        }:\n            raise ValueError("programme manifest is not marked as a descriptive passed/frozen asset")\n\n        bridge_tables = {\n            "all49_enriched_regulators.csv": INPUTS["all49"],\n            "shared_reversal_targets_CCNC_TADA2B_SUPT7L.csv": INPUTS["cofactor"],\n            "shared_reversal_targets_AHR_ARNT.csv": INPUTS["sensor"],\n        }\n        for table_name, table_path in bridge_tables.items():\n            observed_hash = sha256(table_path)\n            manifest_hash = bridge_manifest["tables"][table_name]["sha256"]\n            if observed_hash != manifest_hash:\n                raise ValueError(f"biological-bridge source hash mismatch for {table_name}")\n        if bridge_manifest.get("status") != "DESCRIPTIVE_SOURCE_TABLES_ONLY":\n            raise ValueError("biological-bridge manifest has an unexpected status")\n\n        configure_style()\n        fig = plt.figure(figsize=(SOURCE_WIDTH_IN, SOURCE_HEIGHT_IN), facecolor="white")\n        grid = fig.add_gridspec(\n            3,\n            6,\n            height_ratios=[2.90, 5.60, 3.05],\n            left=0.130,\n            right=0.980,\n            top=0.965,\n            bottom=0.075,\n            hspace=0.38,\n            wspace=0.55,\n        )\n        top_grid = grid[0, :].subgridspec(\n            1, 2, width_ratios=[1.0, 1.45], wspace=0.30\n        )\n        ax_a = fig.add_subplot(top_grid[0, 0])\n        ax_b = fig.add_subplot(top_grid[0, 1])\n        ax_c = fig.add_subplot(grid[1, :])\n        bottom_grid = grid[2, :].subgridspec(\n            1, 2, width_ratios=[1.18, 1.00], wspace=0.42\n        )\n        ax_d = fig.add_subplot(bottom_grid[0, 0])\n        ax_e = fig.add_subplot(bottom_grid[0, 1])\n\n        source_a = panel_a_external(ax_a, arce)\n        source_b_conc, source_b_unanimity = panel_b_targets(ax_b, concentration, unanimity)\n        source_c_programmes = panel_c_all49(ax_c, all49, programmes)\n        cofactor_matrix, _ = shared_wide_to_matrix(cofactor, ["CCNC", "TADA2B", "SUPT7L"])\n        sensor_matrix, _ = shared_wide_to_matrix(sensor, ["AHR", "ARNT"])\n        max_abs = max(float(np.abs(cofactor_matrix).max()), float(np.abs(sensor_matrix).max()))\n        shared_norm = TwoSlopeNorm(vmin=-max_abs, vcenter=0.0, vmax=max_abs)\n        image = panel_d_cofactor(ax_d, cofactor, shared_norm, memberships)\n        panel_e_sensor(ax_e, sensor, shared_norm)\n        cbar_ax = fig.add_axes([0.155, 0.030, 0.440, 0.012])\n        colorbar = fig.colorbar(image, cax=cbar_ax, orientation="horizontal")\n        colorbar.set_ticks([-1.5, 0.0, 1.5])\n        colorbar.set_label("net knockdown coefficient (log2 fold change)", labelpad=2)\n        colorbar.ax.xaxis.set_label_position("top")\n        colorbar.ax.xaxis.set_ticks_position("bottom")\n        colorbar.outline.set_linewidth(0.5)\n\n        fig.canvas.draw()\n        texts = visible_text(fig)\n        renderer = fig.canvas.get_renderer()\n        figure_box = fig.bbox\n        outside: list[str] = []\n        tolerance_px = 1.0\n        for artist in texts:\n            box = artist.get_window_extent(renderer=renderer)\n            if (\n                box.x0 < figure_box.x0 - tolerance_px\n                or box.y0 < figure_box.y0 - tolerance_px\n                or box.x1 > figure_box.x1 + tolerance_px\n                or box.y1 > figure_box.y1 + tolerance_px\n            ):\n                outside.append(artist.get_text())\n        if outside:\n            raise RuntimeError(f"text extends beyond A4 canvas: {outside[:8]}")\n        collisions = text_bbox_collisions(texts, renderer)\n        if collisions:\n            raise RuntimeError(f"text bbox collisions detected: {collisions[:8]}")\n        outside_axes = plotted_values_outside_axes(fig)\n        if outside_axes:\n            raise RuntimeError(f"plotted numeric values outside final axis limits: {outside_axes[:8]}")\n        minimum_source = min(float(artist.get_fontsize()) for artist in texts)\n        minimum_print = minimum_source * (TARGET_WIDTH_MM / 25.4) / SOURCE_WIDTH_IN\n        if minimum_source + 1e-8 < MIN_SOURCE_FONT_PT:\n            offenders = [artist.get_text() for artist in texts if artist.get_fontsize() < MIN_SOURCE_FONT_PT]\n            raise RuntimeError(f"source font floor failed: {minimum_source:.2f} pt; {offenders[:8]}")\n        if minimum_print + 1e-8 < 7.0:\n            raise RuntimeError(f"print font floor failed: {minimum_print:.2f} pt")\n\n        pdf = staging / "Fig3_biological_bridge_candidate.pdf"\n        png = staging / "Fig3_biological_bridge_candidate.png"\n        fig.savefig(pdf, dpi=300, facecolor="white", transparent=False, bbox_inches=None)\n        fig.savefig(png, dpi=300, facecolor="white", transparent=False, bbox_inches=None)\n        plt.close(fig)\n        # Matplotlib emits an RGBA PNG even with transparent=False.  Strip the\n        # redundant alpha channel so the delivered raster is explicitly opaque.\n        rgb_temp = png.with_suffix(".rgb.tmp.png")\n        with Image.open(png) as raster:\n            raster.convert("RGB").save(rgb_temp, format="PNG", dpi=(300, 300))\n        os.replace(rgb_temp, png)\n\n        write_dataframe(source_a, staging / "source_panel_a_external_recurrence.csv")\n        write_dataframe(source_b_conc, staging / "source_panel_b_target_concentration.csv")\n        write_dataframe(source_b_unanimity, staging / "source_panel_b_target_unanimity.csv")\n        write_dataframe(all49, staging / "source_panel_c_all49_direction.csv")\n        write_dataframe(source_c_programmes, staging / "source_panel_c_all49_programmes.csv")\n        write_dataframe(cofactor, staging / "source_panel_d_cofactor_targets.csv")\n        write_dataframe(sensor, staging / "source_panel_e_sensor_targets.csv")\n\n        alt_text = (\n            "Five-panel Figure 3 candidate. Panel a shows that 241 reversal edges covered in "\n            "the Arce perturbation dataset re-reverse more often than 3,256 stable edges from "\n            "the same 11 regulators, with a pooled regulator-stratified odds ratio of 3.23. "\n            "Panel b shows concentration of 4,379 reversals on 2,577 targets relative to a "\n            "degree-preserving reference. Its direction panel carries forward the frozen target-conditioned "\n            "sequence: 69.3, 67.6 and 69.8 percent unanimity at minimum burdens of two, three and four, "\n            "against null means of 46.7, 33.1 and 25.4 percent. Panel c integrates "\n            "lost and gained reversal counts with six post-hoc unions of 19 canonical KEGG-Legacy "\n            "sets, fixed for this descriptive projection, and an "\n            "explicit outside-six complement for all 49 reversal-enriched regulators; most reversal "\n            "edges are outside the six programmes. Panels d and e show paired Rest and 48-hour net "\n            "knockdown coefficients for all 16 targets shared by CCNC, TADA2B and SUPT7L and all 17 "\n            "shared by AHR and ARNT, respectively. Exactly six of the 16 cofactor targets map to the "\n            "19-set dictionary; the remaining ten are retained and unclassified. No panel claims "\n            "target-level significance, direct binding, mediation, pathway "\n            "activation or suppression; the causal experiment remains prospective and is described in the text."\n        )\n        write_text(alt_text + "\\n", staging / "ALT_TEXT.md")\n\n        caption = (\n            "Figure 3 candidate | External recurrence and target organisation nominate state-remodelled "\n            "regulator programmes. (a) Regulator-specific odds ratios and the regulator-stratified pooled "\n            "estimate for re-reversal in the separate Arce perturbation dataset. The percentages are "\n            "coverage-conditional, not genome-wide recurrence rates. (b) Left, target reversal burden "\n            "against the existing degree-preserving null; right, target-conditioned unanimity at minimum "\n            "burdens of two, three and four reversals per target. The threshold sequence is a robustness "\n            "display; the minimum-two result is primary. The two displays use different nulls and answer "\n            "different questions. (c) Raw lost- and "\n            "gained-on-activation reversal counts integrated with membership in six post-hoc unions of "\n            "19 canonical KEGG-Legacy sets, fixed for this descriptive projection, for all 49 regulators "\n            "above the degree-matched expectation. "\n            "Membership is multi-label and outside-six is the complement; colours do not measure pathway "\n            "activity. (d,e) Exhaustive shared-target, post-hoc case studies for the CCNC-TADA2B-SUPT7L "\n            "cofactor trio and AHR-ARNT sensor pair. Exactly six of the 16 cofactor targets map to the "\n            "19-set dictionary; all ten unclassified targets remain visible. Tiles show net perturbation "\n            "coefficients, not target-level significance or direct regulation. The required causal "\n            "experiment is described prospectively in the Discussion, "\n            "not displayed as a result panel."\n        )\n        write_text(caption + "\\n", staging / "CAPTION_DRAFT.md")\n\n        output_hashes = {path.name: sha256(path) for path in sorted(staging.iterdir()) if path.is_file()}\n        manifest = {\n            "schema_version": "fig3-biological-bridge-candidate-v1",\n            "status": "DIAGNOSTIC_CANDIDATE_ONLY",\n            "claim_boundary": (\n                "Panels c-e are descriptive. No direct binding, mediation, pathway activation, pathway "\n                "suppression, fixed-margin two-step result, or regulator-specific motif p-value is shown."\n            ),\n            "canvas": {\n                "inches": [SOURCE_WIDTH_IN, SOURCE_HEIGHT_IN],\n                "a4_portrait": True,\n                "target_width_mm": TARGET_WIDTH_MM,\n                "minimum_source_font_pt": minimum_source,\n                "minimum_font_at_target_width_pt": minimum_print,\n                "opaque_background": True,\n                "pdf_fonttype": 42,\n                "text_outside_canvas": 0,\n                "text_text_bbox_collisions": 0,\n                "plotted_numeric_values_outside_axes": 0,\n            },\n            "assertions": {\n                "all49_regulators": len(all49),\n                "all49_reversals": int(all49["total_reversals"].sum()),\n                "all49_lost": int(all49["lost_on_activation"].sum()),\n                "all49_gained": int(all49["gained_on_activation"].sum()),\n                "cofactor_shared_targets": len(cofactor),\n                "sensor_shared_targets": len(sensor),\n                "failed_two_path_result_included": False,\n            },\n            "inputs": {\n                name: {"path": str(path.relative_to(ROOT)), "sha256": sha256(path)}\n                for name, path in INPUTS.items()\n            },\n            "programme_manifest_status": programme_manifest.get("status"),\n            "script": {\n                "path": str(Path(__file__).resolve().relative_to(ROOT)),\n                "sha256": sha256(Path(__file__).resolve()),\n            },\n            "outputs_before_manifest": output_hashes,\n            "software": {\n                "python": sys.version.split()[0],\n                "matplotlib": mpl.__version__,\n                "numpy": np.__version__,\n                "pandas": pd.__version__,\n            },\n        }\n        write_json(manifest, staging / "manifest.json")\n        pass\n        print(f"wrote diagnostic Figure 3 candidate: {output_dir}")\n        print(f"minimum font: {minimum_source:.2f} pt source; {minimum_print:.2f} pt at {TARGET_WIDTH_MM:.1f} mm")\n    except Exception:\n        if staging.exists():\n            pass\n        raise\n\n\ndef parse_args() -> argparse.Namespace:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUT)\n    return parser.parse_args()\n\n\nif __name__ == "__main__":\n    args = parse_args()\n    build(args.output_dir.resolve())\n'
