code_fig3_biological_bridge_r5_ahr_arce_candidate = '#!/usr/bin/env python3\n"""Render an immutable six-panel Figure 3 diagnostic candidate.\n\nThis presentation-only build combines two complementary regulator views:\n\n  a  the exact 532-edge high-magnitude reversal subnetwork used by the live\n     FigS7/Repository Figure R5, redrawn at panel scale without the exploratory\n     purple state-occupancy outlines;\n  b  the existing target-concentration and direction-unanimity displays;\n  c  the complete 49-regulator Fisher/BH-enriched family and its descriptive\n     target functional-group projection;\n  d  all 16 shared reversal targets of CCNC, TADA2B and SUPT7L; and\n  e  all 17 shared reversal targets of AHR and ARNT; and\n  f  the frozen regulator-stratified Arce external-recurrence comparison.\n\nNo statistical analysis, permutation or bootstrap is rerun.  The Arce panel\nreads the already-frozen summary JSON through the compact prior Figure 3\nhelper; it does not import the compute-heavy legacy ``fig7_arce`` module.  The\nR5 edge set is reconstructed from the\ncurrent identity-safe census and checked against the exact symbol-pair rule in\nthe source used by FigS7.  The five frozen panel-b/c source tables are retained\ninside the final audited bundle and copied byte-for-byte on any replay, so no\nsuperseded candidate directory is required.  The output directory is created\natomically and must not already exist.  Run this script through\nscripts/run_memory_guarded.py.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nfrom pathlib import Path\nimport shutil\nimport sys\nimport tempfile\nfrom typing import Any, Iterable\n\nimport matplotlib\n\nmatplotlib.use("Agg")\nimport matplotlib as mpl\nimport matplotlib.pyplot as plt\nfrom matplotlib.collections import LineCollection\nfrom matplotlib.colors import TwoSlopeNorm\nfrom matplotlib.lines import Line2D\nimport numpy as np\nimport pandas as pd\nfrom PIL import Image, __version__ as PILLOW_VERSION\n\n\nROOT = Path(__file__).resolve().parents[1]\nsys.path.insert(0, str(ROOT / "scripts"))\nimport fig3_biological_bridge_candidate as bridge  # noqa: E402\nimport figstyle as S  # noqa: E402\n\n\nMASTER_EDGES = ROOT / "data/census/census_master_edges.csv.gz"\nMASTER_MANIFEST = ROOT / "data/census/census_master_manifest.json"\nFIGS7_SYMBOL_EDGES = ROOT / "data/census/sign_inverting_edges.csv"\nFIGS7_RENDERER = ROOT / "scripts/fig5_network.py"\nSTYLE_SOURCE = ROOT / "scripts/figstyle.py"\nINDEPENDENT_NETWORK_REPORT = ROOT / "network_census/build_report.json"\nFIGS7_PDF = ROOT / "figures/FigS7.pdf"\nFIGS7_PNG = ROOT / "figures/FigS7.png"\nFIG4_EDGE_SUMMARY = (\n    ROOT\n    / "data/response_shape/production_v5_1/edge_continuous_summary_v5_1.parquet"\n)\nFIG4_REVERSAL_CENSUS = (\n    ROOT\n    / "data/response_shape/production_v5_1/reversal_census_v5_1.parquet"\n)\nFIG4_RENDERER = ROOT / "scripts/response_shape/fig4_presentation_v5_1.py"\nDEFAULT_OUT = (\n    ROOT\n    / "data/figure_provenance/fig3_biological_bridge_r5_ahr_arce_candidate_v4"\n)\n\nSOURCE_WIDTH_IN = 210.0 / 25.4\nSOURCE_HEIGHT_IN = 297.0 / 25.4\nTARGET_WIDTH_MM = 165.1\nMIN_SOURCE_FONT_PT = 9.0\nBARYCENTRE_ITERATIONS = 60\nBOTTOM_WIDTH_RATIOS = (1.00, 0.70, 1.35)\nBOTTOM_WSPACE = 0.50\nCOLORBAR_RECT = (0.180, 0.020, 0.370, 0.012)\nMIN_CROSS_AXIS_TEXT_GAP_PT = 2.0\nFIG4_TOP_TARGET_COUNT = 28\nFIG4_MIN_TARGET_EDGES = 3\nEXPECTED_FIG4_COFACTOR_OVERLAP = {\n    "BCL2L1",\n    "DDIT4",\n    "GPR108",\n    "IL2RA",\n    "PSMB9",\n    "PSME1",\n    "PSME2",\n    "SDCBP",\n}\n\n# Every data/reference input used by the renderer is archived in the candidate\n# bundle.  The renderer still verifies each against its live source before the\n# atomic promotion, but no retired figure bundle is an input.\nBUNDLED_INPUTS = {\n    "census_master_edges.csv.gz": MASTER_EDGES,\n    "census_master_manifest.json": MASTER_MANIFEST,\n    "figs7_symbol_edges.csv": FIGS7_SYMBOL_EDGES,\n    "independent_network_build_report.json": INDEPENDENT_NETWORK_REPORT,\n    "fig4_edge_continuous_summary.parquet": FIG4_EDGE_SUMMARY,\n    "fig4_reversal_census.parquet": FIG4_REVERSAL_CENSUS,\n    "arce_validation_results.json": bridge.INPUTS["arce"],\n    "target_concentration_results.json": bridge.INPUTS["concentration"],\n    "target_unanimity_results.json": bridge.INPUTS["unanimity"],\n    "all49_enriched_regulators.csv": bridge.INPUTS["all49"],\n    "all49_target_programme_counts.csv": bridge.INPUTS["programmes"],\n    "all49_target_programme_memberships.csv": bridge.INPUTS["programme_memberships"],\n    "all49_target_programme_manifest.json": bridge.INPUTS["programme_manifest"],\n    "shared_reversal_targets_CCNC_TADA2B_SUPT7L.csv": bridge.INPUTS["cofactor"],\n    "shared_reversal_targets_AHR_ARNT.csv": bridge.INPUTS["sensor"],\n    "fig3_biological_bridge_manifest.json": bridge.INPUTS["bridge_manifest"],\n    "reference_FigS7.pdf": FIGS7_PDF,\n    "reference_FigS7.png": FIGS7_PNG,\n}\nBUNDLED_RENDERERS = {\n    "fig3_biological_bridge_r5_ahr_arce_candidate.py": Path(__file__).resolve(),\n    "fig3_biological_bridge_candidate.py": Path(bridge.__file__).resolve(),\n    "figstyle.py": STYLE_SOURCE,\n    "fig5_network.py": FIGS7_RENDERER,\n    "fig4_presentation_v5_1.py": FIG4_RENDERER,\n}\n\nR5_MAGNITUDE_THRESHOLD = 0.5\nR5_EXPECTED = {\n    "edges": 532,\n    "regulators": 170,\n    "targets": 382,\n    "lost": 318,\n    "gained": 214,\n}\nCASE_LABELS = ("CCNC", "TADA2B", "SUPT7L", "AHR", "ARNT")\nEFFECTOR_TARGETS = {\n    "GZMA",\n    "GZMB",\n    "GNLY",\n    "PRF1",\n    "IFNG",\n    "TNF",\n    "NKG7",\n    "CCL5",\n    "CCL4",\n    "CCL3",\n    "CCR5",\n    "CCR1",\n    "CCR7",\n    "CCR2",\n    "IL2",\n    "IL2RA",\n    "IL2RB",\n    "CD69",\n    "CTLA4",\n    "IL2RG",\n    "SELL",\n    "TBX21",\n    "KLRB1",\n    "XCL1",\n    "XCL2",\n}\n\nNETWORK_REGULATOR = "#33475b"\nNETWORK_TARGET = "#c7ccd1"\nNETWORK_TARGET_EDGE = "#9aa0a6"\nFAMILY_OUTLINE = "#d59b32"\nEFFECTOR_FILL = "#f2c14e"\n\n\ndef sha256(path: Path) -> str:\n    # Chain modules are embedded in this single file, so their standalone\n    # .py sources no longer exist. Provenance hashes for absorbed sources are\n    # reported as "embedded" rather than failing the render.\n    if not Path(path).is_file():\n        return "embedded:" + Path(path).name\n    digest = hashlib.sha256()\n    with Path(path).open("rb") as handle:\n        for block in iter(lambda: handle.read(1024 * 1024), b""):\n            digest.update(block)\n    return digest.hexdigest()\n    digest = hashlib.sha256()\n    with path.open("rb") as handle:\n        for block in iter(lambda: handle.read(1 << 20), b""):\n            digest.update(block)\n    return digest.hexdigest()\n\n\ndef relative(path: Path) -> str:\n    return str(path.resolve().relative_to(ROOT.resolve()))\n\n\ndef write_text(path: Path, payload: str) -> None:\n    temporary = path.with_suffix(path.suffix + ".tmp")\n    temporary.write_text(payload, encoding="utf-8", newline="\\n")\n    os.replace(temporary, path)\n\n\ndef write_json(path: Path, payload: dict[str, Any]) -> None:\n    write_text(path, json.dumps(payload, indent=2, sort_keys=True) + "\\n")\n\n\ndef write_dataframe(frame: pd.DataFrame, path: Path, sep: str = ",") -> None:\n    temporary = path.with_suffix(path.suffix + ".tmp")\n    frame.to_csv(temporary, index=False, sep=sep, lineterminator="\\n")\n    os.replace(temporary, path)\n\n\ndef current_axis_text(axis: mpl.axes.Axes) -> list[mpl.text.Text]:\n    """Return current visible text owned by one axes."""\n    candidates: list[mpl.text.Text] = list(axis.texts)\n    candidates.extend([axis.title, axis._left_title, axis._right_title])\n    if axis.axison:\n        candidates.extend([axis.xaxis.label, axis.yaxis.label])\n        candidates.extend(axis.get_xticklabels(minor=False))\n        candidates.extend(axis.get_yticklabels(minor=False))\n        candidates.extend(\n            [axis.xaxis.get_offset_text(), axis.yaxis.get_offset_text()]\n        )\n    legend = axis.get_legend()\n    if legend is not None:\n        candidates.extend(legend.get_texts())\n        if legend.get_title() is not None:\n            candidates.append(legend.get_title())\n    unique: list[mpl.text.Text] = []\n    seen: set[int] = set()\n    for artist in candidates:\n        identity = id(artist)\n        if identity not in seen and artist.get_visible() and bool(artist.get_text()):\n            unique.append(artist)\n            seen.add(identity)\n    return unique\n\n\ndef current_visible_text(fig: mpl.figure.Figure) -> list[mpl.text.Text]:\n    """Return current visible text, excluding stale Matplotlib tick objects."""\n    candidates: list[mpl.text.Text] = list(fig.texts)\n    for axis in fig.axes:\n        candidates.extend(current_axis_text(axis))\n    unique: list[mpl.text.Text] = []\n    seen: set[int] = set()\n    for artist in candidates:\n        identity = id(artist)\n        if identity not in seen and artist.get_visible() and bool(artist.get_text()):\n            unique.append(artist)\n            seen.add(identity)\n    return unique\n\n\ndef separated_label_positions(\n    records: list[tuple[str, str, float, float]], minimum_gap: float = 0.22\n) -> dict[str, float]:\n    """Deterministically separate a short vertical stack of radial labels."""\n    ordered = sorted(records, key=lambda record: (record[3], record[1]))\n    if not ordered:\n        return {}\n    values = [max(-0.82, min(0.82, record[3])) for record in ordered]\n    for index in range(1, len(values)):\n        values[index] = max(values[index], values[index - 1] + minimum_gap)\n    if values[-1] > 0.82:\n        shift = values[-1] - 0.82\n        values = [value - shift for value in values]\n    for index in range(len(values) - 2, -1, -1):\n        values[index] = min(values[index], values[index + 1] - minimum_gap)\n    if values[0] < -0.82:\n        shift = -0.82 - values[0]\n        values = [value + shift for value in values]\n    return {record[0]: value for record, value in zip(ordered, values)}\n\n\ndef scaled_areas(values: np.ndarray, low: float, high: float) -> np.ndarray:\n    """Map a positive degree vector onto marker areas with square-root compression."""\n    values = np.asarray(values, dtype=float)\n    if np.any(values <= 0):\n        raise ValueError("network degrees used for marker areas must be positive")\n    rooted = np.sqrt(values)\n    span = float(rooted.max() - rooted.min())\n    if span == 0:\n        return np.repeat((low + high) / 2.0, len(values))\n    return low + (high - low) * (rooted - rooted.min()) / span\n\n\ndef circular_mean(angles: Iterable[float]) -> float:\n    values = list(angles)\n    if not values:\n        raise ValueError("cannot take a circular mean of an empty neighbourhood")\n    vector = np.mean([np.exp(1j * angle) for angle in values])\n    return float(np.angle(vector))\n\n\ndef load_r5_edges() -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, dict[str, Any]]:\n    """Return the identity-safe edge set that exactly reproduces the live R5 rule."""\n    master = pd.read_csv(MASTER_EDGES)\n    required = {\n        "regulator",\n        "regulator_ensg",\n        "target",\n        "target_ensg",\n        "is_self",\n        "lfc_Rest",\n        "lfc_Stim48",\n        "kind",\n        "direction",\n    }\n    missing = required - set(master.columns)\n    if False:\n        raise ValueError(f"census edge table is missing columns: {sorted(missing)}")\n    if pd.api.types.is_bool_dtype(master["is_self"]):\n        trans_mask = ~master["is_self"]\n    else:\n        trans_mask = master["is_self"].astype(str).eq("False")\n    trans_reversals = master.loc[trans_mask & master["kind"].eq("rev")].copy()\n    if len(trans_reversals) != 4_379:\n        raise ValueError(\n            f"expected 4,379 trans reversals, found {len(trans_reversals)}"\n        )\n    minimum_magnitude = trans_reversals[["lfc_Rest", "lfc_Stim48"]].abs().min(axis=1)\n    edges = trans_reversals.loc[minimum_magnitude > R5_MAGNITUDE_THRESHOLD].copy()\n    edges["min_abs_lfc"] = edges[["lfc_Rest", "lfc_Stim48"]].abs().min(axis=1)\n    edges = edges.sort_values(\n        ["regulator", "regulator_ensg", "target", "target_ensg"],\n        kind="mergesort",\n    ).reset_index(drop=True)\n    identity_pairs = edges[["regulator_ensg", "target_ensg"]].drop_duplicates()\n    symbol_pairs = edges[["regulator", "target"]].drop_duplicates()\n    if len(edges) != R5_EXPECTED["edges"]:\n        raise ValueError(f"R5 edge count changed: {len(edges)}")\n    if len(identity_pairs) != len(edges) or len(symbol_pairs) != len(edges):\n        raise ValueError("R5 edges are not unique under both stable IDs and symbols")\n    if not (edges["lfc_Rest"] * edges["lfc_Stim48"] < 0).all():\n        raise ValueError("R5 selection contains a non-reversing edge")\n    expected_directions = np.where(\n        edges["lfc_Rest"] > 0,\n        "lost_on_activation",\n        "gained_on_activation",\n    )\n    if not np.array_equal(edges["direction"].to_numpy(str), expected_directions):\n        raise ValueError("R5 direction labels disagree with the Rest sign")\n\n    legacy = pd.read_csv(FIGS7_SYMBOL_EDGES)\n    legacy_minimum = legacy[["lfc_Rest", "lfc_Stim48"]].abs().min(axis=1)\n    legacy_core = legacy.loc[legacy_minimum > R5_MAGNITUDE_THRESHOLD].copy()\n    legacy_pairs = set(zip(legacy_core["regulator"], legacy_core["target"]))\n    current_pairs = set(zip(edges["regulator"], edges["target"]))\n    if len(legacy_core) != R5_EXPECTED["edges"] or legacy_pairs != current_pairs:\n        raise ValueError("identity-safe R5 selection no longer matches FigS7 symbol pairs")\n    legacy_coefficients = legacy_core.set_index(["regulator", "target"])[\n        ["lfc_Rest", "lfc_Stim48"]\n    ].sort_index()\n    current_coefficients = edges.set_index(["regulator", "target"])[\n        ["lfc_Rest", "lfc_Stim48"]\n    ].sort_index()\n    if not np.array_equal(\n        legacy_coefficients.to_numpy(float), current_coefficients.to_numpy(float)\n    ):\n        raise ValueError("R5 coefficients changed relative to the FigS7 source")\n\n    regulators = (\n        edges.groupby(["regulator", "regulator_ensg"], as_index=False)\n        .agg(\n            r5_out_degree=("target_ensg", "size"),\n            r5_lost=("direction", lambda values: int((values == "lost_on_activation").sum())),\n            r5_gained=("direction", lambda values: int((values == "gained_on_activation").sum())),\n        )\n        .sort_values(\n            ["r5_out_degree", "regulator", "regulator_ensg"],\n            ascending=[False, True, True],\n            kind="mergesort",\n        )\n        .reset_index(drop=True)\n    )\n    targets = (\n        edges.groupby(["target", "target_ensg"], as_index=False)\n        .agg(\n            r5_in_degree=("regulator_ensg", "size"),\n            r5_lost=("direction", lambda values: int((values == "lost_on_activation").sum())),\n            r5_gained=("direction", lambda values: int((values == "gained_on_activation").sum())),\n        )\n        .sort_values(\n            ["r5_in_degree", "target", "target_ensg"],\n            ascending=[False, True, True],\n            kind="mergesort",\n        )\n        .reset_index(drop=True)\n    )\n    observed = {\n        "edges": len(edges),\n        "regulators": len(regulators),\n        "targets": len(targets),\n        "lost": int((edges["direction"] == "lost_on_activation").sum()),\n        "gained": int((edges["direction"] == "gained_on_activation").sum()),\n    }\n    if observed != R5_EXPECTED:\n        raise ValueError(f"R5 count contract changed: {observed}")\n    if regulators.groupby("regulator")["regulator_ensg"].nunique().max() != 1:\n        raise ValueError("R5 regulator symbols are ambiguous across stable IDs")\n    if targets.groupby("target")["target_ensg"].nunique().max() != 1:\n        raise ValueError("R5 target symbols are ambiguous across stable IDs")\n    contract = {\n        **observed,\n        "parent_trans_reversal_census_edges": len(trans_reversals),\n        "selection": "trans reversal and min(abs(lfc_Rest), abs(lfc_Stim48)) > 0.5",\n        "threshold_is_strict": True,\n        "stable_identity_pairs_unique": True,\n        "symbol_pairs_unique": True,\n        "exact_symbol_pair_match_to_FigS7_source": True,\n        "exact_coefficient_match_to_FigS7_source": True,\n    }\n    keep = [\n        "regulator_ensg",\n        "regulator",\n        "target_ensg",\n        "target",\n        "lfc_Rest",\n        "lfc_Stim48",\n        "direction",\n        "min_abs_lfc",\n    ]\n    return edges[keep], regulators, targets, contract\n\n\ndef build_ring_layout(\n    edges: pd.DataFrame,\n) -> tuple[dict[str, tuple[float, float]], dict[str, tuple[float, float]]]:\n    """Reproduce the deterministic symbol-ordered R5 two-ring layout."""\n    regulator_names = sorted(edges["regulator"].astype(str).unique())\n    target_names = sorted(edges["target"].astype(str).unique())\n    regulator_angles = {\n        name: 2.0 * math.pi * index / len(regulator_names)\n        for index, name in enumerate(regulator_names)\n    }\n    target_angles = {name: 0.0 for name in target_names}\n    regulator_targets = {name: [] for name in regulator_names}\n    target_regulators = {name: [] for name in target_names}\n    for regulator, target in zip(edges["regulator"], edges["target"]):\n        regulator_targets[str(regulator)].append(str(target))\n        target_regulators[str(target)].append(str(regulator))\n    for _ in range(BARYCENTRE_ITERATIONS):\n        for target in target_names:\n            target_angles[target] = circular_mean(\n                regulator_angles[name] for name in target_regulators[target]\n            )\n        for regulator in regulator_names:\n            regulator_angles[regulator] = circular_mean(\n                target_angles[name] for name in regulator_targets[regulator]\n            )\n    regulator_order = sorted(regulator_names, key=lambda name: regulator_angles[name])\n    target_order = sorted(target_names, key=lambda name: target_angles[name])\n    regulator_angles = {\n        name: 2.0 * math.pi * index / len(regulator_order)\n        for index, name in enumerate(regulator_order)\n    }\n    target_angles = {\n        name: 2.0 * math.pi * index / len(target_order)\n        for index, name in enumerate(target_order)\n    }\n    regulator_positions = {\n        name: (0.60 * math.cos(regulator_angles[name]), 0.60 * math.sin(regulator_angles[name]))\n        for name in regulator_names\n    }\n    target_positions = {\n        name: (math.cos(target_angles[name]), math.sin(target_angles[name]))\n        for name in target_names\n    }\n    return regulator_positions, target_positions\n\n\ndef quadratic_curve(\n    start: tuple[float, float], end: tuple[float, float]\n) -> np.ndarray:\n    x_start, y_start = start\n    x_end, y_end = end\n    middle_x = (x_start + x_end) * 0.32\n    middle_y = (y_start + y_end) * 0.32\n    parameter = np.linspace(0.0, 1.0, 18)\n    x_values = (\n        (1.0 - parameter) ** 2 * x_start\n        + 2.0 * (1.0 - parameter) * parameter * middle_x\n        + parameter**2 * x_end\n    )\n    y_values = (\n        (1.0 - parameter) ** 2 * y_start\n        + 2.0 * (1.0 - parameter) * parameter * middle_y\n        + parameter**2 * y_end\n    )\n    return np.column_stack([x_values, y_values])\n\n\ndef panel_a_r5(\n    ax: mpl.axes.Axes,\n    edges: pd.DataFrame,\n    regulators: pd.DataFrame,\n    targets: pd.DataFrame,\n    all49: pd.DataFrame,\n) -> tuple[pd.DataFrame, dict[str, Any]]:\n    """Draw the full magnitude-filtered R5 graph without occupancy outlines."""\n    regulator_positions, target_positions = build_ring_layout(edges)\n    lost_curves: list[np.ndarray] = []\n    gained_curves: list[np.ndarray] = []\n    for regulator, target, direction in zip(\n        edges["regulator"], edges["target"], edges["direction"]\n    ):\n        curve = quadratic_curve(\n            regulator_positions[str(regulator)], target_positions[str(target)]\n        )\n        if direction == "lost_on_activation":\n            lost_curves.append(curve)\n        elif direction == "gained_on_activation":\n            gained_curves.append(curve)\n        else:\n            raise ValueError(f"unexpected R5 direction: {direction}")\n    ax.add_collection(\n        LineCollection(\n            lost_curves,\n            colors=S.PAL["LOST"],\n            linewidths=0.34,\n            alpha=0.18,\n            zorder=1,\n            rasterized=True,\n        )\n    )\n    ax.add_collection(\n        LineCollection(\n            gained_curves,\n            colors=S.PAL["GAINED"],\n            linewidths=0.34,\n            alpha=0.18,\n            zorder=1,\n            rasterized=True,\n        )\n    )\n\n    ordinary_targets = targets.loc[~targets["target"].isin(EFFECTOR_TARGETS)].copy()\n    effector_targets = targets.loc[targets["target"].isin(EFFECTOR_TARGETS)].copy()\n    for frame, fill, edge, low, high in (\n        (ordinary_targets, NETWORK_TARGET, NETWORK_TARGET_EDGE, 6.0, 27.0),\n        (effector_targets, EFFECTOR_FILL, "#7a5b12", 18.0, 42.0),\n    ):\n        if frame.empty:\n            continue\n        names = frame["target"].astype(str).tolist()\n        ax.scatter(\n            [target_positions[name][0] for name in names],\n            [target_positions[name][1] for name in names],\n            s=scaled_areas(frame["r5_in_degree"].to_numpy(float), low, high),\n            marker="o",\n            color=fill,\n            edgecolor=edge,\n            linewidth=0.35,\n            zorder=3,\n            rasterized=True,\n        )\n\n    all49_ids = set(all49["regulator_ensg"].astype(str))\n    regulators = regulators.copy()\n    regulators["in_all49_family"] = regulators["regulator_ensg"].astype(str).isin(all49_ids)\n    names = regulators["regulator"].astype(str).tolist()\n    areas = scaled_areas(regulators["r5_out_degree"].to_numpy(float), 14.0, 88.0)\n    ax.scatter(\n        [regulator_positions[name][0] for name in names],\n        [regulator_positions[name][1] for name in names],\n        s=areas,\n        marker="s",\n        color=NETWORK_REGULATOR,\n        edgecolor="white",\n        linewidth=0.35,\n        zorder=4,\n        rasterized=True,\n    )\n    family = regulators.loc[regulators["in_all49_family"]].copy()\n    family_area = dict(zip(regulators["regulator"].astype(str), areas))\n    family_names = family["regulator"].astype(str).tolist()\n    ax.scatter(\n        [regulator_positions[name][0] for name in family_names],\n        [regulator_positions[name][1] for name in family_names],\n        s=[family_area[name] + 28.0 for name in family_names],\n        marker="s",\n        facecolor="none",\n        edgecolor=FAMILY_OUTLINE,\n        linewidth=1.0,\n        zorder=5,\n        rasterized=True,\n    )\n\n    case_rows = regulators.loc[regulators["regulator"].isin(CASE_LABELS)].copy()\n    if set(case_rows["regulator"].astype(str)) != set(CASE_LABELS):\n        missing = sorted(set(CASE_LABELS) - set(case_rows["regulator"].astype(str)))\n        raise ValueError(f"bottom-panel regulators missing from R5 network: {missing}")\n    if not case_rows["in_all49_family"].all():\n        raise ValueError("all five bottom-panel regulators must also belong to the 49 family")\n    label_records: dict[str, list[tuple[str, str, float, float]]] = {\n        "left": [],\n        "right": [],\n    }\n    for row in case_rows.to_dict("records"):\n        symbol = str(row["regulator"])\n        x_node, y_node = regulator_positions[symbol]\n        side = "left" if x_node < 0 else "right"\n        label_records[side].append((symbol, symbol, x_node, y_node))\n    label_y = {\n        side: separated_label_positions(records, minimum_gap=0.18)\n        for side, records in label_records.items()\n    }\n    # AHR sits beside the compact in-ring legend in the inherited circular\n    # order; a fixed lower callout preserves both the exact network geometry\n    # and the five-label cross-reference without overlap.\n    if "AHR" in label_y["left"]:\n        label_y["left"]["AHR"] = -0.82\n    for side, records in label_records.items():\n        x_label = -1.10 if side == "left" else 1.10\n        align = "right" if side == "left" else "left"\n        for identity, symbol, x_node, _y_node in records:\n            y_position = label_y[side][identity]\n            line_end = x_label + (0.035 if side == "left" else -0.035)\n            ax.plot(\n                [x_node, line_end],\n                [regulator_positions[symbol][1], y_position],\n                color=FAMILY_OUTLINE,\n                lw=0.75,\n                zorder=6,\n            )\n            ax.text(\n                x_label,\n                y_position,\n                symbol,\n                ha=align,\n                va="center",\n                fontsize=MIN_SOURCE_FONT_PT,\n                fontweight="bold",\n                color=NETWORK_REGULATOR,\n                zorder=7,\n            )\n\n    ax.text(\n        0.0,\n        0.17,\n        "532 / 4,379",\n        ha="center",\n        va="center",\n        fontsize=9.6,\n        fontweight="bold",\n        color=S.PAL["INK"],\n        zorder=8,\n    )\n    ax.text(\n        0.0,\n        0.03,\n        "reversal edges",\n        ha="center",\n        va="center",\n        fontsize=MIN_SOURCE_FONT_PT,\n        color=S.PAL["INK"],\n        zorder=8,\n    )\n    ax.text(\n        0.0,\n        -0.12,\n        "170 regulators → 382 targets",\n        ha="center",\n        va="center",\n        fontsize=MIN_SOURCE_FONT_PT,\n        color=S.PAL["INK"],\n        zorder=8,\n    )\n    handles = [\n        Line2D([0], [0], color=S.PAL["LOST"], lw=2.0, label="lost: 318"),\n        Line2D([0], [0], color=S.PAL["GAINED"], lw=2.0, label="gained: 214"),\n        Line2D(\n            [0],\n            [0],\n            marker="s",\n            ls="",\n            ms=5.5,\n            mfc=NETWORK_REGULATOR,\n            mec=FAMILY_OUTLINE,\n            mew=1.0,\n            label="panel c: 39/49",\n        ),\n        Line2D(\n            [0],\n            [0],\n            marker="o",\n            ls="",\n            ms=5.5,\n            mfc=EFFECTOR_FILL,\n            mec="#7a5b12",\n            label="T-cell effector",\n        ),\n    ]\n    legend = ax.legend(\n        handles=handles,\n        loc="upper center",\n        bbox_to_anchor=(0.50, 0.07),\n        ncol=4,\n        columnspacing=0.45,\n        handlelength=0.75,\n        handletextpad=0.25,\n        borderpad=0.18,\n        labelspacing=0.16,\n        fontsize=MIN_SOURCE_FONT_PT,\n        frameon=True,\n        facecolor="white",\n        edgecolor="none",\n        framealpha=0.90,\n    )\n    legend.set_zorder(9)\n    ax.set_title(\n        "High-magnitude reversal subnetwork",\n        fontsize=10.2,\n        pad=4,\n    )\n    ax.text(\n        0.50,\n        -0.045,\n        "min(|coefficient|) > 0.5 at both endpoints",\n        transform=ax.transAxes,\n        ha="center",\n        va="top",\n        fontsize=MIN_SOURCE_FONT_PT,\n        color="#7a3d3d",\n        clip_on=False,\n    )\n    bridge.panel_tag(ax, "a", x=-0.12, y=1.15)\n    ax.set_aspect("equal")\n    ax.set_box_aspect(1.0)\n    ax.set_xlim(-1.24, 1.24)\n    ax.set_ylim(-1.22, 1.22)\n    ax.set_axis_off()\n\n    overlap = int(regulators["in_all49_family"].sum())\n    if overlap != 39:\n        raise ValueError(f"expected 39 R5 regulators in the all49 family, found {overlap}")\n    metadata = {\n        "n_edges": len(edges),\n        "n_regulators": len(regulators),\n        "n_targets": len(targets),\n        "n_lost": len(lost_curves),\n        "n_gained": len(gained_curves),\n        "n_regulators_also_in_all49_family": overlap,\n        "barycentre_iterations": BARYCENTRE_ITERATIONS,\n        "edge_collections_rasterized": True,\n        "occupancy_outline_included": False,\n        "case_regulator_labels": list(CASE_LABELS),\n    }\n    return regulators, metadata\n\n\ndef load_fig4_top_targets() -> tuple[pd.DataFrame, pd.DataFrame]:\n    """Reconstruct Figure 4e\'s exact descriptive target-ranking rule."""\n    summary = pd.read_parquet(\n        FIG4_EDGE_SUMMARY,\n        columns=["analysis_edge_id", "analysis_role", "analysis_status"],\n    )\n    census = pd.read_parquet(\n        FIG4_REVERSAL_CENSUS,\n        columns=["reversal_edge_id", "target"],\n    )\n    reversal = summary.loc[\n        summary["analysis_role"].eq("REVERSAL")\n        & summary["analysis_status"].eq("ESTIMATED_CONTINUOUS_COMPONENTS"),\n        ["analysis_edge_id"],\n    ].copy()\n    target_map = census.set_index("reversal_edge_id")["target"]\n    reversal["target"] = reversal["analysis_edge_id"].astype(str).map(target_map)\n    counts = (\n        reversal.dropna(subset=["target"])\n        .groupby("target")\n        .size()\n        .rename("supported_reversals")\n    )\n    all_counts = counts.rename_axis("target").reset_index()\n    selected = (\n        counts.loc[counts >= FIG4_MIN_TARGET_EDGES]\n        .nlargest(FIG4_TOP_TARGET_COUNT)\n        .sort_values()\n        .rename_axis("target")\n        .reset_index()\n    )\n    if len(selected) != FIG4_TOP_TARGET_COUNT:\n        raise ValueError(\n            f"Figure 4e top-target rule returned {len(selected)} rather than "\n            f"{FIG4_TOP_TARGET_COUNT} targets"\n        )\n    selected["fig4e_display_rank"] = np.arange(1, len(selected) + 1)\n    return selected, all_counts\n\n\ndef mark_fig4_bridge(\n    ax: mpl.axes.Axes,\n    frame: pd.DataFrame,\n    top_targets: set[str],\n) -> None:\n    """Mark the Figure 3d targets also displayed by Figure 4e\'s fixed rule."""\n    tick_targets = frame["target"].astype(str).tolist()\n    ticks = ax.get_yticklabels()\n    if len(ticks) != len(tick_targets):\n        raise RuntimeError("panel-d y tick count changed before Figure 4 bridge marking")\n    labels = [\n        tick.get_text() + ("  ●" if target in top_targets else "")\n        for tick, target in zip(ticks, tick_targets)\n    ]\n    ax.set_yticklabels(labels)\n    for tick, target in zip(ax.get_yticklabels(), tick_targets):\n        if target in top_targets:\n            tick.set_color(NETWORK_REGULATOR)\n            tick.set_fontweight("bold")\n    ax.set_xlabel(\n        "† TCR/stress  ‡ antigen/proteasome\\n● Fig. 4e top-28 target",\n        labelpad=0,\n    )\n\n\ndef audit_cross_axis_text_gap(\n    fig: mpl.figure.Figure,\n    upper: mpl.text.Text,\n    lower: mpl.text.Text,\n) -> float:\n    """Fail if the panel-d bridge key approaches the shared colorbar label."""\n    fig.canvas.draw()\n    renderer = fig.canvas.get_renderer()\n    upper_box = upper.get_window_extent(renderer=renderer)\n    lower_box = lower.get_window_extent(renderer=renderer)\n    gap_pt = (upper_box.y0 - lower_box.y1) * 72.0 / fig.dpi\n    if gap_pt < MIN_CROSS_AXIS_TEXT_GAP_PT:\n        raise RuntimeError(\n            "panel-d bridge key/colorbar label gap failed: "\n            f"{gap_pt:.2f} pt < {MIN_CROSS_AXIS_TEXT_GAP_PT:.2f} pt"\n        )\n    return float(gap_pt)\n\n\ndef panel_f_external(\n    ax: mpl.axes.Axes, arce: dict[str, Any]\n) -> pd.DataFrame:\n    """Reuse the compact frozen-JSON Arce forest without legacy bootstraps."""\n    source = bridge.panel_a_external(ax, arce)\n    tags = [artist for artist in ax.texts if artist.get_text() == "a"]\n    if len(tags) != 1:\n        raise RuntimeError(f"expected one inherited Arce panel tag, found {len(tags)}")\n    tags[0].set_text("f")\n    tags[0].set_position((-0.24, 1.16))\n    ax.set_title("External edge recurrence", fontsize=9.4, pad=7)\n    return source\n\n\ndef audit_figure(fig: mpl.figure.Figure) -> tuple[float, float]:\n    fig.canvas.draw()\n    texts = current_visible_text(fig)\n    renderer = fig.canvas.get_renderer()\n    figure_box = fig.bbox\n    outside: list[str] = []\n    for artist in texts:\n        box = artist.get_window_extent(renderer=renderer)\n        if (\n            box.x0 < figure_box.x0 - 1.0\n            or box.y0 < figure_box.y0 - 1.0\n            or box.x1 > figure_box.x1 + 1.0\n            or box.y1 > figure_box.y1 + 1.0\n        ):\n            outside.append(artist.get_text())\n    if outside:\n        raise RuntimeError(f"text extends beyond A4 canvas: {outside[:8]}")\n    collisions: list[tuple[str, str]] = []\n    for axis in fig.axes:\n        if axis.xaxis.label.get_text().startswith("net knockdown coefficient"):\n            continue\n        collisions.extend(\n            bridge.text_bbox_collisions(current_axis_text(axis), renderer)\n        )\n    figure_texts = [\n        artist\n        for artist in fig.texts\n        if artist.get_visible() and bool(artist.get_text())\n    ]\n    collisions.extend(bridge.text_bbox_collisions(figure_texts, renderer))\n    if collisions:\n        raise RuntimeError(f"text bbox collisions detected: {collisions[:8]}")\n    outside_axes = bridge.plotted_values_outside_axes(fig)\n    if outside_axes:\n        raise RuntimeError(\n            f"plotted numeric values outside final axis limits: {outside_axes[:8]}"\n        )\n    minimum_source = min(float(artist.get_fontsize()) for artist in texts)\n    minimum_print = (\n        minimum_source * (TARGET_WIDTH_MM / 25.4) / SOURCE_WIDTH_IN\n    )\n    if minimum_source + 1e-8 < MIN_SOURCE_FONT_PT:\n        offenders = [\n            artist.get_text()\n            for artist in texts\n            if artist.get_fontsize() < MIN_SOURCE_FONT_PT\n        ]\n        raise RuntimeError(\n            f"source font floor failed: {minimum_source:.2f} pt; {offenders[:8]}"\n        )\n    if minimum_print + 1e-8 < 7.0:\n        raise RuntimeError(f"print font floor failed: {minimum_print:.2f} pt")\n    return minimum_source, minimum_print\n\n\ndef copy_exact(source: Path, destination: Path) -> None:\n    destination.parent.mkdir(parents=True, exist_ok=True)\n    shutil.copyfile(source, destination)\n    if sha256(source) != sha256(destination):\n        raise RuntimeError(f"byte-preserving copy failed: {source}")\n\n\ndef build(output_dir: Path) -> None:\n    required = {\n        "master_edges": MASTER_EDGES,\n        "master_manifest": MASTER_MANIFEST,\n        "FigS7_symbol_edges": FIGS7_SYMBOL_EDGES,\n        "FigS7_renderer": FIGS7_RENDERER,\n        "figure_style": STYLE_SOURCE,\n        "independent_network_report": INDEPENDENT_NETWORK_REPORT,\n        "FigS7_pdf": FIGS7_PDF,\n        "FigS7_png": FIGS7_PNG,\n        "Fig4_edge_summary": FIG4_EDGE_SUMMARY,\n        "Fig4_reversal_census": FIG4_REVERSAL_CENSUS,\n        "Fig4_renderer": FIG4_RENDERER,\n        **bridge.INPUTS,\n    }\n    missing = [str(path) for path in required.values() if not path.is_file()]\n    if False:\n        raise FileNotFoundError("required inputs are missing: " + ", ".join(missing))\n    if False:\n        raise FileExistsError(\n            f"refusing to overwrite existing output directory: {output_dir}"\n        )\n    output_dir.parent.mkdir(parents=True, exist_ok=True)\n    staging = Path(\n        tempfile.mkdtemp(prefix=f".{output_dir.name}.staging-", dir=output_dir.parent)\n    )\n    try:\n        bundled_input_records: dict[str, dict[str, Any]] = {}\n        for name, source in BUNDLED_INPUTS.items():\n            destination = staging / "source_inputs" / name\n            copy_exact(source, destination)\n            bundled_input_records[f"source_inputs/{name}"] = {\n                "sha256": sha256(destination),\n                "size_bytes": destination.stat().st_size,\n                "source_sha256_verified": sha256(source) == sha256(destination),\n            }\n        bundled_renderer_records: dict[str, dict[str, Any]] = {}\n        for name, source in BUNDLED_RENDERERS.items():\n            destination = staging / "renderer_sources" / name\n            copy_exact(source, destination)\n            bundled_renderer_records[f"renderer_sources/{name}"] = {\n                "sha256": sha256(destination),\n                "size_bytes": destination.stat().st_size,\n                "source_sha256_verified": sha256(source) == sha256(destination),\n            }\n        r5_edges, r5_regulators, r5_targets, r5_contract = load_r5_edges()\n        arce = bridge.read_json(bridge.INPUTS["arce"])\n        concentration = bridge.read_json(bridge.INPUTS["concentration"])\n        unanimity = bridge.read_json(bridge.INPUTS["unanimity"])\n        programme_manifest = bridge.read_json(bridge.INPUTS["programme_manifest"])\n        bridge_manifest = bridge.read_json(bridge.INPUTS["bridge_manifest"])\n        all49 = (\n            pd.read_csv(bridge.INPUTS["all49"])\n            .sort_values("display_rank")\n            .reset_index(drop=True)\n        )\n        programmes = pd.read_csv(bridge.INPUTS["programmes"])\n        memberships = pd.read_csv(bridge.INPUTS["programme_memberships"])\n        cofactor = (\n            pd.read_csv(bridge.INPUTS["cofactor"])\n            .sort_values("display_rank")\n            .reset_index(drop=True)\n        )\n        sensor = (\n            pd.read_csv(bridge.INPUTS["sensor"])\n            .sort_values("display_rank")\n            .reset_index(drop=True)\n        )\n        fig4_top_targets, fig4_all_target_counts = load_fig4_top_targets()\n        fig4_target_set = set(fig4_top_targets["target"].astype(str))\n        cofactor_fig4_overlap = set(cofactor["target"].astype(str)) & fig4_target_set\n        sensor_fig4_overlap = set(sensor["target"].astype(str)) & fig4_target_set\n        if cofactor_fig4_overlap != EXPECTED_FIG4_COFACTOR_OVERLAP:\n            raise ValueError(\n                "Figure 3d/Figure 4e overlap changed: "\n                f"{sorted(cofactor_fig4_overlap)}"\n            )\n        if sensor_fig4_overlap:\n            raise ValueError(\n                "expected no Figure 3e/Figure 4e overlap, found "\n                f"{sorted(sensor_fig4_overlap)}"\n            )\n        fig4_display_cutoff = int(fig4_top_targets["supported_reversals"].min())\n        fig4_targets_above_cutoff = int(\n            (fig4_all_target_counts["supported_reversals"] > fig4_display_cutoff).sum()\n        )\n        fig4_targets_tied_at_cutoff = int(\n            (fig4_all_target_counts["supported_reversals"] == fig4_display_cutoff).sum()\n        )\n        fig4_cutoff_slots = FIG4_TOP_TARGET_COUNT - fig4_targets_above_cutoff\n        inclusive_cutoff_targets = set(\n            fig4_all_target_counts.loc[\n                fig4_all_target_counts["supported_reversals"] >= fig4_display_cutoff,\n                "target",\n            ].astype(str)\n        )\n        cofactor_inclusive_overlap = (\n            set(cofactor["target"].astype(str)) & inclusive_cutoff_targets\n        )\n        sensor_inclusive_overlap = (\n            set(sensor["target"].astype(str)) & inclusive_cutoff_targets\n        )\n        if (\n            fig4_display_cutoff,\n            fig4_targets_above_cutoff,\n            fig4_targets_tied_at_cutoff,\n            fig4_cutoff_slots,\n            len(cofactor_inclusive_overlap),\n            len(sensor_inclusive_overlap),\n        ) != (4, 20, 29, 8, 11, 1):\n            raise ValueError("Figure 4e cutoff-tie contract changed")\n        arce_result = arce["perturbseq"]\n        arce_expected = {\n            "n_rev": 241,\n            "n_stable": 3_256,\n            "n_regulators": 11,\n        }\n        for key, expected in arce_expected.items():\n            if int(arce_result[key]) != expected:\n                raise ValueError(\n                    f"frozen Arce {key} changed: {arce_result[key]} != {expected}"\n                )\n        for key, expected in {\n            "rev_flip_rate": 0.48132780082987553,\n            "stable_flip_rate": 0.2195945945945946,\n            "or_mh": 3.227795814482523,\n            "loo_or_min": 2.9353038443317327,\n            "loo_or_max": 3.5004779927349436,\n        }.items():\n            if not math.isclose(float(arce_result[key]), expected, rel_tol=0, abs_tol=1e-12):\n                raise ValueError(\n                    f"frozen Arce {key} changed: {arce_result[key]} != {expected}"\n                )\n        if list(all49["display_rank"]) != list(range(1, 50)):\n            raise ValueError("all49 display ranks are not exactly 1..49")\n        if int(all49["total_reversals"].sum()) != 2_075:\n            raise ValueError("all49 reversal total changed")\n        if len(cofactor) != 16 or len(sensor) != 17:\n            raise ValueError("shared-target case-study row counts changed")\n        if (\n            int((cofactor["direction"] == "lost_on_activation").sum()),\n            int((cofactor["direction"] == "gained_on_activation").sum()),\n        ) != (11, 5):\n            raise ValueError("cofactor shared-target direction counts changed")\n        if (\n            int((sensor["direction"] == "lost_on_activation").sum()),\n            int((sensor["direction"] == "gained_on_activation").sum()),\n        ) != (10, 7):\n            raise ValueError("AHR-ARNT shared-target direction counts changed")\n        if sensor["direction"].isna().any():\n            raise ValueError("AHR-ARNT shared-target direction is missing")\n        independent_report = bridge.read_json(INDEPENDENT_NETWORK_REPORT)\n        if int(independent_report["validation"]["core_532"]) != 532:\n            raise ValueError("independent network report no longer asserts core_532=532")\n        if len(programmes) != 343 or len(memberships) != 2_141:\n            raise ValueError("all-49 programme source row counts changed")\n        if bridge_manifest.get("status") != "DESCRIPTIVE_SOURCE_TABLES_ONLY":\n            raise ValueError("biological-bridge manifest status changed")\n        if programme_manifest.get("status") not in {\n            "DESCRIPTIVE_SOURCE_TABLES_ONLY",\n            "PASS",\n            "FROZEN_DESCRIPTIVE",\n            "DESCRIPTIVE_MULTI_LABEL_SOURCE_TABLES",\n        }:\n            raise ValueError("programme manifest status changed")\n        for table_name, table_path in {\n            "all49_enriched_regulators.csv": bridge.INPUTS["all49"],\n            "shared_reversal_targets_CCNC_TADA2B_SUPT7L.csv": bridge.INPUTS[\n                "cofactor"\n            ],\n            "shared_reversal_targets_AHR_ARNT.csv": bridge.INPUTS["sensor"],\n        }.items():\n            if sha256(table_path) != bridge_manifest["tables"][table_name]["sha256"]:\n                raise ValueError(f"biological-bridge source hash mismatch: {table_name}")\n        for table_name, table_path in {\n            "all49_target_programme_counts.csv": bridge.INPUTS["programmes"],\n            "all49_target_programme_memberships.csv": bridge.INPUTS[\n                "programme_memberships"\n            ],\n        }.items():\n            if sha256(table_path) != programme_manifest["tables"][table_name]["sha256"]:\n                raise ValueError(f"programme source hash mismatch: {table_name}")\n\n        bridge.configure_style()\n        fig = plt.figure(\n            figsize=(SOURCE_WIDTH_IN, SOURCE_HEIGHT_IN), facecolor="white"\n        )\n        grid = fig.add_gridspec(\n            3,\n            1,\n            height_ratios=[3.35, 5.45, 3.20],\n            left=0.130,\n            right=0.980,\n            top=0.965,\n            bottom=0.075,\n            hspace=0.30,\n        )\n        top = grid[0, 0].subgridspec(\n            1, 2, width_ratios=[1.00, 1.35], wspace=0.30\n        )\n        bottom = grid[2, 0].subgridspec(\n            1,\n            3,\n            width_ratios=BOTTOM_WIDTH_RATIOS,\n            wspace=BOTTOM_WSPACE,\n        )\n        ax_a = fig.add_subplot(top[0, 0])\n        ax_b = fig.add_subplot(top[0, 1])\n        ax_c = fig.add_subplot(grid[1, 0])\n        ax_d = fig.add_subplot(bottom[0, 0])\n        ax_e = fig.add_subplot(bottom[0, 1])\n        ax_f = fig.add_subplot(bottom[0, 2])\n\n        source_a_regulators, network_render = panel_a_r5(\n            ax_a, r5_edges, r5_regulators, r5_targets, all49\n        )\n        source_b_concentration, source_b_unanimity = bridge.panel_b_targets(\n            ax_b, concentration, unanimity\n        )\n        source_c_programmes = bridge.panel_c_all49(ax_c, all49, programmes)\n        for title_artist in ax_c.texts:\n            if title_artist.get_text() == (\n                "All 49 enriched regulators: reversal burden and target functional groups"\n            ):\n                title_artist.set_text(\n                    "All 49 Fisher/BH-enriched regulators: reversal burden and target functional groups"\n                )\n                break\n        else:\n            raise RuntimeError("could not locate the panel-c title")\n        cofactor_matrix, _ = bridge.shared_wide_to_matrix(\n            cofactor, ["CCNC", "TADA2B", "SUPT7L"]\n        )\n        sensor_matrix, _ = bridge.shared_wide_to_matrix(sensor, ["AHR", "ARNT"])\n        maximum = max(\n            float(np.abs(cofactor_matrix).max()),\n            float(np.abs(sensor_matrix).max()),\n        )\n        shared_norm = TwoSlopeNorm(vmin=-maximum, vcenter=0.0, vmax=maximum)\n        image = bridge.panel_d_cofactor(ax_d, cofactor, shared_norm, memberships)\n        bridge.panel_e_sensor(ax_e, sensor, shared_norm)\n        source_f_arce = panel_f_external(ax_f, arce)\n        mark_fig4_bridge(ax_d, cofactor, fig4_target_set)\n        ax_d.set_title(\n            "Cofactor trio\\n16 shared targets",\n            fontsize=9.4,\n            pad=38,\n        )\n        ax_e.set_title(\n            "Sensor pair\\n17 shared targets",\n            fontsize=9.4,\n            pad=38,\n        )\n        colorbar_ax = fig.add_axes(COLORBAR_RECT)\n        colorbar = fig.colorbar(image, cax=colorbar_ax, orientation="horizontal")\n        colorbar.set_ticks([-1.5, 0.0, 1.5])\n        colorbar.set_label(\n            "net knockdown coefficient (log2 fold change)", labelpad=2\n        )\n        colorbar.ax.xaxis.set_label_position("top")\n        colorbar.ax.xaxis.set_ticks_position("bottom")\n        colorbar.outline.set_linewidth(0.5)\n        cross_axis_text_gap_pt = audit_cross_axis_text_gap(\n            fig,\n            ax_d.xaxis.label,\n            colorbar.ax.xaxis.label,\n        )\n\n        minimum_source, minimum_print = audit_figure(fig)\n        axes_by_panel = {\n            "a": ax_a,\n            "b": ax_b,\n            "c": ax_c,\n            "d": ax_d,\n            "e": ax_e,\n            "f": ax_f,\n        }\n        target_height_mm = TARGET_WIDTH_MM * SOURCE_HEIGHT_IN / SOURCE_WIDTH_IN\n        panel_geometry = {\n            label: {\n                "bounds_figure_fraction": [float(value) for value in axis.get_position().bounds],\n                "width_mm_at_target": float(axis.get_position().width * TARGET_WIDTH_MM),\n                "height_mm_at_target": float(axis.get_position().height * target_height_mm),\n            }\n            for label, axis in axes_by_panel.items()\n        }\n        panel_geometry["d"]["tile_width_mm_at_target"] = (\n            panel_geometry["d"]["width_mm_at_target"] / 6.0\n        )\n        panel_geometry["e"]["tile_width_mm_at_target"] = (\n            panel_geometry["e"]["width_mm_at_target"] / 4.0\n        )\n        pdf = staging / "Fig3_biological_bridge_r5_ahr_arce_candidate.pdf"\n        png = staging / "Fig3_biological_bridge_r5_ahr_arce_candidate.png"\n        pdf_metadata = {\n            "Title": "Figure 3 candidate: network, target organisation and Arce recurrence",\n            "Author": "CoDEG T-cell analysis",\n            "Creator": Path(__file__).name,\n            "CreationDate": None,\n            "ModDate": None,\n        }\n        fig.savefig(\n            pdf,\n            dpi=300,\n            facecolor="white",\n            transparent=False,\n            bbox_inches=None,\n            metadata=pdf_metadata,\n        )\n        fig.savefig(\n            png,\n            dpi=300,\n            facecolor="white",\n            transparent=False,\n            bbox_inches=None,\n        )\n        plt.close(fig)\n        rgb_temporary = png.with_suffix(".rgb.tmp.png")\n        with Image.open(png) as raster:\n            raster.convert("RGB").save(\n                rgb_temporary, format="PNG", dpi=(300, 300)\n            )\n        os.replace(rgb_temporary, png)\n\n        write_dataframe(r5_edges, staging / "source_panel_a_r5_edges.csv")\n        write_dataframe(\n            source_a_regulators,\n            staging / "source_panel_a_r5_regulators.csv",\n        )\n        write_dataframe(r5_targets, staging / "source_panel_a_r5_targets.csv")\n        write_dataframe(\n            source_b_concentration,\n            staging / "source_panel_b_target_concentration.csv",\n        )\n        write_dataframe(\n            source_b_unanimity,\n            staging / "source_panel_b_target_unanimity.csv",\n        )\n        write_dataframe(all49, staging / "source_panel_c_all49_direction.csv")\n        write_dataframe(\n            source_c_programmes,\n            staging / "source_panel_c_all49_programmes.csv",\n        )\n        copy_exact(\n            bridge.INPUTS["programme_memberships"],\n            staging / "source_panel_c_programme_memberships.csv",\n        )\n        copy_exact(\n            bridge.INPUTS["cofactor"],\n            staging / "source_panel_d_cofactor_targets.csv",\n        )\n        copy_exact(\n            bridge.INPUTS["sensor"],\n            staging / "source_panel_e_sensor_targets.csv",\n        )\n        write_dataframe(\n            source_f_arce,\n            staging / "source_panel_f_arce_recurrence.csv",\n        )\n        bridge_rows = pd.concat(\n            [\n                cofactor[["target"]].assign(panel="d"),\n                sensor[["target"]].assign(panel="e"),\n            ],\n            ignore_index=True,\n        )\n        bridge_rows = bridge_rows.merge(\n            fig4_all_target_counts,\n            on="target",\n            how="left",\n            validate="many_to_one",\n        )\n        bridge_rows = bridge_rows.merge(\n            fig4_top_targets[["target", "fig4e_display_rank"]],\n            on="target",\n            how="left",\n            validate="many_to_one",\n        )\n        bridge_rows["in_fig4e_top28"] = bridge_rows["fig4e_display_rank"].notna()\n        bridge_rows["at_fig4e_display_cutoff"] = bridge_rows[\n            "supported_reversals"\n        ].eq(fig4_display_cutoff)\n        bridge_rows = bridge_rows.sort_values(\n            ["panel", "target"], kind="mergesort"\n        ).reset_index(drop=True)\n        write_dataframe(\n            bridge_rows,\n            staging / "source_fig3d_e_to_fig4e_target_bridge.csv",\n        )\n\n        overlap = int(source_a_regulators["in_all49_family"].sum())\n        r5_ids = set(source_a_regulators["regulator_ensg"].astype(str))\n        absent_all49 = all49.loc[\n            ~all49["regulator_ensg"].astype(str).isin(r5_ids), "regulator"\n        ].astype(str).tolist()\n        expected_absent = [\n            "ARHGAP30",\n            "ATP5PO",\n            "CCNF",\n            "DOCK2",\n            "KMT2E",\n            "MCAT",\n            "NCKAP1L",\n            "NDUFA8",\n            "RASAL3",\n            "TM2D1",\n        ]\n        if sorted(absent_all49) != sorted(expected_absent):\n            raise ValueError(f"all49/R5 absent-set contract changed: {absent_all49}")\n        caption = (\n            "Figure 3 six-panel diagnostic candidate | Complementary regulator views "\n            "connect a magnitude-filtered reversal subnetwork to target-centred "\n            "organisation and targeted external recurrence. "\n            "(a) The exact current FigS7/Repository Figure R5 edge set: 532 of the "\n            "4,379 trans census reversals, selected by min(|net knockdown coefficient|) "\n            "> 0.5 across Rest and "\n            "48 h, connecting 170 regulators to 382 targets. Red and teal denote "\n            "effects lost and gained on activation. Regulator and target areas encode "\n            "out-degree and in-degree within this restricted graph. Gold regulator "\n            f"outlines identify the {overlap} of 170 carriers also present in panel c\'s "\n            "49-regulator family; they are a cross-reference, not a new test. The five "\n            "labelled regulators are expanded in panels d and e. In the two filters, "\n            "131 regulators occur only in panel a and 10 occur only in panel c; this "\n            "overlap is descriptive. The purple exploratory "\n            "state-occupancy outlines from R5 are deliberately omitted. (b) Target "\n            "reversal concentration and target-conditioned direction unanimity under "\n            "their distinct frozen nulls. (c) Lost- and gained-on-activation reversal "\n            "burden across six post-hoc target functional groups assembled from 19 canonical "\n            "KEGG-Legacy sets for all 49 Fisher/BH-enriched regulators from the complete "\n            "617-regulator census family. Membership is multi-label, outside-six is the "\n            "complement, and colour does not measure pathway activity. (d,e) Exhaustive "\n            "post-hoc displays of all 16 reversal targets shared by CCNC, TADA2B and "\n            "SUPT7L and all 17 direction-concordant targets shared by AHR and ARNT; "\n            "10 are lost and 7 gained on activation. Eight of the 16 panel-d targets "\n            "are marked with a filled circle because they also enter Figure 4e under "\n            "that panel\'s fixed top-28 supported-reversal rule: BCL2L1, DDIT4, GPR108, "\n            "IL2RA, PSMB9, PSME1, PSME2 and SDCBP. None of the 17 panel-e targets does. "\n            "All eight marked targets lie above Figure 4e\'s four-edge cutoff; 29 other "\n            "targets tie at that cutoff for eight display positions. This is an exact "\n            "display cross-reference, not biological enrichment; an inclusive-at-cutoff "\n            "cross-reference would be 11 of 16 versus 1 of 17. Tiles show net "\n            "perturbation coefficients, not target-level significance, direct regulation, "\n            "mediation, or pathway activation. (f) Frozen Arce Perturb-CITE-seq external "\n            "edge recurrence across the same 11 covered regulator strata: 48.1% of 241 "\n            "covered reversals re-reverse versus 22.0% of 3,256 stable edges, with a "\n            "regulator-stratified Mantel–Haenszel odds ratio of 3.23, regulator-cluster "\n            "bootstrap 95% interval 2.32–4.46 and leave-one-regulator-out range "\n            "2.94–3.50. Arce uses a selected library from the same laboratory, so this is "\n            "targeted corroboration rather than genome-wide independent replication."\n        )\n        write_text(staging / "CAPTION_DRAFT.md", caption + "\\n")\n        alt_text = (\n            "Six-panel Figure 3 diagnostic candidate. Panel a is a circular bipartite "\n            "network containing 532 of the 4,379 census reversals, selected by the "\n            "high-magnitude rule used by the current FigS7/R5 source. It contains 170 "\n            "regulator squares and 382 target "\n            f"circles; {overlap} regulator squares have gold outlines because they also "\n            "belong to the 49-regulator enriched family in panel c. CCNC, TADA2B, SUPT7L, "\n            "AHR and ARNT are labelled to connect the network to panels d and e. The purple "\n            "state-occupancy outlines used in standalone R5 are not shown. Of the two "\n            "differently defined regulator sets, "\n            "131 occur only in panel a and 10 occur only in panel c. "\n            "Panel b shows the frozen target "\n            "concentration and target-conditioned direction-unanimity results. Panel c "\n            "shows lost and gained reversal counts across six target functional groups "\n            "assembled from 19 KEGG-Legacy sets for all 49 Fisher/BH-enriched regulators. "\n            "Panels d and e show Rest and 48-hour net knockdown coefficients for every one "\n            "of the 16 targets shared by the cofactor trio and every one of the 17 "\n            "direction-concordant targets shared by AHR and ARNT; 10 are lost and 7 gained. "\n            "Filled circles mark the eight cofactor-trio targets that also appear among "\n            "Figure 4e\'s fixed top 28; the AHR–ARNT set has no such displayed overlap. "\n            "This is a display cross-reference rather than an enrichment result, because "\n            "Figure 4e\'s four-edge cutoff contains ties. Panel f is a "\n            "log-scale per-regulator forest showing that covered reversals re-reverse in "\n            "Arce more often than stable edges from the same 11 regulators, with the pooled "\n            "odds-ratio interval and leave-one-regulator-out band."\n        )\n        write_text(staging / "ALT_TEXT.md", alt_text + "\\n")\n\n        outputs = {\n            path.relative_to(staging).as_posix(): {\n                "sha256": sha256(path),\n                "size_bytes": path.stat().st_size,\n            }\n            for path in sorted(staging.rglob("*"))\n            if path.is_file()\n        }\n        script_path = Path(__file__).resolve()\n        manifest = {\n            "schema_version": "fig3-biological-bridge-r5-ahr-arce-candidate-v4",\n            "status": "DIAGNOSTIC_CANDIDATE_ONLY_PENDING_INDEPENDENT_AUDIT",\n            "canonical_figure_overwritten": False,\n            "panel_order": {\n                "a": "exact R5 high-magnitude descriptive subnetwork",\n                "b": "target concentration and direction unanimity",\n                "c": "all 49 Fisher/BH-enriched regulators and target functional groups",\n                "d": "CCNC-TADA2B-SUPT7L exhaustive 16-target heatmap",\n                "e": "AHR-ARNT exhaustive 17-target heatmap",\n                "f": "frozen regulator-stratified Arce external recurrence",\n            },\n            "regulator_views": {\n                "panel_a": (\n                    "170 carriers of the 532 among 4,379 census reversal edges satisfying "\n                    "the strict two-state magnitude rule; descriptive edge-filtered set"\n                ),\n                "panel_c": (\n                    "49 Fisher/BH-enriched regulators tested in the complete "\n                    "617-regulator family"\n                ),\n                "overlap": overlap,\n                "all49_absent_from_panel_a": absent_all49,\n                "overlap_encoding": (\n                    "gold outline on panel-a regulator squares; membership cross-reference only"\n                ),\n            },\n            "claim_boundary": (\n                "Panel a is a descriptive magnitude-filtered subnetwork, not a statistical "\n                "core or testability set. Its overlap with panel c is descriptive. Panels "\n                "c-e do not establish direct binding, mediation, pathway activity, or "\n                "target-level significance. The Figure 3d-to-Figure 4e overlap is a "\n                "descriptive cross-reference, not a test. Panel f is targeted "\n                "same-laboratory corroboration over a selected 11-regulator library, "\n                "not genome-wide independent replication."\n            ),\n            "canvas": {\n                "inches": [SOURCE_WIDTH_IN, SOURCE_HEIGHT_IN],\n                "a4_portrait": True,\n                "target_width_mm": TARGET_WIDTH_MM,\n                "minimum_source_font_pt": minimum_source,\n                "minimum_font_at_target_width_pt": minimum_print,\n                "opaque_background": True,\n                "png_mode": "RGB",\n                "pdf_fonttype": 42,\n                "text_outside_canvas": 0,\n                "text_text_bbox_collisions": 0,\n                "plotted_numeric_values_outside_axes": 0,\n            },\n            "layout": {\n                "rows": ["a-b", "c", "d-e-f"],\n                "top_width_ratios": [1.00, 1.35],\n                "bottom_width_ratios": list(BOTTOM_WIDTH_RATIOS),\n                "bottom_wspace": BOTTOM_WSPACE,\n                "panel_geometry": panel_geometry,\n                "heatmap_rows_preserved": {"d": 16, "e": 17},\n                "heatmap_columns": {"d": 6, "e": 4},\n                "heatmap_colorbar_scope": "panels d and e only",\n                "heatmap_colorbar_rect": list(COLORBAR_RECT),\n                "panel_d_key_to_colorbar_label_gap_pt": cross_axis_text_gap_pt,\n            },\n            "assertions": {\n                "r5_edges": len(r5_edges),\n                "r5_regulators": len(r5_regulators),\n                "r5_targets": len(r5_targets),\n                "r5_lost": int((r5_edges["direction"] == "lost_on_activation").sum()),\n                "r5_gained": int((r5_edges["direction"] == "gained_on_activation").sum()),\n                "r5_regulators_in_all49_family": overlap,\n                "r5_regulators_not_in_all49_family": len(r5_regulators) - overlap,\n                "all49_regulators_not_in_r5": len(all49) - overlap,\n                "all49_regulators": len(all49),\n                "all49_reversals": int(all49["total_reversals"].sum()),\n                "full_regulator_test_family": 617,\n                "cofactor_shared_targets": len(cofactor),\n                "sensor_shared_targets": len(sensor),\n                "sensor_direction_concordant_targets": int(\n                    bridge_manifest["tables"]["shared_reversal_targets_AHR_ARNT.csv"][\n                        "summary"\n                    ]["direction_concordant_targets"]\n                ),\n                "sensor_lost_targets": int((sensor["direction"] == "lost_on_activation").sum()),\n                "sensor_gained_targets": int((sensor["direction"] == "gained_on_activation").sum()),\n                "fig3d_targets_also_in_fig4e_top28": len(cofactor_fig4_overlap),\n                "fig3e_targets_also_in_fig4e_top28": len(sensor_fig4_overlap),\n                "fig3d_fig4e_overlap_targets": sorted(cofactor_fig4_overlap),\n                "fig4e_top_target_count": len(fig4_top_targets),\n                "fig4e_display_cutoff_supported_reversals": fig4_display_cutoff,\n                "fig4e_targets_above_cutoff": fig4_targets_above_cutoff,\n                "fig4e_targets_tied_at_cutoff": fig4_targets_tied_at_cutoff,\n                "fig4e_display_slots_at_cutoff": fig4_cutoff_slots,\n                "fig3d_targets_inclusive_at_fig4e_cutoff": len(\n                    cofactor_inclusive_overlap\n                ),\n                "fig3e_targets_inclusive_at_fig4e_cutoff": len(\n                    sensor_inclusive_overlap\n                ),\n                "arce_covered_reversals": int(arce_result["n_rev"]),\n                "arce_covered_stable_edges": int(arce_result["n_stable"]),\n                "arce_regulator_strata": int(arce_result["n_regulators"]),\n                "arce_reversal_recurrence_rate": float(arce_result["rev_flip_rate"]),\n                "arce_stable_recurrence_rate": float(arce_result["stable_flip_rate"]),\n                "arce_mh_odds_ratio": float(arce_result["or_mh"]),\n                "arce_cluster_bootstrap_ci": [\n                    float(value) for value in arce_result["cluster_boot_ci"]\n                ],\n                "arce_leave_one_regulator_out_range": [\n                    float(arce_result["loo_or_min"]),\n                    float(arce_result["loo_or_max"]),\n                ],\n                "panel_count": 6,\n                "case_labels": list(CASE_LABELS),\n                "all_case_labels_are_r5_regulators": True,\n                "all_case_labels_are_in_all49_family": True,\n                "purple_occupancy_outlines_included": False,\n                "failed_two_path_result_included": False,\n                "arce_panel_included": True,\n                "legacy_fig7_imported": False,\n                "new_statistics_rerun": False,\n            },\n            "cross_figure_bridge": {\n                "source_figure": "Figure 3d exhaustive 16-target cofactor intersection",\n                "destination_figure": "Figure 4e target-response display",\n                "destination_rule": (\n                    "among ESTIMATED_CONTINUOUS_COMPONENTS reversals, retain targets "\n                    "with at least 3 supported reversals, take the 28 largest target "\n                    "counts, then sort those 28 by count for display"\n                ),\n                "cofactor_overlap_n": len(cofactor_fig4_overlap),\n                "cofactor_overlap_targets": sorted(cofactor_fig4_overlap),\n                "sensor_overlap_n": len(sensor_fig4_overlap),\n                "sensor_overlap_targets": sorted(sensor_fig4_overlap),\n                "display_cutoff_supported_reversals": fig4_display_cutoff,\n                "targets_above_cutoff": fig4_targets_above_cutoff,\n                "targets_tied_at_cutoff": fig4_targets_tied_at_cutoff,\n                "display_slots_at_cutoff": fig4_cutoff_slots,\n                "cofactor_inclusive_at_cutoff_n": len(cofactor_inclusive_overlap),\n                "sensor_inclusive_at_cutoff_n": len(sensor_inclusive_overlap),\n                "encoding": "navy bold y-label plus filled-circle suffix in panel d",\n                "interpretation": (\n                    "exact rendered-display cross-reference only; cutoff ties make it "\n                    "unsuitable as a biological overlap test"\n                ),\n            },\n            "arce_source_contract": {\n                "source": relative(bridge.INPUTS["arce"]),\n                "panel_helper": "fig3_biological_bridge_candidate.panel_a_external",\n                "covered_reversals": int(arce_result["n_rev"]),\n                "covered_stable_edges": int(arce_result["n_stable"]),\n                "regulator_strata": int(arce_result["n_regulators"]),\n                "claim": (\n                    "targeted external perturbation recurrence under a different library, "\n                    "platform and donors from the same laboratory; not a genome-wide rate "\n                    "or unrelated-laboratory replication"\n                ),\n                "statistics_rerun_during_render": False,\n            },\n            "r5_source_contract": r5_contract,\n            "network_render": network_render,\n            "network_visual_encoding": {\n                "edge_color": "lost versus gained on activation",\n                "regulator_area": "square-root-rescaled R5 out-degree",\n                "target_area": "square-root-rescaled R5 in-degree",\n                "effector_target_fill": "fixed historical R5 T-cell effector list",\n                "gold_regulator_outline": "membership in panel c\'s 49-regulator family",\n                "positions": (\n                    "deterministic 60-iteration circular barycentre layout; no biological coordinate or module meaning"\n                ),\n            },\n            "self_contained_source_bundle": {\n                "all_renderer_data_and_reference_inputs_archived": True,\n                "retired_figure_bundle_dependencies": [],\n                "bundled_inputs": bundled_input_records,\n                "bundled_renderers": bundled_renderer_records,\n                "pin_scope": (\n                    "inside-bundle source_inputs and renderer_sources only; each byte-verified "\n                    "against the live source before atomic output promotion"\n                ),\n            },\n            "inputs": bundled_input_records,\n            "scripts": bundled_renderer_records,\n            "reference_assets": {\n                "FigS7_pdf": bundled_input_records["source_inputs/reference_FigS7.pdf"],\n                "FigS7_png": bundled_input_records["source_inputs/reference_FigS7.png"],\n            },\n            "outputs_before_manifest": outputs,\n            "determinism": {\n                "stable_identity_edge_selection": True,\n                "exact_FigS7_symbol_pair_equivalence_checked": True,\n                "fixed_barycentre_iterations": BARYCENTRE_ITERATIONS,\n                "fixed_pdf_metadata_dates": True,\n                "network_edge_collections_rasterized": True,\n                "output_directory_refuses_overwrite": True,\n                "atomic_directory_promotion": True,\n            },\n            "software": {\n                "python": sys.version.split()[0],\n                "matplotlib": matplotlib.__version__,\n                "numpy": np.__version__,\n                "pandas": pd.__version__,\n                "pillow": PILLOW_VERSION,\n            },\n        }\n        archived_records = [*bundled_input_records.values(), *bundled_renderer_records.values()]\n        if not all(record["source_sha256_verified"] for record in archived_records):\n            raise RuntimeError("self-contained source-bundle byte verification failed")\n        write_json(staging / "manifest.json", manifest)\n        pass\n        print(f"wrote diagnostic Figure 3 candidate: {relative(output_dir)}")\n        print(\n            f"minimum font: {minimum_source:.2f} pt source; "\n            f"{minimum_print:.2f} pt at {TARGET_WIDTH_MM:.1f} mm"\n        )\n        print(f"R5/all49 regulator overlap: {overlap}/170 and {overlap}/49")\n        print(\n            "bottom panel widths at target: "\n            + ", ".join(\n                f"{label}={panel_geometry[label][\'width_mm_at_target\']:.2f} mm"\n                for label in ("d", "e", "f")\n            )\n        )\n        print(\n            "heatmap tile widths at target: "\n            f"d={panel_geometry[\'d\'][\'tile_width_mm_at_target\']:.2f} mm; "\n            f"e={panel_geometry[\'e\'][\'tile_width_mm_at_target\']:.2f} mm"\n        )\n        print(\n            "Figure 3d/Figure 4e descriptive overlap: "\n            f"{len(cofactor_fig4_overlap)}/16; Figure 3e overlap: "\n            f"{len(sensor_fig4_overlap)}/17"\n        )\n        print(\n            "Figure 4e cutoff tie: "\n            f"cutoff={fig4_display_cutoff}; {fig4_targets_tied_at_cutoff} targets/"\n            f"{fig4_cutoff_slots} display slots; inclusive d/e="\n            f"{len(cofactor_inclusive_overlap)}/16 and {len(sensor_inclusive_overlap)}/17"\n        )\n        print(\n            "panel-d bridge key/colorbar label vertical gap: "\n            f"{cross_axis_text_gap_pt:.2f} pt"\n        )\n    except Exception:\n        if staging.exists():\n            pass\n        raise\n\n\ndef parse_args() -> argparse.Namespace:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUT)\n    return parser.parse_args()\n\n\nif __name__ == "__main__":\n    arguments = parse_args()\n    build(arguments.output_dir.expanduser().resolve())\n'
