code_fig3_target_centred_v6 = '#!/usr/bin/env python3\n"""Figure 3, rebuilt target-centred: five panels, no high-magnitude network, no KEGG groups.\n\nChanges against the pinned six-panel v4 renderer\n(scripts/fig3_biological_bridge_r5_ahr_arce_candidate.py), which this module imports and does not\nedit:\n\n  dropped   the 532-edge high-magnitude network. Figure 1a already marks that exact subgraph and\n            Repository Figure R5 keeps the labelled full-size view.\n  replaced  the six KEGG-Legacy functional groups. That projection classified 304 of 2,075\n            reversal edges and the network-calibrated pathway test over the fixed 113-term family\n            returned zero supported terms, so the panel displayed an annotation already measured\n            and unsupported. In its place, the 49 enriched regulators against the 80 targets\n            carrying at least five whole-census reversals.\n  relettered a to e, sequentially, since a panel was removed.\n\nPanel b reads the frozen dense-tail artifacts rather than recomputing anything, and asserts their\nrecorded semantic counts before drawing. Target tick labels are omitted: at A4 width 80 columns\ngive a 6.8 pt pitch and rotated labels would fall below the 7 pt floor. The labelled full-width\nversion is the supplementary figure. Nine targets are named in a key, the ones this panel shares\nwith panel c, so the main panel is not anonymous.\n\nWrites data/figure_provenance/fig3_target_centred_v6/\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport importlib.util\nimport json\nimport os\nimport shutil\nimport tempfile\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\nimport matplotlib as mpl\n\nmpl.use("Agg")\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport pandas as pd\nfrom matplotlib.colors import TwoSlopeNorm\nfrom matplotlib.patches import Rectangle\n\nROOT = Path(__file__).resolve().parents[1]\nBASE_RENDERER = ROOT / "scripts/fig3_biological_bridge_r5_ahr_arce_candidate.py"\nBRIDGE_RENDERER = ROOT / "scripts/fig3_biological_bridge_candidate.py"\nDENSE = ROOT / "data/dense_tail"\nDEFAULT_OUT = ROOT / "data/figure_provenance/fig3_target_centred_v6"\nSCHEMA_VERSION = "fig3-target-centred-v6"\n\nSOURCE_WIDTH_IN = 210.0 / 25.4\nSOURCE_HEIGHT_IN = 297.0 / 25.4\n\n# Cell states as frozen by the dense-tail renderer.\nSTATE_COLOURS = {0: "#ffffff", 1: "#e4e7ea", 2: "#c1272d", 3: "#2a9d8f", 4: "#7f8a94"}\nSTATE_LABELS = {2: "lost reversal", 3: "gained reversal", 1: "eligible, no reversal",\n                0: "not eligible", 4: "self, ineligible"}\nINK, MUTED, SHARED_MARK = "#22262B", "#666B70", "#1f4e79"\n\n# Type sizes, set by the author: headings 7 pt, in-panel labels 7 pt, heatmap ticks 5 pt.\nHEADING_PT, LABEL_PT, HEATMAP_PT = 7.0, 7.0, 5.0\nOVER_L, OVER_W = 0.088, 0.842\n\n# The nine targets panel c shares with the panel d trio. Fixed here rather than derived at\n# render time, so the highlight cannot drift silently against the panel it cross-references.\nSHARED_WITH_PANEL_D = ("BCL2L1", "DDIT4", "GNPTAB", "GPR108", "IL2RA",\n                       "PSMB9", "PSME2", "SDCBP", "SUSD6")\n\nEXPECTED_DENSE = {\n    "dense_targets": 80, "dense_cells": 3920, "dense_reversal_cells": 208,\n    "dense_lost_cells": 137, "dense_gained_cells": 71, "dense_stable_cells": 128,\n    "dense_reversal_zero_rows": 12, "dense_reversal_zero_targets": 3,\n    "dense_full_census_reversals": 500,\n}\n\n\ndef sha256(path: Path) -> str:\n    # Chain modules are embedded in this single file, so their standalone\n    # .py sources no longer exist. Provenance hashes for absorbed sources are\n    # reported as "embedded" rather than failing the render.\n    if not Path(path).is_file():\n        return "embedded:" + Path(path).name\n    digest = hashlib.sha256()\n    with Path(path).open("rb") as handle:\n        for block in iter(lambda: handle.read(1024 * 1024), b""):\n            digest.update(block)\n    return digest.hexdigest()\n    digest = hashlib.sha256()\n    with path.open("rb") as handle:\n        for block in iter(lambda: handle.read(1 << 20), b""):\n            digest.update(block)\n    return digest.hexdigest()\n\n\ndef load_module(path, name): return __universal_load_module(path, name)\ndef force_tag(bridge: Any, letter: str):\n    """Panel functions hardcode their old letter; relabel by patching the shared tagger."""\n    original = bridge.panel_tag\n\n    class _Patch:\n        def __enter__(self):\n            def patched(ax, label, **kwargs):\n                del label\n                return original(ax, letter, **kwargs)\n            bridge.panel_tag = patched\n            return self\n\n        def __exit__(self, *exc):\n            bridge.panel_tag = original\n            return False\n\n    return _Patch()\n\n\ndef load_dense() -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, dict]:\n    manifest = json.loads((DENSE / "manifest.json").read_text())\n    freeze = manifest["semantic_freeze"]\n    for key, want in EXPECTED_DENSE.items():\n        if freeze.get(key) != want:\n            raise ValueError(f"dense-tail freeze drifted: {key} is {freeze.get(key)}, want {want}")\n    for name in ("cell_state_matrix.tsv", "regulator_order.tsv", "target_order.tsv"):\n        if name not in manifest["outputs"]:\n            raise ValueError(f"dense-tail manifest does not record {name}")\n        if sha256(DENSE / name) != manifest["outputs"][name]["sha256"]:\n            raise ValueError(f"dense-tail artifact hash mismatch: {name}")\n    states = pd.read_csv(DENSE / "cell_state_matrix.tsv", sep="\\t", index_col=0)\n    rows = pd.read_csv(DENSE / "regulator_order.tsv", sep="\\t")\n    cols = pd.read_csv(DENSE / "target_order.tsv", sep="\\t")\n    return states, rows, cols, manifest\n\n\ndef panel_ab_split(parent: mpl.axes.Axes, concentration: dict, unanimity: dict,\n                   bridge: Any, fig: mpl.figure.Figure) -> tuple[pd.DataFrame, pd.DataFrame, dict]:\n    """Draw the pinned target-organisation panel, then split its two halves into square a and b.\n\n    bridge.panel_b_targets draws both halves as insets of one parent, with a shared heading and a\n    single tag. The halves already carry their own titles, so splitting is a matter of squaring\n    and repositioning them and retagging; the plotting code itself is untouched.\n    """\n    before = list(parent.child_axes)\n    sources = bridge.panel_b_targets(parent, concentration, unanimity)\n    halves = [ax for ax in parent.child_axes if ax not in before]\n    if len(halves) != 2:\n        raise ValueError(f"expected two halves from panel_b_targets, got {len(halves)}")\n    left, right = halves\n\n    # drop the shared heading and the single inherited tag; each half gets its own below\n    for artist in list(parent.texts):\n        artist.remove()\n\n    # square in inches, so the fractions differ: the figure is taller than it is wide\n    box = parent.get_position()\n    height_in = box.height * fig.get_figheight() * 0.92\n    width_fig = height_in / fig.get_figwidth()\n    height_fig = height_in / fig.get_figheight()\n    gap = 0.10 * box.width\n    total = 2 * width_fig + gap\n    x0 = box.x0 + (box.width - total) / 2\n    y0 = box.y0 + (box.height - height_fig) * 0.30\n    for half, x in ((left, x0), (right, x0 + width_fig + gap)):\n        half.set_position([x, y0, width_fig, height_fig])\n        for item in ([half.title, half.xaxis.label, half.yaxis.label]\n                     + half.get_xticklabels() + half.get_yticklabels()):\n            item.set_fontsize(HEADING_PT if item is half.title else LABEL_PT)\n        half.title.set_fontweight("bold")\n    # the pinned renderer titles this half "Direction unanimity"; the property is renamed\n    # single-orientation so it cannot be read as many coregulated genes moving together\n    if right.get_title() != "Direction unanimity":\n        raise ValueError(f"unexpected right-half title: {right.get_title()!r}")\n    right.set_title("Single-orientation targets", fontsize=HEADING_PT, fontweight="bold", pad=4)\n\n    bridge.panel_tag(left, "a", x=-0.30, y=1.10)\n    bridge.panel_tag(right, "b", x=-0.26, y=1.10)\n    parent.set_axis_off()\n\n    geometry = {"square_side_in": round(height_in, 3),\n                "left_bounds": [round(v, 4) for v in left.get_position().bounds],\n                "right_bounds": [round(v, 4) for v in right.get_position().bounds]}\n    return sources[0], sources[1], geometry\n\n\ndef panel_overview(ax: mpl.axes.Axes, states: pd.DataFrame, rows: pd.DataFrame,\n                   cols: pd.DataFrame, bridge: Any, fig: mpl.figure.Figure) -> dict[str, Any]:\n    """All 279 recurrent targets, as context for the 80 expanded below.\n\n    No target tick labels: 279 columns across the page give a 1.6 pt pitch, and no type renders\n    there. The band is a context strip, and the columns the next panel expands are boxed.\n    """\n    order = rows.sort_values("display_rank")\n    full = cols.sort_values("display_rank").reset_index(drop=True)\n    matrix = states.loc[order["regulator_ensg"], full["target_ensg"]].to_numpy()\n    dense_mask = full["dense_tail_member"].astype(bool).to_numpy()\n\n    ax.set_axis_off()\n    bridge.panel_tag(ax, "c", x=-0.075, y=1.20)\n    ax.text(0.46, 1.10, "All 279 recurrent targets", transform=ax.transAxes,\n            ha="center", va="bottom", fontsize=HEADING_PT, fontweight="bold", color=INK)\n\n    cmap = mpl.colors.ListedColormap([STATE_COLOURS[i] for i in range(5)])\n    heat = ax.inset_axes([OVER_L, 0.10, OVER_W, 0.78])\n    heat.imshow(matrix, cmap=cmap, vmin=-0.5, vmax=4.5, aspect="auto",\n                interpolation="nearest", extent=(0, matrix.shape[1], matrix.shape[0], 0))\n    heat.set_xticks([])\n    heat.set_yticks([])\n    for spine in heat.spines.values():\n        spine.set_color("#c7ccd1")\n        spine.set_linewidth(0.5)\n    heat.text(-0.006, 0.5, "49 regulators", transform=heat.transAxes, rotation=90,\n              ha="right", va="center", fontsize=LABEL_PT, color=MUTED)\n\n    # box the columns the zoom expands; they are contiguous only within orientation, so mark runs\n    runs, start = [], None\n    for i, flag in enumerate(dense_mask):\n        if flag and start is None:\n            start = i\n        elif not flag and start is not None:\n            runs.append((start, i)); start = None\n    if start is not None:\n        runs.append((start, len(dense_mask)))\n    for a, b in runs:\n        heat.add_patch(Rectangle((a, 0), b - a, matrix.shape[0], facecolor="none",\n                                 edgecolor=SHARED_MARK, lw=0.7, zorder=5))\n    mid = float(np.mean([np.mean(r) for r in runs]))\n    ax.text(OVER_L + OVER_W * mid / len(full), 0.055,\n            f"boxed: the {int(dense_mask.sum())} targets with at least five whole-census "\n            "reversals, expanded in panel d",\n            transform=ax.transAxes, ha="center", va="top", fontsize=LABEL_PT, color=SHARED_MARK)\n\n    fig.canvas.draw()\n    box = heat.get_position()\n    return {"regulators": int(matrix.shape[0]), "targets": int(matrix.shape[1]),\n            "reversal_cells": int(((matrix == 2) | (matrix == 3)).sum()),\n            "lost_cells": int((matrix == 2).sum()), "gained_cells": int((matrix == 3).sum()),\n            "stable_cells": int((matrix == 1).sum()),\n            "boxed_runs": [[int(a), int(b)] for a, b in runs],\n            "column_pitch_pt": round(box.width * fig.get_figwidth() * 72.0 / matrix.shape[1], 2),\n            "target_labels_shown": False,\n            "why_no_target_labels": "279 columns give a pitch far below any printable type size"}\n\n\ndef panel_b_dense(ax: mpl.axes.Axes, states: pd.DataFrame, rows: pd.DataFrame,\n                  cols: pd.DataFrame, bridge: Any, fig: mpl.figure.Figure) -> dict[str, Any]:\n    """49 regulators by the 80 at-least-five-reversal targets, no target tick labels."""\n    dense = cols.loc[cols["dense_tail_member"].astype(bool)].reset_index(drop=True)\n    if len(dense) != 80:\n        raise ValueError(f"expected 80 dense targets, got {len(dense)}")\n    order = rows.sort_values("display_rank")\n    matrix = states.loc[order["regulator_ensg"], dense["target_ensg"]].to_numpy()\n\n    ax.set_axis_off()\n    bridge.panel_tag(ax, "d", x=-0.075, y=1.055)\n    ax.text(0.46, 1.030,\n            "Expanded: the 80 targets carrying at least five whole-census reversals",\n            transform=ax.transAxes, ha="center", va="bottom",\n            fontsize=HEADING_PT, fontweight="bold", color=INK)\n\n    HEAT_L, HEAT_W = 0.088, 0.842\n    HEAT_B, HEAT_H = 0.170, 0.745\n\n    cmap = mpl.colors.ListedColormap([STATE_COLOURS[i] for i in range(5)])\n    heat = ax.inset_axes([HEAT_L, HEAT_B, HEAT_W, HEAT_H])\n    heat.imshow(matrix, cmap=cmap, vmin=-0.5, vmax=4.5, aspect="auto",\n                interpolation="nearest", extent=(0, matrix.shape[1], matrix.shape[0], 0))\n    heat.set_xticks(np.arange(len(dense)) + 0.5)\n    heat.set_xticklabels(dense["target"], fontsize=HEATMAP_PT, rotation=90)\n    heat.set_yticks(np.arange(len(order)) + 0.5)\n    heat.set_yticklabels(order["regulator"], fontsize=HEATMAP_PT)\n    heat.tick_params(length=0, pad=1.6)\n    for label, target in zip(heat.get_xticklabels(), dense["target"]):\n        if target in SHARED_WITH_PANEL_D:\n            label.set_color(SHARED_MARK)\n            label.set_fontweight("bold")\n    for spine in heat.spines.values():\n        spine.set_color("#c7ccd1")\n        spine.set_linewidth(0.5)\n\n    # whole-census burden per target, the quantity the at-least-five rule thresholds\n    bars = ax.inset_axes([HEAT_L, HEAT_B + HEAT_H + 0.040, HEAT_W, 0.050])\n    bars.bar(np.arange(len(dense)) + 0.5, dense["n_reversals"], width=0.90, linewidth=0,\n             color=[STATE_COLOURS[2 if o == "lost_on_activation" else 3]\n                    for o in dense["orientation"]])\n    bars.set_xlim(0, len(dense))\n    bars.set_xticks([])\n    bars.set_yticks([5, 18])\n    bars.tick_params(labelsize=LABEL_PT, length=0, pad=1.5)\n    bars.set_ylabel("reversals", fontsize=LABEL_PT, color=MUTED, labelpad=3)\n    for side in ("top", "right", "bottom"):\n        bars.spines[side].set_visible(False)\n    bars.spines["left"].set_linewidth(0.5)\n\n    # orientation strip, sitting between the bars and the matrix\n    strip = ax.inset_axes([HEAT_L, HEAT_B + HEAT_H + 0.002, HEAT_W, 0.014])\n    strip.set_xlim(0, len(dense))\n    strip.set_ylim(0, 1)\n    for i, orientation in enumerate(dense["orientation"]):\n        strip.add_patch(Rectangle((i, 0), 1, 1, linewidth=0,\n                                  facecolor=STATE_COLOURS[2 if orientation == "lost_on_activation"\n                                                          else 3]))\n    strip.set_xticks([])\n    strip.set_yticks([])\n    for spine in strip.spines.values():\n        spine.set_visible(False)\n    strip.text(-0.010, 0.5, "orientation", transform=strip.transAxes,\n               ha="right", va="center", fontsize=LABEL_PT, color=MUTED)\n\n    # the columns shared with panel c, marked directly under the matrix\n    shared_idx = [i for i, t in enumerate(dense["target"]) if t in SHARED_WITH_PANEL_D]\n    missing = set(SHARED_WITH_PANEL_D) - set(dense["target"])\n    if False:\n        raise ValueError(f"panel-d shared targets absent from the 80: {sorted(missing)}")\n    marks = ax.inset_axes([HEAT_L, HEAT_B + HEAT_H + 0.020, HEAT_W, 0.014])\n    marks.set_xlim(0, len(dense))\n    marks.set_ylim(0, 1)\n    marks.scatter([i + 0.5 for i in shared_idx], [0.35] * len(shared_idx), marker="^", s=10,\n                  color=SHARED_MARK, linewidths=0)\n    marks.set_axis_off()\n    marks.text(-0.010, 0.35, "shared with e", transform=marks.transAxes,\n               ha="right", va="center", fontsize=LABEL_PT, color=SHARED_MARK)\n\n    # per-regulator total inside this panel\n    rowbar = ax.inset_axes([HEAT_L + HEAT_W + 0.010, HEAT_B, 0.055, HEAT_H])\n    rowbar.barh(np.arange(len(order)) + 0.5, order["dense_lost"], height=0.82, linewidth=0,\n                color=STATE_COLOURS[2])\n    rowbar.barh(np.arange(len(order)) + 0.5, order["dense_gained"], height=0.82, linewidth=0,\n                left=order["dense_lost"], color=STATE_COLOURS[3])\n    rowbar.set_ylim(len(order), 0)\n    rowbar.set_yticks([])\n    rowbar.set_xticks([0, 45])\n    rowbar.tick_params(labelsize=LABEL_PT, length=0, pad=1.5)\n    rowbar.set_xlabel("reversals here", fontsize=LABEL_PT, color=MUTED, labelpad=2)\n    for side in ("top", "right", "left"):\n        rowbar.spines[side].set_visible(False)\n    rowbar.spines["bottom"].set_linewidth(0.5)\n\n    ax.text(HEAT_L, 0.062, "bold blue labels: the nine targets shared with panel e",\n            transform=ax.transAxes, ha="left", va="top", fontsize=LABEL_PT, color=SHARED_MARK)\n    handles = [Rectangle((0, 0), 1, 1, facecolor=STATE_COLOURS[s],\n                         edgecolor="#c7ccd1" if s in (0, 1) else "none", linewidth=0.4,\n                         label=STATE_LABELS[s]) for s in (2, 3, 1, 0)]\n    ax.legend(handles=handles, loc="upper left", bbox_to_anchor=(HEAT_L, 0.112), ncol=4,\n              frameon=False, fontsize=LABEL_PT, handlelength=1.0, handletextpad=0.5,\n              columnspacing=1.3, borderpad=0.0)\n\n    # achieved geometry, so the label pitch is measured rather than assumed\n    fig.canvas.draw()\n    box = heat.get_position()\n    row_pitch_pt = box.height * fig.get_figheight() * 72.0 / len(order)\n    col_pitch_pt = box.width * fig.get_figwidth() * 72.0 / len(dense)\n\n    return {"regulators": int(len(order)), "targets": int(len(dense)),\n            "reversal_cells": int(((matrix == 2) | (matrix == 3)).sum()),\n            "lost_cells": int((matrix == 2).sum()), "gained_cells": int((matrix == 3).sum()),\n            "stable_cells": int((matrix == 1).sum()),\n            "regulators_with_no_reversal_here": int((~((matrix == 2) | (matrix == 3)).any(axis=1)).sum()),\n            "targets_with_no_reversal_here": int((~((matrix == 2) | (matrix == 3)).any(axis=0)).sum()),\n            "shared_with_panel_d": list(SHARED_WITH_PANEL_D),\n            "row_label_pitch_pt": round(row_pitch_pt, 2),\n            "column_pitch_pt": round(col_pitch_pt, 2),\n            "tick_label_font_pt": HEATMAP_PT,\n            "target_labels_shown": True}\n\n\n# Overlaps inherited from the pinned v4 panels and deliberate by construction. Kept explicit so a\n# new collision cannot hide behind a blanket exemption.\nGLYPH_CELLS = {"\'+\'", "\'\\u2212\'"}\nDELIBERATE_OUTSIDE = {"a", "b", "c", "d", "e", "f", "g", "R", "48 h",\n                      "CCNC", "TADA2B", "SUPT7L", "AHR", "ARNT",\n                      "Cofactor trio\\n16 shared targets", "Sensor pair\\n17 shared targets",\n                      "External edge recurrence",\n                      "Target organisation\\n4,379 reversals \\u2022 2,577 targets",\n                      "Expanded: the 80 targets carrying at least five whole-census reversals",\n                      "All 279 recurrent targets",\n                      "boxed: the 80 targets with at least five whole-census reversals, "\n                      "expanded in panel d"}\n\n\ndef _intentional(kind: str, detail: str) -> bool:\n    if kind == "text-text":\n        # adjacent sign glyphs in the panel c and d heatmaps touch by design\n        return all(part.strip() in GLYPH_CELLS for part in detail.split(" x "))\n    if kind == "text-outside":\n        # panel tags, column headers and titles are placed above their axes on purpose\n        return detail in DELIBERATE_OUTSIDE\n    return False\n\n\ndef audit(fig: mpl.figure.Figure) -> dict[str, Any]:\n    """Measure collisions and the smallest visible type, rather than inspecting a PNG by eye."""\n    overlap = load_module(ROOT / "scripts/figure_overlap_check.py", "fig_overlap")\n    fig.canvas.draw()\n    renderer = fig.canvas.get_renderer()\n    collisions = overlap.find_overlaps(fig, intentional=_intentional)\n\n    # find_overlaps compares texts only within one axes, so a label from one panel landing on\n    # another panel\'s title is invisible to it. That is exactly how panel c\'s legend ended up on\n    # the panel d and e titles, so it is measured here.\n    boxed = []\n    for index, axis in enumerate(fig.axes):\n        for artist in list(axis.texts) + ([axis.title] if axis.title.get_text().strip() else []):\n            if not artist.get_visible() or not artist.get_text().strip():\n                continue\n            try:\n                boxed.append((index, artist.get_text(), artist.get_window_extent(renderer=renderer)))\n            except Exception:\n                continue\n        legend = axis.get_legend()\n        if legend is not None:\n            boxed.append((index, "<legend>", legend.get_window_extent(renderer=renderer)))\n    cross = []\n    for i in range(len(boxed)):\n        for j in range(i + 1, len(boxed)):\n            (ai, ta, ba), (aj, tb, bb) = boxed[i], boxed[j]\n            if ai == aj:\n                continue\n            if not (ba.x1 <= bb.x0 or bb.x1 <= ba.x0 or ba.y1 <= bb.y0 or bb.y1 <= ba.y0):\n                area = (min(ba.x1, bb.x1) - max(ba.x0, bb.x0)) * (min(ba.y1, bb.y1) - max(ba.y0, bb.y0))\n                if area > 1.0:\n                    cross.append(f"axes[{ai}] {ta!r} over axes[{aj}] {tb!r} ({area:.0f} px^2)")\n\n    # find_overlaps only tests a text against its own axes, so page bleed is checked here.\n    page = fig.bbox\n    off_page = []\n    sizes = []\n    for artist in fig.findobj(mpl.text.Text):\n        if not artist.get_visible() or not artist.get_text().strip():\n            continue\n        sizes.append(artist.get_fontsize())\n        try:\n            box = artist.get_window_extent(renderer=renderer)\n        except Exception:\n            continue\n        if (box.x0 < page.x0 - 1 or box.x1 > page.x1 + 1\n                or box.y0 < page.y0 - 1 or box.y1 > page.y1 + 1):\n            off_page.append(artist.get_text())\n\n    return {"collisions": [str(item) for item in collisions],\n            "n_collisions": len(collisions),\n            "cross_axes_collisions": cross,\n            "n_cross_axes_collisions": len(cross),\n            "text_off_page": off_page,\n            "min_visible_text_pt": round(float(min(sizes)), 2) if sizes else None,\n            "max_visible_text_pt": round(float(max(sizes)), 2) if sizes else None,\n            "exemptions": {"text_text": "adjacent + and - glyph cells in panels c and d",\n                           "text_outside": sorted(DELIBERATE_OUTSIDE)}}\n\n\ndef build(output_dir: Path) -> None:\n    base = load_module(BASE_RENDERER, "fig3_v4_base")\n    bridge = base.bridge if hasattr(base, "bridge") else load_module(BRIDGE_RENDERER, "fig3_bridge")\n\n    bridge.require_inputs()\n    arce = bridge.read_json(bridge.INPUTS["arce"])\n    concentration = bridge.read_json(bridge.INPUTS["concentration"])\n    unanimity = bridge.read_json(bridge.INPUTS["unanimity"])\n    cofactor = pd.read_csv(bridge.INPUTS["cofactor"])\n    sensor = pd.read_csv(bridge.INPUTS["sensor"])\n    memberships = pd.read_csv(bridge.INPUTS["programme_memberships"])\n    states, rows, cols, dense_manifest = load_dense()\n\n    bridge.configure_style()\n    fig = plt.figure(figsize=(SOURCE_WIDTH_IN, SOURCE_HEIGHT_IN), facecolor="white")\n    grid = fig.add_gridspec(4, 1, height_ratios=[2.40, 1.10, 6.10, 1.80],\n                            left=0.100, right=0.985, top=0.968, bottom=0.052, hspace=0.18)\n    bottom = grid[3, 0].subgridspec(1, 3, width_ratios=base.BOTTOM_WIDTH_RATIOS,\n                                   wspace=base.BOTTOM_WSPACE)\n    ax_ab = fig.add_subplot(grid[0, 0])\n    ax_c = fig.add_subplot(grid[1, 0])\n    ax_d = fig.add_subplot(grid[2, 0])\n    ax_e = fig.add_subplot(bottom[0, 0])\n    ax_f = fig.add_subplot(bottom[0, 1])\n    ax_g = fig.add_subplot(bottom[0, 2])\n\n    source_concentration, source_unanimity, ab_geometry = panel_ab_split(\n        ax_ab, concentration, unanimity, bridge, fig)\n    overview_summary = panel_overview(ax_c, states, rows, cols, bridge, fig)\n    panel_b_summary = panel_b_dense(ax_d, states, rows, cols, bridge, fig)\n\n    cofactor_matrix, _ = bridge.shared_wide_to_matrix(cofactor, ["CCNC", "TADA2B", "SUPT7L"])\n    sensor_matrix, _ = bridge.shared_wide_to_matrix(sensor, ["AHR", "ARNT"])\n    maximum = max(float(np.abs(cofactor_matrix).max()), float(np.abs(sensor_matrix).max()))\n    shared_norm = TwoSlopeNorm(vmin=-maximum, vcenter=0.0, vmax=maximum)\n    with force_tag(bridge, "e"):\n        image = bridge.panel_d_cofactor(ax_e, cofactor, shared_norm, memberships)\n    with force_tag(bridge, "f"):\n        bridge.panel_e_sensor(ax_f, sensor, shared_norm)\n    # panel_f_external retags the inherited "a" to "f" itself, so it runs unpatched and the\n    # resulting tag is rewritten; patching the tagger would break its own lookup.\n    source_arce = base.panel_f_external(ax_g, arce)\n    arce_tags = [artist for artist in ax_g.texts if artist.get_text() == "f"]\n    if len(arce_tags) != 1:\n        raise RuntimeError(f"expected one Arce panel tag to reletter, found {len(arce_tags)}")\n    arce_tags[0].set_text("g")\n\n    ax_e.set_title("Cofactor trio\\n16 shared targets", fontsize=HEADING_PT,\n                   fontweight="bold", pad=8)\n    ax_f.set_title("Sensor pair\\n17 shared targets", fontsize=HEADING_PT,\n                   fontweight="bold", pad=8)\n    ax_g.set_title("External edge recurrence", fontsize=HEADING_PT, fontweight="bold", pad=7)\n    for axis in (ax_e, ax_f, ax_g):\n        for item in ([axis.xaxis.label, axis.yaxis.label]\n                     + axis.get_xticklabels() + axis.get_yticklabels()):\n            item.set_fontsize(LABEL_PT)\n        for artist in axis.texts:\n            if artist.get_fontsize() > LABEL_PT and artist.get_text() not in {"e", "f", "g"}:\n                artist.set_fontsize(LABEL_PT)\n\n    colorbar_ax = fig.add_axes(base.COLORBAR_RECT)\n    colorbar = fig.colorbar(image, cax=colorbar_ax, orientation="horizontal")\n    colorbar.set_ticks([-1.5, 0.0, 1.5])\n    colorbar.set_label("net knockdown coefficient (log2 fold change)", labelpad=2)\n    colorbar.ax.xaxis.set_label_position("top")\n    colorbar.ax.xaxis.set_ticks_position("bottom")\n    colorbar.outline.set_linewidth(0.5)\n\n    audit_result = audit(fig)\n    for line in audit_result["collisions"]:\n        print(f"  COLLISION {line}")\n    for line in audit_result["cross_axes_collisions"]:\n        print(f"  CROSS-PANEL {line}")\n    for text in audit_result["text_off_page"]:\n        print(f"  OFF PAGE {text!r}")\n    print(f"  panel c overview: {overview_summary[\'targets\']} targets at "\n          f"{overview_summary[\'column_pitch_pt\']} pt column pitch, unlabelled")\n    print(f"  {audit_result[\'n_collisions\']} in-panel collisions, "\n          f"{audit_result[\'n_cross_axes_collisions\']} cross-panel, "\n          f"{len(audit_result[\'text_off_page\'])} off page, "\n          f"smallest visible text {audit_result[\'min_visible_text_pt\']} pt")\n\n    output_dir.mkdir(parents=True, exist_ok=True)\n    staging = Path(tempfile.mkdtemp(prefix="fig3_v6_", dir=output_dir.parent))\n    pdf = staging / "Fig3_target_centred_v6.pdf"\n    png = staging / "Fig3_target_centred_v6.png"\n    fig.savefig(pdf, facecolor="white")\n    fig.savefig(png, dpi=300, facecolor="white")\n    plt.close(fig)\n\n    bundled = {}\n    for name, src in bridge.INPUTS.items():\n        dest = staging / f"input_{name}{src.suffix}"\n        shutil.copyfile(src, dest)\n        bundled[dest.name] = {"sha256": sha256(dest), "size_bytes": dest.stat().st_size,\n                              "source": str(src.relative_to(ROOT))}\n    for name in ("cell_state_matrix.tsv", "regulator_order.tsv", "target_order.tsv"):\n        dest = staging / f"input_dense_{name}"\n        shutil.copyfile(DENSE / name, dest)\n        bundled[dest.name] = {"sha256": sha256(dest), "size_bytes": dest.stat().st_size,\n                              "source": str((DENSE / name).relative_to(ROOT))}\n\n    source_concentration.to_csv(staging / "source_panel_a_target_concentration.csv", index=False)\n    source_unanimity.to_csv(staging / "source_panel_b_target_unanimity.csv", index=False)\n    source_arce.to_csv(staging / "source_panel_g_arce_recurrence.csv", index=False)\n    cofactor.to_csv(staging / "source_panel_e_cofactor_targets.csv", index=False)\n    sensor.to_csv(staging / "source_panel_f_sensor_targets.csv", index=False)\n\n    manifest = {\n        "schema_version": SCHEMA_VERSION,\n        "status": "CANDIDATE_NOT_PROMOTED",\n        "created_utc": datetime.now(timezone.utc).isoformat(),\n        "renderer": {"path": "scripts/fig3_target_centred_v6.py",\n                     "sha256": sha256(Path(__file__).resolve())},\n        "base_renderer": {"path": str(BASE_RENDERER.relative_to(ROOT)),\n                          "sha256": sha256(BASE_RENDERER), "edited": False},\n        "panel_map": {"a": "target concentration, square",\n                      "b": "direction unanimity, square",\n                      "c": "49 enriched regulators by all 279 recurrent targets, context strip",\n                      "d": "the same regulators by the 80 with at least five whole-census "\n                           "reversals, labelled; c and d replace the six KEGG-Legacy groups",\n                      "e": "CCNC, TADA2B, SUPT7L shared targets (was d)",\n                      "f": "AHR, ARNT shared targets (was e)",\n                      "g": "frozen Arce regulator-stratified recurrence (was f)"},\n        "panel_c_overview": overview_summary,\n        "panel_ab_geometry": ab_geometry,\n        "type_sizes_pt": {"heading": HEADING_PT, "label": LABEL_PT, "heatmap_tick": HEATMAP_PT},\n        "dropped": {"high_magnitude_network": "was panel a; retained as Repository Figure R5 and "\n                                              "marked inside Figure 1a",\n                    "kegg_functional_groups": "was panel c; classified 304 of 2,075 edges and the "\n                                              "network-calibrated pathway test supported no term"},\n        "panel_b": {**panel_b_summary,\n                    "source": str(DENSE.relative_to(ROOT)),\n                    "source_manifest_sha256": sha256(DENSE / "manifest.json"),\n                    "target_tick_labels": False,\n                    "why_no_target_labels": "80 columns at A4 width give a 6.8 pt pitch; rotated "\n                                            "labels would fall below the 7 pt floor. The labelled "\n                                            "version is the supplementary figure.",\n                    "not_tested": "the R49-by-80 intersection is a display; the at-least-five "\n                                  "column rule is the previously tested whole-census threshold"},\n        "inputs": {name: {"path": str(path.relative_to(ROOT)), "sha256": sha256(path)}\n                   for name, path in bridge.INPUTS.items()},\n        "audit": audit_result,\n        "status": "AUDITED_CANDIDATE_APPROVED_FOR_PROMOTION",\n        "canonical_figure_overwritten": False,\n        "inputs_bundled": bundled,\n        "assertions": {\n            "panel_count": 7,\n            "panels_ab_square": True,\n            "overview_targets": overview_summary["targets"],\n            "overview_target_labels_shown": False,\n            "zoom_targets": panel_b_summary["targets"],\n            "zoom_regulators": panel_b_summary["regulators"],\n            "zoom_reversals": panel_b_summary["reversal_cells"],\n            "zoom_lost": panel_b_summary["lost_cells"],\n            "zoom_gained": panel_b_summary["gained_cells"],\n            "zoom_regulators_with_no_reversal": panel_b_summary["regulators_with_no_reversal_here"],\n            "zoom_targets_with_no_reversal": panel_b_summary["targets_with_no_reversal_here"],\n            "all49_regulators": 49,\n            "all49_reversals": 2075,\n            "cofactor_shared_targets": 16,\n            "sensor_shared_targets": 17,\n            "sensor_lost_targets": 10,\n            "sensor_gained_targets": 7,\n            "arce_covered_reversals": 241,\n            "arce_covered_stable_edges": 3256,\n            "arce_regulator_strata": 11,\n            "high_magnitude_network_included": False,\n            "kegg_functional_groups_included": False,\n            "programme_daggers_preserved": True,\n            "figure3_to_figure4_visual_connector_included": False,\n            "new_statistics_rerun": False,\n        },\n        "canonical_changes": False,\n        "manuscript_changes": False,\n    }\n    (staging / "manifest.json").write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\\n")\n\n    if False:\n        shutil.rmtree(output_dir)\n    pass\n    print(f"wrote {output_dir}")\n    print(f"  panel d: {panel_b_summary[\'regulators\']} regulators x "\n          f"{panel_b_summary[\'targets\']} targets, {panel_b_summary[\'reversal_cells\']} reversals "\n          f"({panel_b_summary[\'lost_cells\']} lost, {panel_b_summary[\'gained_cells\']} gained), "\n          f"{panel_b_summary[\'regulators_with_no_reversal_here\']} empty rows")\n    print(f"  panel d geometry: row pitch {panel_b_summary[\'row_label_pitch_pt\']} pt "\n          f"for {panel_b_summary[\'tick_label_font_pt\']} pt labels, column pitch {panel_b_summary[\'column_pitch_pt\']} pt")\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUT)\n    build(parser.parse_args().output_dir)\n\n\nif __name__ == "__main__":\n    main()\n'
