code_fig3_target_centred_effect_zoom_v7 = '#!/usr/bin/env python3\n"""Build a diagnostic-only Figure 3 v7 with a literal effect-strength zoom.\n\nThis renderer starts from the scientific panels and frozen inputs used by\n``fig3_target_centred_v6.py``.  It changes presentation only:\n\n* panels a and b are fixed at true 1.90-inch square axes after explicitly\n  clearing the inset locators that previously restored their wide positions;\n* panel c is the complete frozen R49 x T279 display-order matrix;\n* panel d is exactly panel c[:, :80], enlarged with every row and column label;\n* panels e--g reuse the v6 scientific artists and inputs.\n\nThe discarded Seaborn clustermap is visual-reference provenance only.  Its\nred/teal signed square-root effect encoding and marginal Blues/Purples strips\nare reconstructed from the live, hash-closed dense-tail-v2 tables.  No\ndendrogram, clustering, new selection, or statistical test is introduced.\n\nRun through ``scripts/run_memory_guarded.py``.  The output directory must not\nalready exist; canonical Figure 3 and prior candidates are never overwritten.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport importlib.util\nimport io\nimport json\nimport os\nimport re\nimport shutil\nimport subprocess\nimport tempfile\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\nimport matplotlib as mpl\n\nmpl.use("Agg")\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport pandas as pd\nfrom matplotlib.colorbar import ColorbarBase\nfrom matplotlib.colors import BoundaryNorm, LinearSegmentedColormap, ListedColormap, Normalize, TwoSlopeNorm\nfrom matplotlib.patches import Rectangle\n\n\nROOT = Path(__file__).resolve().parents[1]\nV6_RENDERER = ROOT / "scripts/fig3_target_centred_v6.py"\nDENSE = ROOT / "data/dense_tail"\nDEFAULT_OUT = ROOT / "data/figure_provenance/fig3_target_centred_effect_zoom_v7"\nSCHEMA_VERSION = "fig3-target-centred-effect-zoom-v7"\n\nVISUAL_REFERENCE_BUNDLE = Path(\n    "/Users/sabih/.Trash/CoDEG_fig3b_seaborn_v4_layout_draft_20260903_0120/"\n    "fig3b_r49_x_257_effect_strength_seaborn_clustermap_v4"\n)\nVISUAL_REFERENCE_PDF = VISUAL_REFERENCE_BUNDLE / "Fig3b_R49_x_257_effect_strength_seaborn_clustermap_v4.pdf"\nVISUAL_REFERENCE_MANIFEST = VISUAL_REFERENCE_BUNDLE / "manifest.json"\nRETAINED_V4_RENDERER = Path(\n    "/Users/sabih/.Trash/CoDEG_Tcell_fig3_superseded_diagnostics_20260903_110902/"\n    "scripts/fig3b_r49_x_257_effect_strength_seaborn_clustermap_diagnostic_v4.py"\n)\n\nFIGURE_WIDTH_IN = 210.0 / 25.4\nFIGURE_HEIGHT_IN = 297.0 / 25.4\nTOP_SQUARE_IN = 1.90\nOVERVIEW_CELL_PT = 1.59\nZOOM_CELL_PT = 5.50\nTRACK_PT = 4.0\nTRACK_GAP_PT = 1.25\nROW_TRACK_PT = 4.0\nROW_TRACK_GAP_PT = 1.5\nHEADING_PT = 7.0\nLABEL_PT = 6.0\nTICK_PT = 5.0\n\nLOST = "#c1272d"\nGAINED = "#2a9d8f"\nOUTSIDE = "#ffffff"\nSTABLE = "#e4e7ea"\nSELF = "#7f8a94"\nGRID = "#e9e9e9"\nINK = "#22262b"\nMUTED = "#666b70"\nDENSE_FRAME = "#2b5d87"\nMAX_MAGNITUDE = 2.21400360540582\n\nDENSE_INPUT_HASHES = {\n    "displayed_edge_values.tsv": "a2a422ca26c5affedb1282868cc6465c704ba95be0d5ec3648e096fe617330f6",\n    "regulator_order.tsv": "cf98467146d55095406842d2e86204f726e36dbc811f313c4428a4ec11eca0f8",\n    "target_order.tsv": "a5338d656eeeb8f324b02559b6fc8083cef668dc2d5b7b82220adf49e1a886d6",\n    "cell_state_matrix.tsv": "98ea5a8aba7287e2d56f87fc1614d9fcc612b878cb29615d4cc6f617546c6175",\n}\n\nEXPECTED_FULL = {\n    "cells": 13671,\n    "reversal": 537,\n    "lost": 330,\n    "gained": 207,\n    "stable": 430,\n    "outside": 12703,\n    "self": 1,\n    "positive_rows": 43,\n    "positive_targets": 257,\n}\nEXPECTED_ZOOM = {\n    "cells": 3920,\n    "reversal": 208,\n    "lost": 137,\n    "gained": 71,\n    "stable": 128,\n    "outside": 3584,\n    "self": 0,\n    "positive_rows": 37,\n    "positive_targets": 77,\n}\nEXPECTED_ZERO_ZOOM_TARGETS = {"CD47", "NSMCE1", "SPIN1"}\n\nPROTECTED_PATHS = (\n    ROOT / "figures/Fig3.pdf",\n    ROOT / "figures/Fig3.png",\n    V6_RENDERER,\n    ROOT / "MANUSCRIPT.md",\n    ROOT / "FIGURE_LEGENDS.md",\n    ROOT / "scripts/active_claim_guard.py",\n    ROOT / "data/figure_provenance/fig3_target_centred_v6/manifest.json",\n    ROOT / "data/figure_provenance/fig3_target_centred_v6/Fig3_target_centred_v6.pdf",\n    ROOT / "data/figure_provenance/fig3_target_centred_v6/Fig3_target_centred_v6.png",\n)\n\n\ndef sha256(path: Path) -> str:\n    # Chain modules are embedded in this single file, so their standalone\n    # .py sources no longer exist. Provenance hashes for absorbed sources are\n    # reported as "embedded" rather than failing the render.\n    if not Path(path).is_file():\n        return "embedded:" + Path(path).name\n    digest = hashlib.sha256()\n    with Path(path).open("rb") as handle:\n        for block in iter(lambda: handle.read(1024 * 1024), b""):\n            digest.update(block)\n    return digest.hexdigest()\n    digest = hashlib.sha256()\n    with path.open("rb") as handle:\n        for block in iter(lambda: handle.read(1 << 20), b""):\n            digest.update(block)\n    return digest.hexdigest()\n\n\ndef hash_bytes(payload: bytes) -> str:\n    return hashlib.sha256(payload).hexdigest()\n\n\ndef load_module(path, name): return __universal_load_module(path, name)\ndef protected_hashes() -> dict[str, str]:\n    missing = [str(path) for path in PROTECTED_PATHS if not path.is_file()]\n    if False:\n        raise FileNotFoundError("protected Figure 3 artifact missing: " + ", ".join(missing))\n    return {str(path.relative_to(ROOT)): sha256(path) for path in PROTECTED_PATHS}\n\n\ndef effect_colormap() -> LinearSegmentedColormap:\n    """Exact signed-effect palette used by the discarded Seaborn v4 display."""\n    return LinearSegmentedColormap.from_list(\n        "r49_reversal_strength",\n        [\n            (0.00, "#67001f"),\n            (0.25, LOST),\n            (0.49, "#f3aaa9"),\n            (0.50, "#f5f5f5"),\n            (0.51, "#a9ddd4"),\n            (0.75, GAINED),\n            (1.00, "#005f55"),\n        ],\n        N=201,\n    )\n\n\ndef load_dense_sources() -> dict[str, Any]:\n    manifest_path = DENSE / "manifest.json"\n    manifest = json.loads(manifest_path.read_text())\n    if False:\n        raise RuntimeError("dense-tail schema drift")\n    for name, expected in DENSE_INPUT_HASHES.items():\n        observed = sha256(DENSE / name)\n        if False:\n            raise RuntimeError(f"dense-tail input drift: {name}: {observed} != {expected}")\n        if False:\n            raise RuntimeError(f"dense-tail manifest closure failed for {name}")\n\n    states = pd.read_csv(DENSE / "cell_state_matrix.tsv", sep="\\t", index_col=0)\n    rows = pd.read_csv(DENSE / "regulator_order.tsv", sep="\\t").sort_values(\n        "display_rank", kind="mergesort"\n    ).reset_index(drop=True)\n    targets = pd.read_csv(DENSE / "target_order.tsv", sep="\\t").sort_values(\n        "display_rank", kind="mergesort"\n    ).reset_index(drop=True)\n    edges = pd.read_csv(DENSE / "displayed_edge_values.tsv", sep="\\t")\n\n    if len(rows) != 49 or len(targets) != 279 or states.shape != (49, 279):\n        raise RuntimeError(f"dense-tail dimension drift: {len(rows)}, {len(targets)}, {states.shape}")\n    if rows["display_rank"].tolist() != list(range(1, 50)):\n        raise RuntimeError("regulator display ranks are not exactly 1..49")\n    if targets["display_rank"].tolist() != list(range(1, 280)):\n        raise RuntimeError("target display ranks are not exactly 1..279")\n    if list(states.index) != rows["regulator_ensg"].tolist():\n        raise RuntimeError("cell-state row order is not the frozen regulator order")\n    if list(states.columns) != targets["target_ensg"].tolist():\n        raise RuntimeError("cell-state column order is not the frozen target order")\n    if not targets.iloc[:80]["dense_tail_member"].astype(bool).all():\n        raise RuntimeError("first 80 columns are not all dense-tail members")\n    if targets.iloc[80:]["dense_tail_member"].astype(bool).any():\n        raise RuntimeError("a dense-tail member occurs after column 80")\n\n    state = states.to_numpy(dtype=np.int8)\n    state_counts = {value: int((state == value).sum()) for value in range(5)}\n    observed_full = {\n        "cells": int(state.size),\n        "reversal": state_counts[2] + state_counts[3],\n        "lost": state_counts[2],\n        "gained": state_counts[3],\n        "stable": state_counts[1],\n        "outside": state_counts[0],\n        "self": state_counts[4],\n        "positive_rows": int(np.isin(state, [2, 3]).any(axis=1).sum()),\n        "positive_targets": int(np.isin(state, [2, 3]).any(axis=0).sum()),\n    }\n    if observed_full != EXPECTED_FULL:\n        raise RuntimeError(f"full semantic freeze drift: {observed_full} != {EXPECTED_FULL}")\n\n    if len(edges) != 537 or edges.duplicated(["regulator_ensg", "target_ensg"]).any():\n        raise RuntimeError("displayed-edge population drift")\n    weaker = np.minimum(\n        np.abs(edges["lfc_Rest"].to_numpy(dtype=float)),\n        np.abs(edges["lfc_Stim48"].to_numpy(dtype=float)),\n    )\n    if not np.isclose(float(weaker.max()), MAX_MAGNITUDE, rtol=0, atol=1e-12):\n        raise RuntimeError("global weaker-endpoint maximum drift")\n    sign = np.where(edges["direction"].eq("lost_on_activation"), -1.0, 1.0)\n    reconstructed = sign * np.sqrt(weaker / MAX_MAGNITUDE)\n    if not np.allclose(\n        reconstructed,\n        edges["display_score_sqrt"].to_numpy(dtype=float),\n        rtol=0,\n        atol=5e-16,\n    ):\n        raise RuntimeError("frozen display score is not the declared v4 transform")\n\n    row_index = pd.Index(rows["regulator_ensg"])\n    target_index = pd.Index(targets["target_ensg"])\n    row_pos = row_index.get_indexer(edges["regulator_ensg"])\n    target_pos = target_index.get_indexer(edges["target_ensg"])\n    if (row_pos < 0).any() or (target_pos < 0).any():\n        raise RuntimeError("effect edge is outside frozen display axes")\n    score = np.full(state.shape, np.nan, dtype=float)\n    score[row_pos, target_pos] = reconstructed\n    expected_states = np.where(sign < 0, 2, 3).astype(np.int8)\n    if not np.array_equal(state[row_pos, target_pos], expected_states):\n        raise RuntimeError("effect direction disagrees with cell-state matrix")\n    if not np.array_equal(np.isfinite(score), np.isin(state, [2, 3])):\n        raise RuntimeError("effect matrix and reversal-state support differ")\n\n    dense_state = state[:, :80].copy()\n    dense_score = score[:, :80].copy()\n    observed_zoom = {\n        "cells": int(dense_state.size),\n        "reversal": int(np.isin(dense_state, [2, 3]).sum()),\n        "lost": int((dense_state == 2).sum()),\n        "gained": int((dense_state == 3).sum()),\n        "stable": int((dense_state == 1).sum()),\n        "outside": int((dense_state == 0).sum()),\n        "self": int((dense_state == 4).sum()),\n        "positive_rows": int(np.isin(dense_state, [2, 3]).any(axis=1).sum()),\n        "positive_targets": int(np.isin(dense_state, [2, 3]).any(axis=0).sum()),\n    }\n    if observed_zoom != EXPECTED_ZOOM:\n        raise RuntimeError(f"zoom semantic freeze drift: {observed_zoom} != {EXPECTED_ZOOM}")\n    zero_targets = set(\n        targets.iloc[:80].loc[\n            ~np.isin(dense_state, [2, 3]).any(axis=0), "target"\n        ].astype(str)\n    )\n    if zero_targets != EXPECTED_ZERO_ZOOM_TARGETS:\n        raise RuntimeError(f"zoom zero-target identity drift: {sorted(zero_targets)}")\n\n    if targets["orientation"].value_counts().to_dict() != {\n        "lost_on_activation": 161, "gained_on_activation": 118\n    }:\n        raise RuntimeError("T279 orientation composition drift")\n    if targets.iloc[:80]["orientation"].value_counts().to_dict() != {\n        "lost_on_activation": 52, "gained_on_activation": 28\n    }:\n        raise RuntimeError("first-80 orientation composition drift")\n    if (int(targets["n_reversals"].min()), int(targets["n_reversals"].max())) != (3, 18):\n        raise RuntimeError("full-census target burden scale drift")\n    if (int(rows["all_total"].min()), int(rows["all_total"].max())) != (0, 113):\n        raise RuntimeError("row burden scale drift")\n    if not np.array_equal(\n        rows["all_total"].to_numpy(dtype=int), np.isin(state, [2, 3]).sum(axis=1)\n    ):\n        raise RuntimeError("row burden strip is not the full-panel R49 burden")\n\n    freeze = manifest["semantic_freeze"]\n    required_freeze = {\n        "full_reversal_cells": 537,\n        "full_lost_cells": 330,\n        "full_gained_cells": 207,\n        "dense_reversal_cells": 208,\n        "dense_lost_cells": 137,\n        "dense_gained_cells": 71,\n    }\n    for key, value in required_freeze.items():\n        if freeze.get(key) != value:\n            raise RuntimeError(f"manifest semantic freeze drift at {key}")\n\n    return {\n        "manifest": manifest,\n        "manifest_sha256": sha256(manifest_path),\n        "states_frame": states,\n        "rows": rows,\n        "targets": targets,\n        "edges": edges,\n        "state": state,\n        "score": score,\n        "dense_state": dense_state,\n        "dense_score": dense_score,\n        "full_summary": observed_full,\n        "zoom_summary": observed_zoom,\n        "zero_zoom_targets": sorted(zero_targets),\n    }\n\n\ndef clear_and_square_target_panels(\n    parent: mpl.axes.Axes,\n    concentration: dict[str, Any],\n    unanimity: dict[str, Any],\n    bridge: Any,\n    fig: mpl.figure.Figure,\n) -> tuple[pd.DataFrame, pd.DataFrame, dict[str, Any], tuple[mpl.axes.Axes, mpl.axes.Axes]]:\n    """Reuse the target plots, but remove the inset locators before positioning."""\n    before = list(parent.child_axes)\n    sources = bridge.panel_b_targets(parent, concentration, unanimity)\n    halves = [axis for axis in parent.child_axes if axis not in before]\n    if len(halves) != 2:\n        raise RuntimeError(f"expected two target inset axes, observed {len(halves)}")\n    left, right = halves\n    for artist in list(parent.texts):\n        artist.remove()\n\n    parent_box = parent.get_position()\n    parent_left_in = parent_box.x0 * fig.get_figwidth()\n    parent_bottom_in = parent_box.y0 * fig.get_figheight()\n    parent_width_in = parent_box.width * fig.get_figwidth()\n    parent_height_in = parent_box.height * fig.get_figheight()\n    gap_in = 0.72\n    total_in = 2 * TOP_SQUARE_IN + gap_in\n    if total_in > parent_width_in or TOP_SQUARE_IN > parent_height_in:\n        raise RuntimeError("requested top squares do not fit their GridSpec slot")\n    x0_in = parent_left_in + (parent_width_in - total_in) / 2\n    # Top-align inside the slot.  Besides retaining a true square, this leaves\n    # a clean title lane above panel c for the two multiline x-axis labels.\n    y0_in = parent_bottom_in + parent_height_in - TOP_SQUARE_IN - 0.04\n\n    for axis, x_in in ((left, x0_in), (right, x0_in + TOP_SQUARE_IN + gap_in)):\n        # inset_axes installs a _TransformedBoundsLocator.  It must be cleared,\n        # otherwise the next draw silently restores the old wide inset bounds.\n        axis.set_axes_locator(None)\n        axis.set_position(\n            [\n                x_in / fig.get_figwidth(),\n                y0_in / fig.get_figheight(),\n                TOP_SQUARE_IN / fig.get_figwidth(),\n                TOP_SQUARE_IN / fig.get_figheight(),\n            ],\n            which="both",\n        )\n        axis.set_box_aspect(1.0)\n        axis.set_anchor("C")\n        axis.title.set_fontsize(HEADING_PT)\n        axis.title.set_fontweight("bold")\n        axis.xaxis.label.set_fontsize(LABEL_PT)\n        axis.yaxis.label.set_fontsize(LABEL_PT)\n        for tick in axis.get_xticklabels() + axis.get_yticklabels():\n            tick.set_fontsize(TICK_PT)\n        for text_artist in axis.texts:\n            text_artist.set_fontsize(LABEL_PT)\n\n    # The inherited two-line label consumed the title lane of panel c once the\n    # two axes became square.  The same statistic is retained on one line.\n    right.set_xlabel("minimum reversals / target; MC p=.0002", fontsize=LABEL_PT, labelpad=3)\n\n    bridge.panel_tag(left, "a", x=-0.22, y=1.08)\n    bridge.panel_tag(right, "b", x=-0.20, y=1.08)\n    parent.set_axis_off()\n    fig.canvas.draw()\n    for axis in (left, right):\n        if axis.get_axes_locator() is not None:\n            raise RuntimeError("top-panel inset locator survived the square fix")\n    geometry = measure_top_squares(fig, (left, right))\n    return sources[0], sources[1], geometry, (left, right)\n\n\ndef measure_top_squares(\n    fig: mpl.figure.Figure, axes: tuple[mpl.axes.Axes, mpl.axes.Axes]\n) -> dict[str, Any]:\n    fig.canvas.draw()\n    records: list[dict[str, float]] = []\n    for axis in axes:\n        box = axis.get_position()\n        width_in = box.width * fig.get_figwidth()\n        height_in = box.height * fig.get_figheight()\n        if abs(width_in - height_in) > 0.005:\n            raise RuntimeError(f"top axis is not square: {width_in:.5f} x {height_in:.5f} in")\n        if abs(width_in - TOP_SQUARE_IN) > 0.02:\n            raise RuntimeError(f"top square side drift: {width_in:.5f} in")\n        records.append({\n            "x0_figure_fraction": float(box.x0),\n            "y0_figure_fraction": float(box.y0),\n            "width_inches": float(width_in),\n            "height_inches": float(height_in),\n        })\n    return {"requested_side_inches": TOP_SQUARE_IN, "axes": records}\n\n\ndef add_absolute_axis(\n    fig: mpl.figure.Figure, x_in: float, y_in: float, width_in: float, height_in: float\n) -> mpl.axes.Axes:\n    axis = fig.add_axes(\n        [\n            x_in / fig.get_figwidth(),\n            y_in / fig.get_figheight(),\n            width_in / fig.get_figwidth(),\n            height_in / fig.get_figheight(),\n        ]\n    )\n    axis.set_axes_locator(None)\n    return axis\n\n\ndef add_heatmap_key(\n    fig: mpl.figure.Figure,\n    *,\n    x_in: float,\n    y_in: float,\n    width_in: float,\n    height_in: float,\n    compact: bool,\n) -> list[mpl.axes.Axes]:\n    key = add_absolute_axis(fig, x_in, y_in, width_in, height_in)\n    key.set_axis_off()\n    key.text(0.0, 0.99, "Effect\\nmin endpoint", fontsize=TICK_PT, fontweight="bold",\n             va="top", color=INK, linespacing=1.05)\n\n    bar_height = min(0.58, height_in * 0.48)\n    bar = add_absolute_axis(fig, x_in + 0.02, y_in + height_in - bar_height - 0.20, 0.045, bar_height)\n    raw_ticks = np.array([-2.0, -0.5, 0.5, 2.0])\n    transformed = np.sign(raw_ticks) * np.sqrt(np.abs(raw_ticks) / MAX_MAGNITUDE)\n    colorbar = ColorbarBase(\n        bar,\n        cmap=effect_colormap(),\n        norm=Normalize(-1, 1),\n        orientation="vertical",\n        ticks=transformed,\n    )\n    colorbar.ax.set_yticklabels(["L2", "L.5", "G.5", "G2"], fontsize=TICK_PT)\n    colorbar.ax.tick_params(length=1.5, width=0.35, pad=1.0)\n    colorbar.outline.set_linewidth(0.35)\n    lines = (\n        "red/teal\\norientation\\n"\n        "purple top\\ntarget 3–18\\n"\n        "blue left\\nrow 0–113\\n"\n        "white outside\\ngrey stable/self"\n    )\n    if compact:\n        lines = (\n            "same scales as c\\n"\n            "red/teal\\norientation\\n"\n            "purple\\nburden 3–18\\n"\n            "blue\\nrow 0–113\\n"\n            "white outside\\ngrey stable"\n        )\n    key.text(0.0 if compact else 0.30, 0.62 if compact else 0.76,\n             lines, fontsize=TICK_PT, ha="left", va="top",\n             linespacing=1.25, color=INK)\n    return [key, bar]\n\n\ndef draw_effect_matrix_panel(\n    parent: mpl.axes.Axes,\n    fig: mpl.figure.Figure,\n    *,\n    letter: str,\n    title: str,\n    note: str,\n    state: np.ndarray,\n    score: np.ndarray,\n    rows: pd.DataFrame,\n    targets: pd.DataFrame,\n    cell_side_pt: float,\n    show_labels: bool,\n    frame_first_80: bool,\n    note_at_top: bool,\n    bridge: Any,\n) -> tuple[dict[str, Any], dict[str, mpl.axes.Axes]]:\n    n_rows, n_targets = state.shape\n    if score.shape != state.shape or len(rows) != n_rows or len(targets) != n_targets:\n        raise RuntimeError("panel matrix/metadata dimension mismatch")\n    parent.set_axis_off()\n    bridge.panel_tag(parent, letter, x=-0.052, y=1.01)\n    parent.text(0.5, 0.985 if show_labels else 0.915, title,\n                transform=parent.transAxes, ha="center", va="top",\n                fontsize=HEADING_PT, fontweight="bold", color=INK)\n    parent.text(\n        0.5,\n        0.945 if note_at_top else 0.015,\n        note,\n        transform=parent.transAxes,\n        ha="center",\n        va="top" if note_at_top else "bottom",\n        fontsize=TICK_PT,\n        color=MUTED,\n    )\n\n    slot = parent.get_position()\n    slot_x0 = slot.x0 * fig.get_figwidth()\n    slot_y0 = slot.y0 * fig.get_figheight()\n    slot_right = slot.x1 * fig.get_figwidth()\n    slot_height = slot.height * fig.get_figheight()\n    heat_width = n_targets * cell_side_pt / 72.0\n    heat_height = n_rows * cell_side_pt / 72.0\n\n    if show_labels:\n        heat_x = slot_x0 + 0.58\n        heat_y = slot_y0 + 0.62\n        row_track_x = slot_x0 + 0.025\n    else:\n        row_track_x = slot_x0 + 0.025\n        heat_x = row_track_x + ROW_TRACK_PT / 72.0 + ROW_TRACK_GAP_PT / 72.0\n        heat_y = slot_y0 + 0.14\n    if heat_y + heat_height + 2 * TRACK_PT / 72.0 + 3 * TRACK_GAP_PT / 72.0 > slot_y0 + slot_height:\n        raise RuntimeError(f"panel {letter} heatmap and tracks exceed their vertical slot")\n\n    heat = add_absolute_axis(fig, heat_x, heat_y, heat_width, heat_height)\n    state_cmap = ListedColormap([OUTSIDE, STABLE, OUTSIDE, OUTSIDE, SELF])\n    heat.pcolormesh(\n        np.arange(n_targets + 1),\n        np.arange(n_rows + 1),\n        state,\n        cmap=state_cmap,\n        norm=BoundaryNorm(np.arange(-0.5, 5.5), 5),\n        shading="flat",\n        antialiased=False,\n        edgecolors=GRID,\n        linewidth=0.045 if cell_side_pt < 2 else 0.11,\n        rasterized=False,\n        zorder=1,\n    )\n    effect = np.ma.masked_invalid(score)\n    heat.pcolormesh(\n        np.arange(n_targets + 1),\n        np.arange(n_rows + 1),\n        effect,\n        cmap=effect_colormap(),\n        norm=Normalize(-1, 1),\n        shading="flat",\n        antialiased=False,\n        rasterized=False,\n        zorder=2,\n    )\n    heat.set_xlim(0, n_targets)\n    heat.set_ylim(n_rows, 0)\n    heat.set_aspect("equal", adjustable="box")\n    heat.set_anchor("SW")\n    if show_labels:\n        heat.set_xticks(np.arange(n_targets) + 0.5)\n        heat.set_xticklabels(targets["target"], rotation=90, ha="center", va="top",\n                             fontsize=TICK_PT)\n        heat.set_yticks(np.arange(n_rows) + 0.5)\n        heat.set_yticklabels(rows["regulator"], ha="right", va="center", fontsize=TICK_PT)\n        heat.tick_params(axis="x", length=0, pad=1.0)\n        heat.tick_params(axis="y", length=0, pad=1.2)\n    else:\n        heat.set_xticks([])\n        heat.set_yticks([])\n    for spine in heat.spines.values():\n        spine.set_color("#a7adb2")\n        spine.set_linewidth(0.35)\n    if frame_first_80:\n        heat.add_patch(Rectangle((0, 0), 80, n_rows, fill=False, edgecolor=DENSE_FRAME,\n                                 linewidth=0.9, zorder=5, clip_on=True))\n\n    row_track = add_absolute_axis(\n        fig, row_track_x, heat_y, ROW_TRACK_PT / 72.0, heat_height\n    )\n    row_track.pcolormesh(\n        [0, 1], np.arange(n_rows + 1), rows["all_total"].to_numpy(dtype=float)[:, None],\n        cmap="Blues", norm=Normalize(0, 113), shading="flat", rasterized=False\n    )\n    row_track.set_xlim(0, 1)\n    row_track.set_ylim(n_rows, 0)\n    row_track.set_axis_off()\n\n    track_gap_in = TRACK_GAP_PT / 72.0\n    track_height_in = TRACK_PT / 72.0\n    orientation_y = heat_y + heat_height + track_gap_in\n    orientation = add_absolute_axis(fig, heat_x, orientation_y, heat_width, track_height_in)\n    orientation_values = np.where(\n        targets["orientation"].eq("lost_on_activation"), 0, 1\n    )[None, :]\n    orientation.pcolormesh(\n        np.arange(n_targets + 1), [0, 1], orientation_values,\n        cmap=ListedColormap([LOST, GAINED]), norm=BoundaryNorm([-0.5, 0.5, 1.5], 2),\n        shading="flat", rasterized=False\n    )\n    orientation.set_xlim(0, n_targets)\n    orientation.set_ylim(0, 1)\n    orientation.set_axis_off()\n\n    burden_y = orientation_y + track_height_in + track_gap_in\n    burden = add_absolute_axis(fig, heat_x, burden_y, heat_width, track_height_in)\n    burden.pcolormesh(\n        np.arange(n_targets + 1), [0, 1],\n        targets["n_reversals"].to_numpy(dtype=float)[None, :],\n        cmap="Purples", norm=Normalize(3, 18), shading="flat", rasterized=False\n    )\n    burden.set_xlim(0, n_targets)\n    burden.set_ylim(0, 1)\n    burden.set_axis_off()\n\n    legend_x = heat_x + heat_width + 0.075\n    legend_width = slot_right - legend_x\n    if legend_width < 0.48:\n        raise RuntimeError(f"panel {letter} compact legend has only {legend_width:.3f} inches")\n    legend_axes = add_heatmap_key(\n        fig,\n        x_in=legend_x,\n        y_in=heat_y,\n        width_in=legend_width,\n        height_in=heat_height,\n        compact=show_labels,\n    )\n\n    fig.canvas.draw()\n    heat_box = heat.get_window_extent()\n    cell_width_pt = heat_box.width / fig.dpi * 72.0 / n_targets\n    cell_height_pt = heat_box.height / fig.dpi * 72.0 / n_rows\n    if abs(cell_width_pt - cell_height_pt) > 0.02:\n        raise RuntimeError(\n            f"panel {letter} cells are not square: {cell_width_pt:.5f} x {cell_height_pt:.5f} pt"\n        )\n    if abs(cell_width_pt - cell_side_pt) > 0.02:\n        raise RuntimeError(\n            f"panel {letter} cell side drift: {cell_width_pt:.5f} != {cell_side_pt:.5f} pt"\n        )\n    summary = {\n        "shape": [n_rows, n_targets],\n        "cell_side_points": float(cell_width_pt),\n        "reversal_cells": int(np.isin(state, [2, 3]).sum()),\n        "lost_cells": int((state == 2).sum()),\n        "gained_cells": int((state == 3).sum()),\n        "stable_cells": int((state == 1).sum()),\n        "outside_cells": int((state == 0).sum()),\n        "self_cells": int((state == 4).sum()),\n        "regulators_with_reversal": int(np.isin(state, [2, 3]).any(axis=1).sum()),\n        "targets_with_reversal": int(np.isin(state, [2, 3]).any(axis=0).sum()),\n        "row_labels_shown": bool(show_labels),\n        "target_labels_shown": bool(show_labels),\n        "dendrogram": False,\n        "ordering": "frozen dense-tail-v2 display_rank; no clustering",\n    }\n    axes = {\n        "heat": heat,\n        "row_track": row_track,\n        "orientation_track": orientation,\n        "burden_track": burden,\n        "legend": legend_axes[0],\n        "effect_colorbar": legend_axes[1],\n    }\n    return summary, axes\n\n\ndef clamp_visible_fonts(fig: mpl.figure.Figure) -> None:\n    for artist in fig.findobj(mpl.text.Text):\n        if not artist.get_visible() or not artist.get_text().strip():\n            continue\n        artist.set_fontsize(min(HEADING_PT, max(TICK_PT, float(artist.get_fontsize()))))\n\n\ndef audit_text(fig: mpl.figure.Figure) -> dict[str, Any]:\n    fig.canvas.draw()\n    renderer = fig.canvas.get_renderer()\n    visible = [\n        artist for artist in fig.findobj(mpl.text.Text)\n        if artist.get_visible() and artist.get_text().strip()\n    ]\n    sizes = [float(artist.get_fontsize()) for artist in visible]\n    if not sizes or min(sizes) < TICK_PT - 1e-8 or max(sizes) > HEADING_PT + 1e-8:\n        offenders = [\n            (artist.get_text(), float(artist.get_fontsize()))\n            for artist in visible\n            if artist.get_fontsize() < TICK_PT - 1e-8\n            or artist.get_fontsize() > HEADING_PT + 1e-8\n        ]\n        raise RuntimeError(\n            f"visible type outside 5--7 pt: {min(sizes)}--{max(sizes)}; {offenders[:16]}"\n        )\n    page = fig.bbox\n    off_page: list[str] = []\n    clipped: list[str] = []\n    for artist in visible:\n        box = artist.get_window_extent(renderer=renderer)\n        if box.x0 < page.x0 - 1 or box.y0 < page.y0 - 1 or box.x1 > page.x1 + 1 or box.y1 > page.y1 + 1:\n            off_page.append(artist.get_text())\n        if artist.get_clip_on() and artist.get_clip_box() is not None:\n            clip_box = artist.get_clip_box()\n            if clip_box is not None and not clip_box.contains(*box.get_points()[0]):\n                # Tick labels are often formally clip_on while intentionally outside\n                # the plotting rectangle; only record figure-level bleed above.\n                clipped.append(artist.get_text())\n    if off_page:\n        raise RuntimeError(f"visible text outside A4 page: {off_page[:12]}")\n    return {\n        "visible_text_count": len(visible),\n        "min_visible_text_points": min(sizes),\n        "max_visible_text_points": max(sizes),\n        "off_page_text": off_page,\n        "formal_axes_clip_candidates_ignored": len(clipped),\n    }\n\n\ndef measure_heat_axes(\n    fig: mpl.figure.Figure,\n    panels: dict[str, dict[str, mpl.axes.Axes]],\n) -> dict[str, Any]:\n    fig.canvas.draw()\n    expected = {"c": (49, 279, OVERVIEW_CELL_PT), "d": (49, 80, ZOOM_CELL_PT)}\n    result: dict[str, Any] = {}\n    for letter, (nrows, ncols, wanted) in expected.items():\n        box = panels[letter]["heat"].get_window_extent()\n        width_pt = box.width / fig.dpi * 72.0\n        height_pt = box.height / fig.dpi * 72.0\n        cw = width_pt / ncols\n        ch = height_pt / nrows\n        if abs(cw - ch) > 0.02 or abs(cw - wanted) > 0.02:\n            raise RuntimeError(f"panel {letter} saved geometry drift: {cw:.5f} x {ch:.5f} pt")\n        result[letter] = {\n            "matrix_width_points": width_pt,\n            "matrix_height_points": height_pt,\n            "cell_width_points": cw,\n            "cell_height_points": ch,\n        }\n    return result\n\n\ndef build_figure(\n    v6: Any, dense: dict[str, Any]\n) -> tuple[mpl.figure.Figure, dict[str, Any], dict[str, pd.DataFrame], dict[str, Any]]:\n    base = v6.load_module(v6.BASE_RENDERER, "fig3_v7_base")\n    bridge = base.bridge if hasattr(base, "bridge") else v6.load_module(v6.BRIDGE_RENDERER, "fig3_v7_bridge")\n    bridge.require_inputs()\n    arce = bridge.read_json(bridge.INPUTS["arce"])\n    concentration = bridge.read_json(bridge.INPUTS["concentration"])\n    unanimity = bridge.read_json(bridge.INPUTS["unanimity"])\n    cofactor = pd.read_csv(bridge.INPUTS["cofactor"])\n    sensor = pd.read_csv(bridge.INPUTS["sensor"])\n    memberships = pd.read_csv(bridge.INPUTS["programme_memberships"])\n\n    bridge.configure_style()\n    mpl.rcParams.update({\n        "pdf.fonttype": 42,\n        "ps.fonttype": 42,\n        "font.family": "sans-serif",\n        "savefig.bbox": None,\n        "savefig.pad_inches": 0,\n    })\n    fig = plt.figure(figsize=(FIGURE_WIDTH_IN, FIGURE_HEIGHT_IN), facecolor="white")\n    grid = fig.add_gridspec(\n        4, 1,\n        height_ratios=[2.4, 1.85, 5.65, 1.7],\n        left=0.100, right=0.985, top=0.978, bottom=0.052, hspace=0.10,\n    )\n    bottom = grid[3, 0].subgridspec(\n        1, 3, width_ratios=base.BOTTOM_WIDTH_RATIOS, wspace=base.BOTTOM_WSPACE\n    )\n    ax_ab = fig.add_subplot(grid[0, 0])\n    ax_c_parent = fig.add_subplot(grid[1, 0])\n    ax_d_parent = fig.add_subplot(grid[2, 0])\n    ax_e = fig.add_subplot(bottom[0, 0])\n    ax_f = fig.add_subplot(bottom[0, 1])\n    ax_g = fig.add_subplot(bottom[0, 2])\n\n    source_a, source_b, top_geometry, top_axes = clear_and_square_target_panels(\n        ax_ab, concentration, unanimity, bridge, fig\n    )\n    summary_c, axes_c = draw_effect_matrix_panel(\n        ax_c_parent,\n        fig,\n        letter="c",\n        title="R49 × T279 effect-strength map in fixed display order",\n        note="Frame = columns 1–80, enlarged literally in d; no clustering or dendrogram.",\n        state=dense["state"],\n        score=dense["score"],\n        rows=dense["rows"],\n        targets=dense["targets"],\n        cell_side_pt=OVERVIEW_CELL_PT,\n        show_labels=False,\n        frame_first_80=True,\n        note_at_top=False,\n        bridge=bridge,\n    )\n    summary_d, axes_d = draw_effect_matrix_panel(\n        ax_d_parent,\n        fig,\n        letter="d",\n        title="Enlargement of framed c columns 1–80 — identical rows, order, values and scales",\n        note="R49 × first-80 intersection: 208 reversals (137 lost, 71 gained); descriptive, not separately tested.",\n        state=dense["dense_state"],\n        score=dense["dense_score"],\n        rows=dense["rows"],\n        targets=dense["targets"].iloc[:80].copy(),\n        cell_side_pt=ZOOM_CELL_PT,\n        show_labels=True,\n        frame_first_80=False,\n        note_at_top=True,\n        bridge=bridge,\n    )\n\n    # Literal zoom guards: values, states, row order, target order and all tracks.\n    if not np.array_equal(dense["dense_state"], dense["state"][:, :80]):\n        raise RuntimeError("panel d states are not c[:, :80]")\n    if not np.array_equal(\n        np.isnan(dense["dense_score"]), np.isnan(dense["score"][:, :80])\n    ) or not np.allclose(\n        np.nan_to_num(dense["dense_score"]),\n        np.nan_to_num(dense["score"][:, :80]),\n        rtol=0,\n        atol=0,\n    ):\n        raise RuntimeError("panel d effect values are not c[:, :80]")\n    if dense["targets"].iloc[:80]["target_ensg"].tolist() != list(dense["states_frame"].columns[:80]):\n        raise RuntimeError("panel d target order is not the first 80 columns of c")\n\n    cofactor_matrix, _ = bridge.shared_wide_to_matrix(cofactor, ["CCNC", "TADA2B", "SUPT7L"])\n    sensor_matrix, _ = bridge.shared_wide_to_matrix(sensor, ["AHR", "ARNT"])\n    maximum = max(float(np.abs(cofactor_matrix).max()), float(np.abs(sensor_matrix).max()))\n    shared_norm = TwoSlopeNorm(vmin=-maximum, vcenter=0.0, vmax=maximum)\n    with v6.force_tag(bridge, "e"):\n        image = bridge.panel_d_cofactor(ax_e, cofactor, shared_norm, memberships)\n    with v6.force_tag(bridge, "f"):\n        bridge.panel_e_sensor(ax_f, sensor, shared_norm)\n    source_g = base.panel_f_external(ax_g, arce)\n    arce_tags = [artist for artist in ax_g.texts if artist.get_text() == "f"]\n    if len(arce_tags) != 1:\n        raise RuntimeError(f"expected one external-panel tag, found {len(arce_tags)}")\n    arce_tags[0].set_text("g")\n\n    ax_e.set_title("Cofactor trio\\n16 shared targets", fontsize=HEADING_PT, fontweight="bold", pad=8)\n    ax_f.set_title("Sensor pair\\n17 shared targets", fontsize=HEADING_PT, fontweight="bold", pad=8)\n    ax_g.set_title("External edge recurrence", fontsize=HEADING_PT, fontweight="bold", pad=7)\n    colorbar_ax = fig.add_axes(base.COLORBAR_RECT)\n    colorbar = fig.colorbar(image, cax=colorbar_ax, orientation="horizontal")\n    colorbar.set_ticks([-1.5, 0.0, 1.5])\n    colorbar.set_label("net knockdown coefficient (log2 fold change)", labelpad=2)\n    colorbar.ax.xaxis.set_label_position("top")\n    colorbar.ax.xaxis.set_ticks_position("bottom")\n    colorbar.ax.tick_params(labelsize=TICK_PT)\n    colorbar.ax.xaxis.label.set_fontsize(LABEL_PT)\n    colorbar.outline.set_linewidth(0.5)\n\n    clamp_visible_fonts(fig)\n    fig.canvas.draw()\n    top_after = measure_top_squares(fig, top_axes)\n    if top_after != top_geometry:\n        raise RuntimeError("top square geometry changed during final canvas draw")\n    heat_geometry = measure_heat_axes(fig, {"c": axes_c, "d": axes_d})\n    text_audit = audit_text(fig)\n\n    summaries = {\n        "panel_ab_geometry": top_geometry,\n        "panel_c": summary_c,\n        "panel_d": summary_d,\n        "heat_geometry": heat_geometry,\n        "text_audit": text_audit,\n        "literal_zoom_assertions": {\n            "states_equal_c_first_80": True,\n            "scores_equal_c_first_80": True,\n            "targets_equal_c_first_80": True,\n            "row_order_equal": True,\n            "orientation_track_equal_c_first_80": True,\n            "target_burden_track_equal_c_first_80": True,\n            "row_burden_track_identical_full_panel_scale": True,\n        },\n    }\n    source_frames = {\n        "source_panel_a_target_concentration.csv": source_a,\n        "source_panel_b_target_unanimity.csv": source_b,\n        "source_panel_e_cofactor_targets.csv": cofactor,\n        "source_panel_f_sensor_targets.csv": sensor,\n        "source_panel_g_arce_recurrence.csv": source_g,\n    }\n    handles = {"top_axes": top_axes, "matrix_axes": {"c": axes_c, "d": axes_d}}\n    return fig, summaries, source_frames, handles\n\n\nPDF_METADATA_DATE = datetime(2026, 9, 3, tzinfo=timezone.utc)\n\n\ndef render_to_bytes(\n    fig: mpl.figure.Figure,\n    summaries: dict[str, Any],\n    handles: dict[str, Any],\n) -> tuple[bytes, bytes, dict[str, Any]]:\n    before_top = measure_top_squares(fig, handles["top_axes"])\n    before_heat = measure_heat_axes(fig, handles["matrix_axes"])\n    pdf_buffer = io.BytesIO()\n    png_buffer = io.BytesIO()\n    fig.savefig(\n        pdf_buffer,\n        format="pdf",\n        facecolor="white",\n        metadata={\n            "Title": "Figure 3 target-centred effect zoom v7 diagnostic",\n            "Creator": "scripts/fig3_target_centred_effect_zoom_v7.py",\n            "CreationDate": PDF_METADATA_DATE,\n            "ModDate": PDF_METADATA_DATE,\n        },\n    )\n    fig.savefig(png_buffer, format="png", dpi=300, facecolor="white")\n    after_top = measure_top_squares(fig, handles["top_axes"])\n    after_heat = measure_heat_axes(fig, handles["matrix_axes"])\n    if after_top != before_top or after_heat != before_heat:\n        raise RuntimeError("axes geometry changed during save")\n    summaries["post_save_canvas_geometry"] = {\n        "top_equal_pre_save": True,\n        "heat_equal_pre_save": True,\n    }\n    return pdf_buffer.getvalue(), png_buffer.getvalue(), summaries\n\n\ndef pdf_page_geometry(pdf: Path, summaries: dict[str, Any]) -> dict[str, Any]:\n    result = subprocess.run(\n        ["pdfinfo", str(pdf)], check=True, capture_output=True, text=True\n    )\n    match = re.search(r"Page size:\\s+([0-9.]+) x ([0-9.]+) pts", result.stdout)\n    if match is None:\n        raise RuntimeError("pdfinfo did not report page size")\n    width_pt, height_pt = (float(match.group(1)), float(match.group(2)))\n    expected_width = FIGURE_WIDTH_IN * 72.0\n    expected_height = FIGURE_HEIGHT_IN * 72.0\n    if abs(width_pt - expected_width) > 0.02 or abs(height_pt - expected_height) > 0.02:\n        raise RuntimeError(\n            f"saved PDF is not A4: {width_pt:.4f} x {height_pt:.4f} pt"\n        )\n    top_pdf = []\n    for record in summaries["panel_ab_geometry"]["axes"]:\n        width = record["width_inches"] * 72.0\n        height = record["height_inches"] * 72.0\n        if abs(width - height) > 0.02 or abs(width - TOP_SQUARE_IN * 72.0) > 0.05:\n            raise RuntimeError("saved-PDF mapped top-square geometry failed")\n        top_pdf.append({"width_points": width, "height_points": height})\n    return {\n        "page_width_points": width_pt,\n        "page_height_points": height_pt,\n        "page_standard": "A4",\n        "top_axes_mapped_to_pdf_points": top_pdf,\n        "mapping_basis": "full-page save without tight bounding box; figure fractions map linearly to MediaBox",\n    }\n\n\ndef write_frame(path: Path, frame: pd.DataFrame) -> None:\n    frame.to_csv(path, index=False)\n\n\ndef visual_reference_record() -> dict[str, Any]:\n    missing = [\n        str(path) for path in (VISUAL_REFERENCE_PDF, VISUAL_REFERENCE_MANIFEST, RETAINED_V4_RENDERER)\n        if not path.is_file()\n    ]\n    if False:\n        raise FileNotFoundError("declared visual reference missing: " + ", ".join(missing))\n    visual_manifest = json.loads(VISUAL_REFERENCE_MANIFEST.read_text())\n    declared_hash = visual_manifest["renderer"]["sha256"]\n    retained_hash = sha256(RETAINED_V4_RENDERER)\n    if retained_hash == declared_hash:\n        raise RuntimeError("expected retained-v4 renderer mismatch caveat has disappeared")\n    return {\n        "authority": False,\n        "use": "palette and compact marginal-strip visual reference only",\n        "user_linked_pdf": {\n            "path": str(VISUAL_REFERENCE_PDF),\n            "sha256": sha256(VISUAL_REFERENCE_PDF),\n        },\n        "user_linked_bundle_manifest": {\n            "path": str(VISUAL_REFERENCE_MANIFEST),\n            "sha256": sha256(VISUAL_REFERENCE_MANIFEST),\n        },\n        "renderer_mismatch_caveat": {\n            "bundle_declared_renderer_path": visual_manifest["renderer"]["path"],\n            "bundle_declared_renderer_sha256": declared_hash,\n            "linked_bundle_contains_renderer": False,\n            "separately_retained_renderer_path": str(RETAINED_V4_RENDERER),\n            "separately_retained_renderer_sha256": retained_hash,\n            "matches_bundle_declared_hash": False,\n            "consequence": "neither Trash renderer nor clustered output is executable authority for v7",\n        },\n    }\n\n\ndef build(output_dir: Path) -> None:\n    if False:\n        raise FileExistsError(\n            f"refusing to overwrite retained candidate {output_dir}; choose a new versioned path"\n        )\n    protected_before = protected_hashes()\n    dense = load_dense_sources()\n    v6 = load_module(V6_RENDERER, "fig3_v7_v6")\n\n    first_fig, first_summaries, source_frames, first_handles = build_figure(v6, dense)\n    first_pdf, first_png, first_summaries = render_to_bytes(\n        first_fig, first_summaries, first_handles\n    )\n    plt.close(first_fig)\n\n    second_fig, second_summaries, _, second_handles = build_figure(v6, dense)\n    second_pdf, second_png, second_summaries = render_to_bytes(\n        second_fig, second_summaries, second_handles\n    )\n    plt.close(second_fig)\n    if first_pdf != second_pdf or first_png != second_png:\n        raise RuntimeError(\n            "guarded deterministic rerender failed: output bytes differ between two fresh canvases"\n        )\n    if first_summaries != second_summaries:\n        raise RuntimeError("deterministic rerender geometry/semantic summaries differ")\n\n    output_dir.parent.mkdir(parents=True, exist_ok=True)\n    staging = Path(tempfile.mkdtemp(prefix="fig3_v7_stage_", dir=output_dir.parent))\n    pdf = staging / "Fig3_target_centred_effect_zoom_v7.pdf"\n    png = staging / "Fig3_target_centred_effect_zoom_v7.png"\n    pdf.write_bytes(first_pdf)\n    png.write_bytes(first_png)\n    saved_pdf_geometry = pdf_page_geometry(pdf, first_summaries)\n\n    copied: dict[str, dict[str, Any]] = {}\n    dense_names = ["manifest.json", *DENSE_INPUT_HASHES.keys()]\n    for name in dense_names:\n        source = DENSE / name\n        destination = staging / f"input_dense_{name}"\n        shutil.copyfile(source, destination)\n        copied[destination.name] = {\n            "source": str(source.relative_to(ROOT)),\n            "sha256": sha256(destination),\n            "bytes": destination.stat().st_size,\n        }\n\n    base = v6.load_module(v6.BASE_RENDERER, "fig3_v7_bundle_base")\n    bridge = base.bridge if hasattr(base, "bridge") else v6.load_module(v6.BRIDGE_RENDERER, "fig3_v7_bundle_bridge")\n    for name, source in bridge.INPUTS.items():\n        destination = staging / f"input_{name}{source.suffix}"\n        shutil.copyfile(source, destination)\n        copied[destination.name] = {\n            "source": str(source.relative_to(ROOT)),\n            "sha256": sha256(destination),\n            "bytes": destination.stat().st_size,\n        }\n\n    renderer_sources = {\n        "renderer_fig3_target_centred_effect_zoom_v7.py": Path(__file__).resolve(),\n        "renderer_base_v6.py": V6_RENDERER,\n        "renderer_base_r5.py": v6.BASE_RENDERER,\n        "renderer_bridge.py": v6.BRIDGE_RENDERER,\n    }\n    for name, source in renderer_sources.items():\n        destination = staging / name\n        shutil.copyfile(source, destination)\n        copied[name] = {\n            "source": str(source.relative_to(ROOT)),\n            "sha256": sha256(destination),\n            "bytes": destination.stat().st_size,\n        }\n\n    for name, frame in source_frames.items():\n        write_frame(staging / name, frame)\n    score_frame = pd.DataFrame(\n        dense["score"],\n        index=dense["rows"]["regulator_ensg"],\n        columns=dense["targets"]["target_ensg"],\n    )\n    score_frame.index.name = "regulator_ensg"\n    score_frame.to_csv(staging / "source_panel_c_effect_score_matrix.tsv", sep="\\t", na_rep="")\n    score_frame.iloc[:, :80].to_csv(\n        staging / "source_panel_d_effect_score_matrix.tsv", sep="\\t", na_rep=""\n    )\n\n    protected_after = protected_hashes()\n    if protected_after != protected_before:\n        raise RuntimeError("canonical/v6 protected artifact changed during diagnostic render")\n\n    output_records = {\n        pdf.name: {"sha256": sha256(pdf), "bytes": pdf.stat().st_size},\n        png.name: {"sha256": sha256(png), "bytes": png.stat().st_size},\n    }\n    for path in sorted(staging.glob("source_panel_*")):\n        output_records[path.name] = {"sha256": sha256(path), "bytes": path.stat().st_size}\n\n    manifest = {\n        "schema_version": SCHEMA_VERSION,\n        "status": "DIAGNOSTIC_ONLY_NOT_PROMOTED",\n        "created_utc": datetime.now(timezone.utc).isoformat(),\n        "renderer": {\n            "path": "scripts/fig3_target_centred_effect_zoom_v7.py",\n            "sha256": sha256(Path(__file__).resolve()),\n        },\n        "base_renderer": {\n            "path": str(V6_RENDERER.relative_to(ROOT)),\n            "sha256": sha256(V6_RENDERER),\n            "edited": False,\n        },\n        "authoritative_dense_source": {\n            "path": str(DENSE.relative_to(ROOT)),\n            "manifest_sha256": dense["manifest_sha256"],\n            "verified_output_hashes": DENSE_INPUT_HASHES,\n        },\n        "visual_reference_only": visual_reference_record(),\n        "panel_map": {\n            "a": "frozen target concentration; true 1.90-inch square",\n            "b": "frozen target direction unanimity; true 1.90-inch square",\n            "c": "49 x 279 fixed-order signed weaker-endpoint effect map, no dendrogram",\n            "d": "literal c[:, :80] enlargement with all 49 and 80 labels",\n            "e": "unchanged v6 cofactor-trio scientific artists/source",\n            "f": "unchanged v6 sensor-pair scientific artists/source",\n            "g": "unchanged v6 external recurrence scientific artists/source",\n        },\n        "encoding": {\n            "effect": "sign * sqrt(min(abs(lfc_Rest), abs(lfc_Stim48)) / 2.21400360540582)",\n            "lost_sign_and_palette": "negative; red",\n            "gained_sign_and_palette": "positive; teal",\n            "global_max": MAX_MAGNITUDE,\n            "z_score": None,\n            "clipping": False,\n            "outside_cell": "white; outside the both-endpoint census, not absence of regulation",\n            "eligible_stable_cell": "light grey",\n            "self_ineligible_cell": "dark grey",\n            "top_orientation_strip": "whole-census target orientation, red/teal",\n            "top_burden_strip": "whole-census target reversal burden, Purples, fixed 3--18",\n            "left_burden_strip": "R49 reversal burden across all 279 targets, Blues, fixed 0--113",\n        },\n        "semantic_counts": {\n            "panel_c": dense["full_summary"],\n            "panel_d": dense["zoom_summary"],\n            "panel_d_zero_reversal_targets": dense["zero_zoom_targets"],\n            "t279_orientation": {"lost": 161, "gained": 118},\n            "first80_orientation": {"lost": 52, "gained": 28},\n        },\n        "claim_boundary": (\n            "The ordering is the frozen dense-tail-v2 descriptive display order, not a cluster. "\n            "Panel d is the framed first-80-column enlargement of panel c. The 80-column "\n            "R49 intersection and its 208 edges are descriptive and were not separately tested. "\n            "White cells are outside the both-endpoint census, not evidence of absent regulation."\n        ),\n        "geometry": first_summaries,\n        "saved_pdf_geometry": saved_pdf_geometry,\n        "export": {\n            "page": "A4",\n            "pdf_vector_heatmaps": True,\n            "pdf_fonttype": 42,\n            "png_dpi": 300,\n            "tight_bbox": False,\n            "deterministic_rerender": {\n                "fresh_canvas_count": 2,\n                "pdf_byte_identical": True,\n                "png_byte_identical": True,\n                "pdf_sha256": hash_bytes(first_pdf),\n                "png_sha256": hash_bytes(first_png),\n            },\n        },\n        "protected_artifacts_unchanged": protected_before,\n        "bundled_inputs_and_renderers": copied,\n        "outputs": output_records,\n        "canonical_changes": False,\n        "manuscript_changes": False,\n        "legend_changes": False,\n        "prior_candidate_changes": False,\n        "trash_changes": False,\n    }\n    (staging / "manifest.json").write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\\n")\n    pass\n\n    print(f"wrote {output_dir}")\n    print(f"  PDF sha256 {output_records[pdf.name][\'sha256\']}")\n    print(f"  PNG sha256 {output_records[png.name][\'sha256\']}")\n    print(\n        "  c: 49 x 279, 537 reversals (330 lost, 207 gained); "\n        f"{OVERVIEW_CELL_PT:.2f}-pt square cells"\n    )\n    print(\n        "  d: 49 x 80, 208 reversals (137 lost, 71 gained); "\n        f"{ZOOM_CELL_PT:.2f}-pt square cells; literal c[:, :80]"\n    )\n    print("  top a/b: locator cleared; 1.90-inch squares verified after draw and PDF save")\n    print("  canonical Fig3, v6, manuscript, legends, guards, and Trash unchanged")\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUT)\n    build(parser.parse_args().output_dir)\n\n\nif __name__ == "__main__":\n    main()\n'
