code_fig3_target_centred_effect_zoom_v8 = '#!/usr/bin/env python3\n"""Build Figure 3 v8 as a graphical-legend-only revision of audited v7.\n\nThe scientific matrices, source tables, effect transform, and panel data are\ndelegated unchanged to the hash-closed v7 renderer.  This wrapper changes only\nthe heatmap key, the requested panel-d label size, and (when collision-safe) a\nmodest panel-d cell-side reduction:\n\n* red/teal swatches draw lost/gained orientation;\n* Purples and Blues mini-gradients draw the fixed target (3--18) and row\n  (0--113) burden scales;\n* bordered white and split light/dark-grey swatches draw outside-census and\n  stable/self states;\n* the signed effect-strength bar retains raw log2FC-unit ticks; and\n* every panel-d target and regulator label is exactly 5.5 pt; and\n* panel b restores v6\'s guarded ``Single-orientation targets`` terminology\n  after asserting that the inherited v7 title is the retired wording; and\n* panels e and f label their shared targets as ``direction-concordant``.\n\nRun only through ``scripts/run_memory_guarded.py``.  The output directory must\nnot already exist; canonical Figure 3 and every earlier diagnostic are\nprotected from overwrite.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport importlib.util\nimport io\nimport json\nimport shutil\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\nimport matplotlib as mpl\n\nmpl.use("Agg")\nimport matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.colorbar import ColorbarBase\nfrom matplotlib.colors import Normalize\nfrom matplotlib.patches import Rectangle\n\n\nROOT = Path(__file__).resolve().parents[1]\nV7_RENDERER = ROOT / "scripts/fig3_target_centred_effect_zoom_v7.py"\nDEFAULT_OUT = ROOT / "data/figure_provenance/fig3_target_centred_effect_zoom_v8_2"\nSCHEMA_VERSION = "fig3-target-centred-effect-zoom-v8.2"\nPANEL_D_LABEL_PT = 5.5\nPANEL_D_CELL_PT = 5.50\nPDF_METADATA_DATE = datetime(2026, 9, 3, tzinfo=timezone.utc)\n\n\ndef sha256(path: Path) -> str:\n    # Chain modules are embedded in this single file, so their standalone\n    # .py sources no longer exist. Provenance hashes for absorbed sources are\n    # reported as "embedded" rather than failing the render.\n    if not Path(path).is_file():\n        return "embedded:" + Path(path).name\n    digest = hashlib.sha256()\n    with Path(path).open("rb") as handle:\n        for block in iter(lambda: handle.read(1024 * 1024), b""):\n            digest.update(block)\n    return digest.hexdigest()\n    digest = hashlib.sha256()\n    with path.open("rb") as handle:\n        for block in iter(lambda: handle.read(1 << 20), b""):\n            digest.update(block)\n    return digest.hexdigest()\n\n\ndef load_module(path, name): return __universal_load_module(path, name)\ndef _text(axis: mpl.axes.Axes, x: float, y: float, value: str, **kwargs: Any) -> None:\n    defaults = {\n        "fontsize": 5.0,\n        "color": "#22262b",\n        "transform": axis.transAxes,\n        "clip_on": True,\n    }\n    defaults.update(kwargs)\n    axis.text(x, y, value, **defaults)\n\n\ndef _swatch(\n    axis: mpl.axes.Axes,\n    x: float,\n    y: float,\n    width: float,\n    height: float,\n    color: str,\n    *,\n    edge: str = "#777777",\n) -> None:\n    axis.add_patch(\n        Rectangle(\n            (x, y), width, height,\n            transform=axis.transAxes,\n            facecolor=color,\n            edgecolor=edge,\n            linewidth=0.35,\n            clip_on=True,\n        )\n    )\n\n\ndef _split_swatch(\n    axis: mpl.axes.Axes,\n    x: float,\n    y: float,\n    width: float,\n    height: float,\n    left: str,\n    right: str,\n) -> None:\n    _swatch(axis, x, y, width / 2.0, height, left)\n    _swatch(axis, x + width / 2.0, y, width / 2.0, height, right)\n    axis.add_patch(\n        Rectangle(\n            (x, y), width, height,\n            transform=axis.transAxes,\n            fill=False,\n            edgecolor="#777777",\n            linewidth=0.35,\n            clip_on=True,\n        )\n    )\n\n\ndef _gradient(\n    axis: mpl.axes.Axes,\n    x: float,\n    y: float,\n    width: float,\n    height: float,\n    cmap_name: str,\n) -> None:\n    cmap = mpl.colormaps[cmap_name]\n    bins = 24\n    for index in range(bins):\n        start = x + width * index / bins\n        _swatch(\n            axis,\n            start,\n            y,\n            width / bins + 0.0004,\n            height,\n            mpl.colors.to_hex(cmap((index + 0.5) / bins)),\n            edge="none",\n        )\n    axis.add_patch(\n        Rectangle(\n            (x, y), width, height,\n            transform=axis.transAxes,\n            fill=False,\n            edgecolor="#777777",\n            linewidth=0.35,\n            clip_on=True,\n        )\n    )\n\n\ndef install_graphical_key(v7: Any) -> None:\n    """Replace the prose key while preserving all heatmap axes and scales."""\n\n    def add_heatmap_key(\n        fig: mpl.figure.Figure,\n        *,\n        x_in: float,\n        y_in: float,\n        width_in: float,\n        height_in: float,\n        compact: bool,\n    ) -> list[mpl.axes.Axes]:\n        key = v7.add_absolute_axis(fig, x_in, y_in, width_in, height_in)\n        key.set_xlim(0, 1)\n        key.set_ylim(0, 1)\n        key.set_axis_off()\n\n        if compact:\n            # Panel d has a narrow but tall key lane.  Use its height and draw\n            # one uncluttered shared c/d graphical scale per block.\n            _text(key, 0.02, 0.995, "c/d key", va="top", fontweight="bold")\n            _text(key, 0.02, 0.955, "Effect", va="top", fontweight="bold")\n            _text(key, 0.02, 0.918, "min |log2FC|", va="top")\n            bar_height = min(0.58, height_in * 0.18)\n            bar_y = y_in + height_in - bar_height - 0.44\n            bar = v7.add_absolute_axis(fig, x_in + 0.05, bar_y, 0.045, bar_height)\n\n            _text(key, 0.02, 0.665, "Orientation", va="top", fontweight="bold")\n            _swatch(key, 0.04, 0.610, 0.16, 0.027, v7.LOST, edge="none")\n            _text(key, 0.25, 0.623, "lost", va="center")\n            _swatch(key, 0.04, 0.562, 0.16, 0.027, v7.GAINED, edge="none")\n            _text(key, 0.25, 0.575, "gained", va="center")\n\n            _text(key, 0.02, 0.505, "Target burden", va="top", fontweight="bold")\n            _gradient(key, 0.05, 0.452, 0.84, 0.024, "Purples")\n            _text(key, 0.05, 0.435, "3", va="top", ha="left")\n            _text(key, 0.89, 0.435, "18", va="top", ha="right")\n\n            _text(key, 0.02, 0.360, "Row burden", va="top", fontweight="bold")\n            _gradient(key, 0.05, 0.307, 0.84, 0.024, "Blues")\n            _text(key, 0.05, 0.290, "0", va="top", ha="left")\n            _text(key, 0.89, 0.290, "113", va="top", ha="right")\n\n            _swatch(key, 0.04, 0.190, 0.18, 0.028, v7.OUTSIDE)\n            _text(key, 0.28, 0.204, "outside", va="center")\n            _split_swatch(key, 0.04, 0.132, 0.18, 0.028, v7.STABLE, v7.SELF)\n            _text(key, 0.28, 0.146, "stable/self", va="center")\n        else:\n            # The overview lane is only 1.08 inches tall.  A second complete\n            # key there is cramped, so v8.2 uses one shared c/d key beside d.\n            # Retain a non-rendering axis handle for geometry/provenance code.\n            bar = v7.add_absolute_axis(fig, x_in, y_in, 0.001, 0.001)\n            bar.set_axis_off()\n            return [key, bar]\n\n        raw_ticks = np.array([-2.0, -0.5, 0.5, 2.0])\n        transformed = np.sign(raw_ticks) * np.sqrt(np.abs(raw_ticks) / v7.MAX_MAGNITUDE)\n        colorbar = ColorbarBase(\n            bar,\n            cmap=v7.effect_colormap(),\n            norm=Normalize(-1, 1),\n            orientation="vertical",\n            ticks=transformed,\n        )\n        colorbar.ax.set_yticklabels(["−2", "−0.5", "+0.5", "+2"], fontsize=5.0)\n        colorbar.ax.tick_params(length=1.5, width=0.35, pad=1.0)\n        colorbar.outline.set_linewidth(0.35)\n        return [key, bar]\n\n    v7.add_heatmap_key = add_heatmap_key\n\n\ndef install_panel_d_label_guard(v7: Any) -> None:\n    """Set and audit exact 5.5-pt labels without altering matrix geometry."""\n    original_draw = v7.draw_effect_matrix_panel\n\n    def draw_effect_matrix_panel(*args: Any, **kwargs: Any) -> Any:\n        summary, axes = original_draw(*args, **kwargs)\n        if kwargs.get("show_labels", False):\n            heat = axes["heat"]\n            for label in heat.get_xticklabels() + heat.get_yticklabels():\n                label.set_fontsize(PANEL_D_LABEL_PT)\n            summary["regulator_label_points"] = PANEL_D_LABEL_PT\n            summary["target_label_points"] = PANEL_D_LABEL_PT\n        return summary, axes\n\n    v7.draw_effect_matrix_panel = draw_effect_matrix_panel\n\n\ndef _overlap_audit(labels: list[mpl.text.Text], renderer: Any, axis: str) -> dict[str, Any]:\n    boxes = [label.get_window_extent(renderer=renderer) for label in labels if label.get_visible()]\n    if axis == "x":\n        boxes.sort(key=lambda box: box.x0)\n    else:\n        boxes.sort(key=lambda box: box.y0)\n    overlaps: list[float] = []\n    for left, right in zip(boxes, boxes[1:]):\n        if left.overlaps(right):\n            x_overlap = min(left.x1, right.x1) - max(left.x0, right.x0)\n            y_overlap = min(left.y1, right.y1) - max(left.y0, right.y0)\n            if x_overlap > 0.20 and y_overlap > 0.20:\n                overlaps.append(float(x_overlap * y_overlap))\n    return {\n        "labels": len(boxes),\n        "overlap_pairs_above_0.2px_each_axis": len(overlaps),\n        "maximum_overlap_area_pixels2": max(overlaps, default=0.0),\n    }\n\n\ndef install_build_audit(v7: Any) -> None:\n    original_build_figure = v7.build_figure\n\n    def build_figure(v6: Any, dense: dict[str, Any]) -> Any:\n        fig, summaries, sources, handles = original_build_figure(v6, dense)\n        panel_b = handles["top_axes"][1]\n        if panel_b.get_title() != "Direction unanimity":\n            raise RuntimeError(\n                "panel b inherited title changed before guarded terminology restoration: "\n                f"{panel_b.get_title()!r}"\n            )\n        panel_b.set_title(\n            "Single-orientation targets",\n            fontsize=v7.HEADING_PT,\n            fontweight="bold",\n            pad=4,\n        )\n        bottom_title_contract = {\n            "Cofactor trio\\n16 shared targets": (\n                "e", "Cofactor trio\\n16 direction-concordant targets"\n            ),\n            "Sensor pair\\n17 shared targets": (\n                "f", "Sensor pair\\n17 direction-concordant targets"\n            ),\n        }\n        bottom_axes: dict[str, mpl.axes.Axes] = {}\n        for inherited, (letter, rendered) in bottom_title_contract.items():\n            matches = [axis for axis in fig.axes if axis.get_title() == inherited]\n            if len(matches) != 1:\n                raise RuntimeError(\n                    f"panel {letter} inherited title assertion failed for {inherited!r}: "\n                    f"found {len(matches)} axes"\n                )\n            matches[0].set_title(\n                rendered,\n                fontsize=v7.HEADING_PT,\n                fontweight="bold",\n                pad=8,\n            )\n            bottom_axes[letter] = matches[0]\n        fig.canvas.draw()\n        heat = handles["matrix_axes"]["d"]["heat"]\n        xlabels = list(heat.get_xticklabels())\n        ylabels = list(heat.get_yticklabels())\n        all_sizes = [float(label.get_fontsize()) for label in xlabels + ylabels]\n        if not all_sizes or any(abs(size - PANEL_D_LABEL_PT) > 1e-10 for size in all_sizes):\n            raise RuntimeError(f"panel d labels are not exactly {PANEL_D_LABEL_PT} pt: {sorted(set(all_sizes))}")\n        renderer = fig.canvas.get_renderer()\n        title_boxes = {\n            letter: axis.title.get_window_extent(renderer=renderer)\n            for letter, axis in bottom_axes.items()\n        }\n        if title_boxes["e"].overlaps(title_boxes["f"]):\n            raise RuntimeError("direction-concordant panel e/f titles overlap")\n        page_box = fig.bbox\n        for letter, box in title_boxes.items():\n            if (\n                box.x0 < page_box.x0 - 1\n                or box.y0 < page_box.y0 - 1\n                or box.x1 > page_box.x1 + 1\n                or box.y1 > page_box.y1 + 1\n            ):\n                raise RuntimeError(f"panel {letter} direction-concordant title leaves A4 page")\n        x_audit = _overlap_audit(xlabels, renderer, "x")\n        y_audit = _overlap_audit(ylabels, renderer, "y")\n        if x_audit["overlap_pairs_above_0.2px_each_axis"] or y_audit["overlap_pairs_above_0.2px_each_axis"]:\n            raise RuntimeError(f"panel d label collision: target={x_audit}; regulator={y_audit}")\n        summaries["panel_d_label_audit"] = {\n            "requested_points": PANEL_D_LABEL_PT,\n            "cell_pitch_points": PANEL_D_CELL_PT,\n            "observed_min_points": min(all_sizes),\n            "observed_max_points": max(all_sizes),\n            "target_labels": x_audit,\n            "regulator_labels": y_audit,\n            "saved_pdf_mapping": "full-page A4 export; axes and font points preserved without tight bounding box",\n        }\n        summaries["graphical_heatmap_key"] = {\n            "prose_legend_removed": True,\n            "shared_for_panels": ["c", "d"],\n            "location": "beside panel d; no duplicate overview key",\n            "orientation": {"lost": v7.LOST, "gained": v7.GAINED},\n            "target_burden": {"cmap": "Purples", "minimum": 3, "maximum": 18},\n            "row_burden": {"cmap": "Blues", "minimum": 0, "maximum": 113},\n            "outside": {"fill": v7.OUTSIDE, "bordered": True},\n            "stable_self": {"stable": v7.STABLE, "self": v7.SELF, "split_swatch": True},\n            "effect_ticks_raw_signed_log2fc": [-2.0, -0.5, 0.5, 2.0],\n        }\n        summaries["panel_b_title_guard"] = {\n            "asserted_inherited_title": "Direction unanimity",\n            "rendered_title": "Single-orientation targets",\n            "terminology_only": True,\n        }\n        rendered_strings = [\n            artist.get_text()\n            for artist in fig.findobj(mpl.text.Text)\n            if artist.get_visible() and artist.get_text().strip()\n        ]\n        forbidden = [\n            text\n            for text in rendered_strings\n            if "direction unanimity" in text.lower() or "unanimous" in text.lower()\n        ]\n        if forbidden:\n            raise RuntimeError(f"retired panel terminology remains rendered: {forbidden}")\n        summaries["panel_title_terminology_guard"] = {\n            "rendered": {\n                "b": "Single-orientation targets",\n                "e": "Cofactor trio\\n16 direction-concordant targets",\n                "f": "Sensor pair\\n17 direction-concordant targets",\n            },\n            "forbidden_rendered_terms": ["direction unanimity", "unanimous"],\n            "forbidden_matches": [],\n            "e_f_title_overlap": False,\n            "title_points": v7.HEADING_PT,\n        }\n        summaries["text_audit"] = v7.audit_text(fig)\n        return fig, summaries, sources, handles\n\n    v7.build_figure = build_figure\n\n\ndef install_v8_pdf_metadata(v7: Any) -> None:\n    def render_to_bytes(\n        fig: mpl.figure.Figure,\n        summaries: dict[str, Any],\n        handles: dict[str, Any],\n    ) -> tuple[bytes, bytes, dict[str, Any]]:\n        before_top = v7.measure_top_squares(fig, handles["top_axes"])\n        before_heat = v7.measure_heat_axes(fig, handles["matrix_axes"])\n        pdf_buffer = io.BytesIO()\n        png_buffer = io.BytesIO()\n        fig.savefig(\n            pdf_buffer,\n            format="pdf",\n            facecolor="white",\n            metadata={\n                "Title": "Figure 3 target-centred effect zoom v8.2 graphical-key diagnostic",\n                "Creator": "scripts/fig3_target_centred_effect_zoom_v8.py",\n                "CreationDate": PDF_METADATA_DATE,\n                "ModDate": PDF_METADATA_DATE,\n            },\n        )\n        fig.savefig(png_buffer, format="png", dpi=300, facecolor="white")\n        after_top = v7.measure_top_squares(fig, handles["top_axes"])\n        after_heat = v7.measure_heat_axes(fig, handles["matrix_axes"])\n        if after_top != before_top or after_heat != before_heat:\n            raise RuntimeError("axes geometry changed during save")\n        summaries["post_save_canvas_geometry"] = {\n            "top_equal_pre_save": True,\n            "heat_equal_pre_save": True,\n        }\n        return pdf_buffer.getvalue(), png_buffer.getvalue(), summaries\n\n    v7.render_to_bytes = render_to_bytes\n\n\ndef finalize_bundle(output_dir: Path, v7: Any) -> None:\n    old_pdf = output_dir / "Fig3_target_centred_effect_zoom_v7.pdf"\n    old_png = output_dir / "Fig3_target_centred_effect_zoom_v7.png"\n    new_pdf = output_dir / "Fig3_target_centred_effect_zoom_v8_2.pdf"\n    new_png = output_dir / "Fig3_target_centred_effect_zoom_v8_2.png"\n    old_pdf.rename(new_pdf)\n    old_png.rename(new_png)\n\n    bundled_wrapper = output_dir / "renderer_fig3_target_centred_effect_zoom_v8.py"\n    shutil.copyfile(Path(__file__).resolve(), bundled_wrapper)\n\n    manifest_path = output_dir / "manifest.json"\n    manifest = json.loads(manifest_path.read_text())\n    manifest["schema_version"] = SCHEMA_VERSION\n    manifest["renderer"] = {\n        "path": "scripts/fig3_target_centred_effect_zoom_v8.py",\n        "sha256": sha256(Path(__file__).resolve()),\n    }\n    manifest["implementation_base_renderer_v7"] = {\n        "path": str(V7_RENDERER.relative_to(ROOT)),\n        "sha256": sha256(V7_RENDERER),\n        "scientific_and_geometry_source": True,\n        "edited": False,\n    }\n    manifest["panel_map"]["d"] = (\n        "literal c[:, :80] enlargement with all 49 regulator and 80 target labels at 5.5 pt"\n    )\n    manifest["panel_map"]["b"] = (\n        "frozen single-orientation target statistic; true 1.90-inch square"\n    )\n    manifest["panel_map"]["e"] = (\n        "unchanged v6 cofactor-trio scientific artists/source; 16 direction-concordant targets"\n    )\n    manifest["panel_map"]["f"] = (\n        "unchanged v6 sensor-pair scientific artists/source; 17 direction-concordant targets"\n    )\n    manifest["encoding"]["graphical_legend"] = {\n        "shared_for_panels": ["c", "d"],\n        "location": "beside panel d; no duplicate overview key",\n        "orientation": "drawn red/teal lost/gained swatches",\n        "target_burden": "drawn Purples gradient with 3 and 18 endpoints",\n        "row_burden": "drawn Blues gradient with 0 and 113 endpoints",\n        "outside": "drawn bordered white swatch",\n        "stable_self": "drawn split light-grey/dark-grey swatch",\n        "effect": "compact signed effect-strength colorbar with raw log2FC-unit ticks",\n    }\n    manifest["scope_relative_to_v7_5"] = {\n        "graphical_heatmap_key_only": True,\n        "panel_d_tick_label_size_only": "5.0 to exactly 5.5 pt",\n        "panel_b_terminology_restored": "Direction unanimity to Single-orientation targets",\n        "panel_e_f_terminology": "shared targets labelled direction-concordant",\n        "matrices_changed": False,\n        "panel_c_matrix_geometry_changed": False,\n        "panel_d_cell_side_points": PANEL_D_CELL_PT,\n        "panel_d_matrix_geometry_changed": PANEL_D_CELL_PT != 5.50,\n        "panel_a_to_g_scientific_artists_changed": False,\n    }\n    manifest["rejected_panel_d_geometry_trial"] = {\n        "trial_cell_side_points": 5.25,\n        "label_points": 5.50,\n        "target_adjacent_overlap_pairs": 79,\n        "regulator_adjacent_overlap_pairs": 48,\n        "decision": "rejected; retained 5.50-point square cells",\n        "guard_log": "data/figure_provenance/fig3_target_centred_effect_zoom_v8_1.guard.log",\n    }\n    manifest["rendered_terminology_contract"] = {\n        "panel_b": "Single-orientation targets",\n        "panel_e": "Cofactor trio\\n16 direction-concordant targets",\n        "panel_f": "Sensor pair\\n17 direction-concordant targets",\n        "forbidden_rendered_terms": ["direction unanimity", "unanimous"],\n        "forbidden_matches": [],\n    }\n    outputs = manifest["outputs"]\n    outputs[new_pdf.name] = outputs.pop(old_pdf.name)\n    outputs[new_png.name] = outputs.pop(old_png.name)\n    outputs[new_pdf.name] = {"sha256": sha256(new_pdf), "bytes": new_pdf.stat().st_size}\n    outputs[new_png.name] = {"sha256": sha256(new_png), "bytes": new_png.stat().st_size}\n    manifest["bundled_inputs_and_renderers"][bundled_wrapper.name] = {\n        "source": "scripts/fig3_target_centred_effect_zoom_v8.py",\n        "sha256": sha256(bundled_wrapper),\n        "bytes": bundled_wrapper.stat().st_size,\n    }\n    # This key refers to the prose manuscript legend, which remains untouched.\n    manifest["legend_changes"] = False\n    manifest["figure_graphical_key_changes"] = True\n    manifest_path.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\\n")\n\n    print(f"finalized {output_dir}")\n    print(f"  PDF sha256 {sha256(new_pdf)}")\n    print(f"  PNG sha256 {sha256(new_png)}")\n    print(f"  manifest sha256 {sha256(manifest_path)}")\n    print("  d labels: 49 regulator + 80 target labels, exactly 5.5 pt, collision audit passed")\n    print("  canonical and all prior diagnostic bundles unchanged")\n\n\ndef build(output_dir: Path) -> None:\n    v7 = load_module(V7_RENDERER, "fig3_target_centred_effect_zoom_v8_base")\n    v7.ZOOM_CELL_PT = PANEL_D_CELL_PT\n    install_graphical_key(v7)\n    install_panel_d_label_guard(v7)\n    install_build_audit(v7)\n    install_v8_pdf_metadata(v7)\n    v7.build(output_dir)\n    finalize_bundle(output_dir, v7)\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUT)\n    build(parser.parse_args().output_dir)\n\n\nif __name__ == "__main__":\n    main()\n'
