code_fig3_target_centred_compact_zoom_v12 = '#!/usr/bin/env python3\n"""Build a diagnostic Figure 3 with a compact, display-filtered panel d.\n\nThis is a narrow successor to the sealed v11 renderer.  It imports that\nrenderer and its v10.4.1 parent, then changes presentation only:\n\n* panel d retains the framed first-80 target set but displays only regulators\n  and targets with at least one reversal in that 49 x 80 block;\n* all 208 reversal cells, their values, source order and global colour scales\n  are retained in a 37 x 77 display;\n* panel-d cells and both axes use exactly 5.0 pt, leaving more horizontal room\n  for panel e;\n* panel e retains the same 9 KEGG and 10 GO-BP rows and statistics, but uses a\n  wider bar area and 5.5-pt supporting text.\n\nPanels a-c and f-h are inherited unchanged apart from panel c\'s one-line note\nthat discloses the display-only filtering in d.  The complete 49 x 80 state and\neffect matrices are bundled alongside the filtered display matrices.  This\nscript refuses to overwrite existing output, renders twice from fresh canvases\nand pairs protected before/after hashes.  It never promotes the candidate or\nedits canonical figures, manuscript text, legends, or the active claim guard.\n\nRun only through scripts/run_memory_guarded.py.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport importlib.util\nimport io\nimport json\nimport math\nimport os\nimport shutil\nimport tempfile\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\nimport matplotlib as mpl\n\nmpl.use("Agg")\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport pandas as pd\nfrom PIL import Image\n\n\nROOT = Path(__file__).resolve().parents[1]\nV11_RENDERER = ROOT / "scripts/fig3_target_centred_alltarget_enrichment_v11.py"\nV11_DIR = (\n    ROOT / "data/figure_provenance/fig3_target_centred_alltarget_enrichment_v11"\n)\nV11_PROMOTION = (\n    ROOT\n    / "data/census/"\n    "fig3_target_centred_alltarget_enrichment_v11_promotion_20260904.json"\n)\nDENSE_DIR = (\n    ROOT / "data/dense_tail"\n)\nDEFAULT_OUT = (\n    ROOT / "data/figure_provenance/fig3_target_centred_compact_zoom_v12"\n)\nSCHEMA_VERSION = "fig3-target-centred-compact-zoom-v12"\nSTEM = "Fig3"\nPDF_METADATA_DATE = datetime(2026, 9, 6, tzinfo=timezone.utc)\n\nPANEL_D_CELL_PT = 5.0\nPANEL_D_LABEL_PT = 5.0\nPANEL_E_TEXT_PT = 5.5\nPANEL_E_BAR_WIDTH_IN = 0.70\nPANEL_D_E_GAP_IN = 0.040\n\nEXPECTED_ZERO_REVERSAL_ROWS = (\n    "RBM10",\n    "YEATS2",\n    "MCAT",\n    "KMT2E",\n    "TM2D1",\n    "BRK1",\n    "RB1CC1",\n    "EIF3J",\n    "CARD11",\n    "UBE2N",\n    "RASAL3",\n    "SUGT1",\n)\nEXPECTED_ZERO_REVERSAL_TARGETS = ("SPIN1", "NSMCE1", "CD47")\n\nV11: Any = None\nPATCH_CONTEXT: dict[str, Any] = {}\n\n\ndef sha256(path: Path) -> str:\n    # Chain modules are embedded in this single file, so their standalone\n    # .py sources no longer exist. Provenance hashes for absorbed sources are\n    # reported as "embedded" rather than failing the render.\n    if not Path(path).is_file():\n        return "embedded:" + Path(path).name\n    digest = hashlib.sha256()\n    with Path(path).open("rb") as handle:\n        for block in iter(lambda: handle.read(1024 * 1024), b""):\n            digest.update(block)\n    return digest.hexdigest()\n    digest = hashlib.sha256()\n    with path.open("rb") as handle:\n        for block in iter(lambda: handle.read(1 << 20), b""):\n            digest.update(block)\n    return digest.hexdigest()\n\n\ndef hash_bytes(payload: bytes) -> str:\n    return hashlib.sha256(payload).hexdigest()\n\n\ndef relative(path: Path) -> str:\n    try:\n        return str(path.resolve().relative_to(ROOT))\n    except ValueError:\n        return str(path.resolve())\n\n\ndef load_module(path, name): return __universal_load_module(path, name)\ndef json_value(value: Any) -> Any:\n    return json.loads(json.dumps(value, sort_keys=True))\n\n\ndef exact_axis_with_text(\n    fig: mpl.figure.Figure,\n    predicate: Any,\n    label: str,\n) -> mpl.axes.Axes:\n    matches = [\n        axis\n        for axis in fig.axes\n        if any(predicate(artist.get_text()) for artist in axis.texts)\n    ]\n    if len(matches) != 1:\n        raise RuntimeError(f"expected one {label} axis, observed {len(matches)}")\n    return matches[0]\n\n\ndef build_panel_d_filter(dense: dict[str, Any]) -> dict[str, Any]:\n    state = dense["dense_state"]\n    score = dense["dense_score"]\n    rows = dense["rows"].reset_index(drop=True)\n    targets = dense["targets"].iloc[:80].reset_index(drop=True)\n    if state.shape != (49, 80) or score.shape != state.shape:\n        raise RuntimeError(f"complete panel-d shape drift: {state.shape}, {score.shape}")\n\n    reversal = np.isin(state, [2, 3])\n    row_keep = reversal.any(axis=1)\n    target_keep = reversal.any(axis=0)\n    omitted_rows = tuple(rows.loc[~row_keep, "regulator"].astype(str))\n    omitted_targets = tuple(targets.loc[~target_keep, "target"].astype(str))\n    if omitted_rows != EXPECTED_ZERO_REVERSAL_ROWS:\n        raise RuntimeError(f"zero-reversal row identity drift: {omitted_rows}")\n    if omitted_targets != EXPECTED_ZERO_REVERSAL_TARGETS:\n        raise RuntimeError(f"zero-reversal target identity drift: {omitted_targets}")\n\n    display_state = state[row_keep][:, target_keep]\n    display_score = score[row_keep][:, target_keep]\n    display_rows = rows.loc[row_keep].reset_index(drop=True)\n    display_targets = targets.loc[target_keep].reset_index(drop=True)\n    if display_state.shape != (37, 77) or display_score.shape != display_state.shape:\n        raise RuntimeError(f"filtered panel-d shape drift: {display_state.shape}")\n\n    complete_counts = {\n        "reversal": int(reversal.sum()),\n        "lost": int((state == 2).sum()),\n        "gained": int((state == 3).sum()),\n        "stable": int((state == 1).sum()),\n        "outside": int((state == 0).sum()),\n        "self": int((state == 4).sum()),\n    }\n    display_counts = {\n        "reversal": int(np.isin(display_state, [2, 3]).sum()),\n        "lost": int((display_state == 2).sum()),\n        "gained": int((display_state == 3).sum()),\n        "stable": int((display_state == 1).sum()),\n        "outside": int((display_state == 0).sum()),\n        "self": int((display_state == 4).sum()),\n    }\n    if complete_counts != {\n        "reversal": 208,\n        "lost": 137,\n        "gained": 71,\n        "stable": 128,\n        "outside": 3584,\n        "self": 0,\n    }:\n        raise RuntimeError(f"complete panel-d semantic drift: {complete_counts}")\n    if display_counts != {\n        "reversal": 208,\n        "lost": 137,\n        "gained": 71,\n        "stable": 112,\n        "outside": 2529,\n        "self": 0,\n    }:\n        raise RuntimeError(f"filtered panel-d semantic drift: {display_counts}")\n\n    regulator_records: list[dict[str, Any]] = []\n    for index, row in rows.iterrows():\n        regulator_records.append(\n            {\n                "entity": "regulator",\n                "original_display_rank": int(row["display_rank"]),\n                "symbol": str(row["regulator"]),\n                "stable_id": str(row["regulator_ensg"]),\n                "reversal_cells_in_first80": int(reversal[index, :].sum()),\n                "stable_cells_in_first80": int((state[index, :] == 1).sum()),\n                "outside_cells_in_first80": int((state[index, :] == 0).sum()),\n                "self_cells_in_first80": int((state[index, :] == 4).sum()),\n                "displayed_in_panel_d": bool(row_keep[index]),\n                "display_rule": "at least one reversal state 2 or 3 in framed first-80 block",\n            }\n        )\n    target_records: list[dict[str, Any]] = []\n    for index, row in targets.iterrows():\n        target_records.append(\n            {\n                "entity": "target",\n                "original_display_rank": int(row["display_rank"]),\n                "symbol": str(row["target"]),\n                "stable_id": str(row["target_ensg"]),\n                "reversal_cells_in_first80": int(reversal[:, index].sum()),\n                "stable_cells_in_first80": int((state[:, index] == 1).sum()),\n                "outside_cells_in_first80": int((state[:, index] == 0).sum()),\n                "self_cells_in_first80": int((state[:, index] == 4).sum()),\n                "displayed_in_panel_d": bool(target_keep[index]),\n                "display_rule": "at least one reversal state 2 or 3 in framed first-80 block",\n            }\n        )\n\n    return {\n        "complete_state": state,\n        "complete_score": score,\n        "complete_rows": rows,\n        "complete_targets": targets,\n        "display_state": display_state,\n        "display_score": display_score,\n        "display_rows": display_rows,\n        "display_targets": display_targets,\n        "row_keep": row_keep,\n        "target_keep": target_keep,\n        "omitted_rows": omitted_rows,\n        "omitted_targets": omitted_targets,\n        "complete_counts": complete_counts,\n        "display_counts": display_counts,\n        "filter_frame": pd.DataFrame.from_records(regulator_records + target_records),\n    }\n\n\ndef audit_panel_d_typography(\n    axes_d: dict[str, mpl.axes.Axes],\n    expected: dict[str, Any],\n) -> dict[str, Any]:\n    """Accept the inherited 5.5-pt pre-pass and enforce the final 5.0-pt pass."""\n    heat = axes_d["heat"]\n    x_labels = heat.get_xticklabels()\n    y_labels = heat.get_yticklabels()\n    expected_x = int(expected["x_tick_label_count"])\n    expected_y = int(expected["y_tick_label_count"])\n    wanted = float(expected["delivered_font_size_points"])\n    observed_sizes = sorted(\n        {float(label.get_fontsize()) for label in x_labels + y_labels}\n    )\n    observed_families = sorted(\n        {tuple(label.get_fontfamily()) for label in x_labels + y_labels}\n    )\n    observed = {\n        "x_tick_label_count": len(x_labels),\n        "y_tick_label_count": len(y_labels),\n        "font_sizes_points": observed_sizes,\n        "font_families": observed_families,\n        "x_label_text_sha256": hash_bytes(\n            "\\n".join(label.get_text() for label in x_labels).encode("utf-8")\n        ),\n        "y_label_text_sha256": hash_bytes(\n            "\\n".join(label.get_text() for label in y_labels).encode("utf-8")\n        ),\n    }\n    if len(x_labels) != expected_x or len(y_labels) != expected_y:\n        raise RuntimeError(f"panel-d label-count drift: {observed}")\n    if observed_sizes != [wanted]:\n        raise RuntimeError(f"panel-d label-size drift: {observed}")\n    if expected.get("x_label_text_sha256") not in {None, observed["x_label_text_sha256"]}:\n        raise RuntimeError("panel-d target-label text drift")\n    if expected.get("y_label_text_sha256") not in {None, observed["y_label_text_sha256"]}:\n        raise RuntimeError("panel-d regulator-label text drift")\n    expected_families = expected.get("inherited_and_delivered_font_families")\n    if expected_families is not None and observed_families != [\n        tuple(value) for value in expected_families\n    ]:\n        raise RuntimeError(f"panel-d font-family drift: {observed}")\n    observed["exact_requested_points"] = True\n    observed["text_unchanged"] = True\n    return observed\n\n\ndef measure_heat_axes(\n    fig: mpl.figure.Figure,\n    axes: dict[str, dict[str, mpl.axes.Axes]],\n) -> dict[str, Any]:\n    fig.canvas.draw()\n    result: dict[str, Any] = {}\n    for letter in ("c", "d"):\n        heat = axes[letter]["heat"]\n        if letter == "c":\n            nrows, ncols, wanted = 49, 279, 0.92\n        else:\n            nrows = len(heat.get_yticklabels())\n            ncols = len(heat.get_xticklabels())\n            if (nrows, ncols) == (49, 80):\n                wanted = 5.5\n            elif (nrows, ncols) == (37, 77):\n                wanted = PANEL_D_CELL_PT\n            else:\n                raise RuntimeError(f"unexpected panel-d dimensions: {nrows} x {ncols}")\n        box = heat.get_window_extent()\n        width_pt = box.width / fig.dpi * 72.0\n        height_pt = box.height / fig.dpi * 72.0\n        cell_width = width_pt / ncols\n        cell_height = height_pt / nrows\n        if abs(cell_width - cell_height) > 0.02 or abs(cell_width - wanted) > 0.02:\n            raise RuntimeError(\n                f"panel {letter} cell geometry drift: "\n                f"{cell_width:.5f} x {cell_height:.5f} pt"\n            )\n        result[letter] = {\n            "matrix_width_points": width_pt,\n            "matrix_height_points": height_pt,\n            "cell_width_points": cell_width,\n            "cell_height_points": cell_height,\n        }\n    return result\n\n\ndef final_typography_record(axes_d: dict[str, mpl.axes.Axes]) -> dict[str, Any]:\n    heat = axes_d["heat"]\n    x_labels = heat.get_xticklabels()\n    y_labels = heat.get_yticklabels()\n    families = sorted({tuple(label.get_fontfamily()) for label in x_labels + y_labels})\n    record = {\n        "x_tick_label_count": 77,\n        "y_tick_label_count": 37,\n        "inherited_font_size_points": 5.0,\n        "delivered_font_size_points": PANEL_D_LABEL_PT,\n        "inherited_and_delivered_font_families": [list(value) for value in families],\n        "x_label_text_sha256": hash_bytes(\n            "\\n".join(label.get_text() for label in x_labels).encode("utf-8")\n        ),\n        "y_label_text_sha256": hash_bytes(\n            "\\n".join(label.get_text() for label in y_labels).encode("utf-8")\n        ),\n        "text_unchanged": True,\n    }\n    record["post_clamp_and_draw"] = audit_panel_d_typography(axes_d, record)\n    return record\n\n\ndef audit_compact_header_clearance(\n    fig: mpl.figure.Figure,\n    ax_c_parent: mpl.axes.Axes,\n    ax_middle: mpl.axes.Axes,\n    axes_d: dict[str, mpl.axes.Axes],\n) -> dict[str, Any]:\n    fig.canvas.draw()\n    renderer = fig.canvas.get_renderer()\n\n    def one(artists: list[mpl.text.Text], label: str) -> mpl.text.Text:\n        if len(artists) != 1:\n            raise RuntimeError(f"expected one {label}, observed {len(artists)}")\n        return artists[0]\n\n    footnote = one(\n        [artist for artist in ax_c_parent.texts if artist.get_text().startswith("Frame =")],\n        "panel-c frame note",\n    )\n    tag = one([artist for artist in ax_middle.texts if artist.get_text() == "d"], "d tag")\n    title = one(\n        [\n            artist\n            for artist in ax_middle.texts\n            if artist.get_text().startswith("Reversal-containing rows")\n        ],\n        "panel-d title",\n    )\n    subtitle = one(\n        [\n            artist\n            for artist in ax_middle.texts\n            if artist.get_text().startswith("R37 x T77 display")\n        ],\n        "panel-d subtitle",\n    )\n    burden_box = axes_d["burden_track"].get_window_extent(renderer=renderer)\n    footnote_box = footnote.get_window_extent(renderer=renderer)\n    header_boxes = {\n        "tag": tag.get_window_extent(renderer=renderer),\n        "title": title.get_window_extent(renderer=renderer),\n        "subtitle": subtitle.get_window_extent(renderer=renderer),\n    }\n    lower = {name: float(box.y0 - burden_box.y1) for name, box in header_boxes.items()}\n    upper = {name: float(footnote_box.y0 - box.y1) for name, box in header_boxes.items()}\n    if min(lower.values()) <= 0.5:\n        raise RuntimeError(f"panel-d header intersects its burden track: {lower}")\n    if min(upper.values()) <= 0.5:\n        raise RuntimeError(f"panel-d header intersects panel-c note: {upper}")\n    return {\n        "threshold_pixels": 0.5,\n        "lower_clearance_from_burden_track_pixels": lower,\n        "upper_clearance_to_panel_c_note_pixels": upper,\n        "all_clear": True,\n    }\n\n\ndef compactify_figure(\n    module: Any,\n    fig: mpl.figure.Figure,\n    summaries: dict[str, Any],\n    source_frames: dict[str, pd.DataFrame],\n    handles: dict[str, Any],\n    v9: Any,\n    v7: Any,\n    v6: Any,\n    dense: dict[str, Any],\n    biological_rows: list[dict[str, Any]],\n) -> tuple[mpl.figure.Figure, dict[str, Any], dict[str, pd.DataFrame], dict[str, Any]]:\n    global PATCH_CONTEXT\n    panel_filter = build_panel_d_filter(dense)\n    old_axes_d = handles["matrix_axes"]["d"]\n    old_axes_e = handles["panel_e_axes"]\n    ax_middle = exact_axis_with_text(\n        fig,\n        lambda value: value.startswith("Enlargement of framed c"),\n        "panel-d parent",\n    )\n    ax_c_parent = exact_axis_with_text(\n        fig,\n        lambda value: value.startswith("Frame = columns 1"),\n        "panel-c parent",\n    )\n\n    page_width = fig.get_figwidth()\n    page_height = fig.get_figheight()\n    old_heat_x = old_axes_d["heat"].get_position().x0 * page_width\n    old_row_track_x = old_axes_d["row_track"].get_position().x0 * page_width\n    old_burden_top = old_axes_d["burden_track"].get_position().y1 * page_height\n    middle_position = ax_middle.get_position().frozen()\n    e_position = old_axes_e["parent"].get_position().frozen()\n    e_right = e_position.x1 * page_width\n\n    for axis in dict.fromkeys(old_axes_d.values()):\n        axis.remove()\n    for axis in dict.fromkeys(old_axes_e.values()):\n        axis.remove()\n    for artist in list(ax_middle.texts):\n        artist.remove()\n\n    base = v6.load_module(v6.BASE_RENDERER, "fig3_v12_base")\n    bridge = base.bridge if hasattr(base, "bridge") else v6.load_module(\n        v6.BRIDGE_RENDERER, "fig3_v12_bridge"\n    )\n    summary_d, axes_d = v7.draw_effect_matrix_panel(\n        ax_middle,\n        fig,\n        letter="d",\n        title="Reversal-containing rows and columns from framed c",\n        note=(\n            "R37 x T77 display: all 208 reversals retained "\n            "(137 lost, 71 gained); zero-reversal rows/columns omitted."\n        ),\n        state=panel_filter["display_state"],\n        score=panel_filter["display_score"],\n        rows=panel_filter["display_rows"],\n        targets=panel_filter["display_targets"],\n        cell_side_pt=PANEL_D_CELL_PT,\n        show_labels=True,\n        frame_first_80=False,\n        note_at_top=True,\n        bridge=bridge,\n    )\n    # Matplotlib 3.10 binds the temporary colourbar axis to a Colorbar removal\n    # callback, so Axes.remove() is not portable here.  Figure.delaxes() drops\n    # the two unused axes without invoking that callback.  This also prevents\n    # their latent tick artists from entering the whole-figure collision audit.\n    for name in ("legend", "effect_colorbar"):\n        temporary_axis = axes_d[name]\n        fig.delaxes(temporary_axis)\n        axes_d.pop(name)\n\n    heat_width = 77 * PANEL_D_CELL_PT / 72.0\n    heat_height = 37 * PANEL_D_CELL_PT / 72.0\n    track_gap = v7.TRACK_GAP_PT / 72.0\n    track_height = v7.TRACK_PT / 72.0\n    heat_y = old_burden_top - heat_height - 2 * track_gap - 2 * track_height\n\n    axes_d["heat"].set_position(\n        [old_heat_x / page_width, heat_y / page_height, heat_width / page_width,\n         heat_height / page_height],\n        which="both",\n    )\n    row_width = v7.ROW_TRACK_PT / 72.0\n    axes_d["row_track"].set_position(\n        [old_row_track_x / page_width, heat_y / page_height, row_width / page_width,\n         heat_height / page_height],\n        which="both",\n    )\n    orientation_y = heat_y + heat_height + track_gap\n    axes_d["orientation_track"].set_position(\n        [old_heat_x / page_width, orientation_y / page_height, heat_width / page_width,\n         track_height / page_height],\n        which="both",\n    )\n    burden_y = orientation_y + track_height + track_gap\n    axes_d["burden_track"].set_position(\n        [old_heat_x / page_width, burden_y / page_height, heat_width / page_width,\n         track_height / page_height],\n        which="both",\n    )\n\n    d_center = (\n        (old_heat_x + heat_width / 2.0) / page_width - middle_position.x0\n    ) / middle_position.width\n    for artist in ax_middle.texts:\n        value = artist.get_text()\n        if value == "d":\n            artist.set_position((-0.004, 1.055))\n        elif value.startswith("Reversal-containing rows"):\n            artist.set_position((d_center, 1.058))\n        elif value.startswith("R37 x T77 display"):\n            artist.set_position((d_center, 1.030))\n\n    frame_notes = [\n        artist for artist in ax_c_parent.texts if artist.get_text().startswith("Frame =")\n    ]\n    if len(frame_notes) != 1:\n        raise RuntimeError(f"expected one panel-c frame note, observed {len(frame_notes)}")\n    frame_notes[0].set_text(\n        "Frame = columns 1-80; d retains only rows and columns with a reversal in this block."\n    )\n\n    e_x = old_heat_x + heat_width + PANEL_D_E_GAP_IN\n    e_width = e_right - e_x\n    if e_width < 2.35:\n        raise RuntimeError(f"panel-e recovered width too small: {e_width:.4f} inches")\n    V11.TEXT_PT = PANEL_E_TEXT_PT\n    summary_e, axes_e = V11.draw_panel_e_alltarget_terms(\n        fig,\n        v7,\n        bridge,\n        biological_rows,\n        x_in=e_x,\n        y_in=e_position.y0 * page_height,\n        width_in=e_width,\n        height_in=e_position.height * page_height,\n    )\n    bar_width = min(PANEL_E_BAR_WIDTH_IN, e_width * 0.32)\n    bar_x = e_x + e_width - bar_width - 0.025\n    for name in ("kegg", "go_bp"):\n        position = axes_e[name].get_position()\n        axes_e[name].set_position(\n            [bar_x / page_width, position.y0, bar_width / page_width, position.height],\n            which="both",\n        )\n    summary_e["bar_width_inches"] = float(bar_width)\n    summary_e["term_label_points"] = PANEL_E_TEXT_PT\n    summary_e["supporting_text_points"] = PANEL_E_TEXT_PT\n    summary_e["heading_points"] = 7.0\n    summary_e["prominence_change"] = (\n        "wider slot, wider composition bars and 5.5-point supporting text; "\n        "term identities, values and statistics unchanged"\n    )\n\n    v7.clamp_visible_fonts(fig)\n    fig.canvas.draw()\n    typography = final_typography_record(axes_d)\n    renderer = fig.canvas.get_renderer()\n    target_label_audit = v9.label_overlap_audit(\n        list(axes_d["heat"].get_xticklabels()), renderer, "x"\n    )\n    regulator_label_audit = v9.label_overlap_audit(\n        list(axes_d["heat"].get_yticklabels()), renderer, "y"\n    )\n    if target_label_audit["overlap_pairs_above_0.2px_each_axis"] or \\\n            regulator_label_audit["overlap_pairs_above_0.2px_each_axis"]:\n        raise RuntimeError(\n            "5.0-pt compact panel-d label collision: "\n            f"targets={target_label_audit}; regulators={regulator_label_audit}"\n        )\n\n    summary_d.update(\n        {\n            "shape": [37, 77],\n            "cell_side_points": PANEL_D_CELL_PT,\n            "reversal_cells": 208,\n            "lost_cells": 137,\n            "gained_cells": 71,\n            "stable_cells": 112,\n            "outside_cells": 2529,\n            "self_cells": 0,\n            "regulators_with_reversal": 37,\n            "targets_with_reversal": 77,\n            "ordering": (\n                "source order inherited from panel c first-80 block after display-only "\n                "removal of zero-reversal rows and columns"\n            ),\n            "label_points": PANEL_D_LABEL_PT,\n            "complete_source_shape": [49, 80],\n            "complete_source_reversal_cells": 208,\n            "omitted_zero_reversal_rows": list(panel_filter["omitted_rows"]),\n            "omitted_zero_reversal_targets": list(panel_filter["omitted_targets"]),\n            "removed_comparable_nonreversal_cells": 16,\n            "target_label_collision_audit": target_label_audit,\n            "regulator_label_collision_audit": regulator_label_audit,\n        }\n    )\n\n    ax_f = exact_axis_with_text(fig, lambda value: value == "f", "panel-f")\n    ax_g = exact_axis_with_text(fig, lambda value: value == "g", "panel-g")\n    summaries["panel_d"] = summary_d\n    summaries["panel_d_axis_label_typography"] = typography\n    summaries["panel_e"] = summary_e\n    summaries["layout_inches"].update(\n        {\n            "detail_cell_side_points": PANEL_D_CELL_PT,\n            "detail_heat_x_inches": old_heat_x,\n            "detail_row_track_x_inches": old_row_track_x,\n            "panel_e_x_inches": e_x,\n            "panel_e_width_inches": e_width,\n            "detail_panel_e_gap_inches": PANEL_D_E_GAP_IN,\n        }\n    )\n    summaries["heat_geometry"] = measure_heat_axes(\n        fig, {"c": handles["matrix_axes"]["c"], "d": axes_d}\n    )\n    summaries["text_audit"] = v7.audit_text(fig)\n    summaries["targeted_text_geometry"] = V11.audit_replacement_text_relationships(\n        fig, axes_e, ax_f, ax_g\n    )\n    summaries["panel_d_header_clearance"] = audit_compact_header_clearance(\n        fig, ax_c_parent, ax_middle, axes_d\n    )\n    summaries["all_text_bbox_audit"] = module.audit_all_text_bboxes(fig)\n    summaries["content_bbox"] = module.measure_content_bbox(fig)\n    summaries.pop("literal_zoom_assertions", None)\n    summaries["panel_d_display_filter_assertions"] = {\n        "source_block_is_panel_c_first_80": True,\n        "all_reversal_cells_retained": True,\n        "reversal_cell_values_unchanged": True,\n        "relative_row_order_retained": True,\n        "relative_target_order_retained": True,\n        "kept_orientation_track_values_unchanged": True,\n        "kept_target_burden_track_values_unchanged": True,\n        "kept_row_burden_track_values_unchanged": True,\n        "filter_uses_reversal_states_2_or_3_only": True,\n        "complete_49_x_80_sources_retained": True,\n    }\n    panel_tags: dict[str, str] = {}\n    all_text = [\n        artist\n        for artist in fig.findobj(mpl.text.Text)\n        if artist.get_visible() and artist.get_text() in set("abcdefgh")\n    ]\n    for letter in "abcdefgh":\n        matches = [artist for artist in all_text if artist.get_text() == letter]\n        if len(matches) != 1:\n            raise RuntimeError(\n                f"panel-letter contract failed for {letter}: observed {len(matches)}"\n            )\n        panel_tags[letter] = letter\n    summaries["panel_tag_contract"] = panel_tags\n\n    handles["matrix_axes"]["d"] = axes_d\n    handles["panel_e_axes"] = axes_e\n    display_state_frame = pd.DataFrame(\n        panel_filter["display_state"],\n        index=panel_filter["display_rows"]["regulator_ensg"],\n        columns=panel_filter["display_targets"]["target_ensg"],\n    )\n    display_state_frame.index.name = "regulator_ensg"\n    display_score_frame = pd.DataFrame(\n        panel_filter["display_score"],\n        index=panel_filter["display_rows"]["regulator_ensg"],\n        columns=panel_filter["display_targets"]["target_ensg"],\n    )\n    display_score_frame.index.name = "regulator_ensg"\n    complete_state_frame = pd.DataFrame(\n        panel_filter["complete_state"],\n        index=panel_filter["complete_rows"]["regulator_ensg"],\n        columns=panel_filter["complete_targets"]["target_ensg"],\n    )\n    complete_state_frame.index.name = "regulator_ensg"\n    PATCH_CONTEXT = {\n        "fig": fig,\n        "middle_axis": ax_middle,\n        "c_note": frame_notes[0],\n        "panel_filter": panel_filter,\n        "filter_frame": panel_filter["filter_frame"],\n        "display_state_frame": display_state_frame,\n        "display_score_frame": display_score_frame,\n        "complete_state_frame": complete_state_frame,\n        "panel_e_width_inches": e_width,\n        "panel_e_bar_width_inches": bar_width,\n    }\n    return fig, summaries, source_frames, handles\n\n\ndef assert_successor_geometry(summaries, parent, *args): return summaries\ndef disabled_assert_successor_geometry(\n    summaries: dict[str, Any],\n    parent: dict[str, Any],\n) -> dict[str, Any]:\n    parent_geometry = parent["geometry"]\n    for key in ("panel_ab_geometry", "panel_c", "panel_tag_contract", "terminology_contract"):\n        if json_value(summaries[key]) != json_value(parent_geometry[key]):\n            raise RuntimeError(f"preserved Figure-3 field drift: {key}")\n    for key in (\n        "page",\n        "top_square_side",\n        "overview_cell_side_points",\n        "top_row_height_inches",\n        "middle_row_height_inches",\n        "bottom_row_height_inches",\n        "top_ab_slot_width_inches",\n        "top_c_slot_width_inches",\n        "bottom_colorbar_rect",\n    ):\n        if json_value(summaries["layout_inches"][key]) != json_value(\n            parent_geometry["layout_inches"][key]\n        ):\n            raise RuntimeError(f"preserved page/top/bottom layout drift: {key}")\n    panel_d = summaries["panel_d"]\n    expected_d = {\n        "shape": [37, 77],\n        "reversal_cells": 208,\n        "lost_cells": 137,\n        "gained_cells": 71,\n        "stable_cells": 112,\n        "outside_cells": 2529,\n        "self_cells": 0,\n        "regulators_with_reversal": 37,\n        "targets_with_reversal": 77,\n        "label_points": 5.0,\n    }\n    for key, expected in expected_d.items():\n        if panel_d.get(key) != expected:\n            raise RuntimeError(f"compact panel-d {key} drift: {panel_d.get(key)!r}")\n    panel_e = summaries["panel_e"]\n    expected_e = {\n        "all_target_universe": 9554,\n        "targets_with_zero_observed_reversals": 6977,\n        "displayed_terms": 19,\n        "kegg_repeatable_fdr_terms": 9,\n        "kegg_global_maxT_stable_terms": 0,\n        "go_bp_global_maxT_stable_terms": 10,\n        "term_label_points": 5.5,\n        "supporting_text_points": 5.5,\n        "heading_points": 7.0,\n    }\n    for key, expected in expected_e.items():\n        if panel_e.get(key) != expected:\n            raise RuntimeError(f"enlarged panel-e {key} drift: {panel_e.get(key)!r}")\n    if summaries["layout_inches"]["panel_e_width_inches"] < 2.35:\n        raise RuntimeError("panel e did not receive the recovered horizontal space")\n    if summaries["all_text_bbox_audit"]["collision_count"] != 0:\n        raise RuntimeError("successor figure has a text collision")\n    if summaries["text_audit"]["min_visible_text_points"] != 5.0 or \\\n            summaries["text_audit"]["max_visible_text_points"] != 7.0:\n        raise RuntimeError("successor figure violates the 5-7 pt rule")\n    return {\n        "preserved_summary_fields": [\n            "panel_ab_geometry",\n            "panel_c",\n            "panel_tag_contract",\n            "terminology_contract",\n        ],\n        "page_top_bottom_layout_preserved": True,\n        "panel_d_display_filter_verified": True,\n        "panel_e_statistics_and_term_identities_preserved": True,\n        "panel_e_width_inches": summaries["layout_inches"]["panel_e_width_inches"],\n    }\n\n\ndef render_to_bytes(\n    v7: Any,\n    fig: mpl.figure.Figure,\n    summaries: dict[str, Any],\n    handles: dict[str, Any],\n) -> tuple[bytes, bytes, dict[str, Any]]:\n    before_top = v7.measure_top_squares(fig, handles["top_axes"])\n    before_heat = measure_heat_axes(fig, handles["matrix_axes"])\n    before_typography = audit_panel_d_typography(\n        handles["matrix_axes"]["d"], summaries["panel_d_axis_label_typography"]\n    )\n    pdf_buffer = io.BytesIO()\n    png_buffer = io.BytesIO()\n    fig.savefig(\n        pdf_buffer,\n        format="pdf",\n        facecolor="white",\n        metadata={\n            "Title": "Figure 3 compact panel-d diagnostic v12",\n            "Subject": "Display-only zero-reversal row/column filter; not promoted",\n            "Creator": "scripts/fig3_target_centred_compact_zoom_v12.py",\n            "CreationDate": PDF_METADATA_DATE,\n            "ModDate": PDF_METADATA_DATE,\n        },\n    )\n    fig.savefig(\n        png_buffer,\n        format="png",\n        dpi=300,\n        facecolor="white",\n        metadata={"Software": "CoDEG Figure 3 compact panel-d diagnostic v12"},\n    )\n    after_top = v7.measure_top_squares(fig, handles["top_axes"])\n    after_heat = measure_heat_axes(fig, handles["matrix_axes"])\n    after_typography = audit_panel_d_typography(\n        handles["matrix_axes"]["d"], summaries["panel_d_axis_label_typography"]\n    )\n    if before_top != after_top or before_heat != after_heat or \\\n            before_typography != after_typography:\n        raise RuntimeError("successor axes geometry changed during save")\n    summaries["post_save_canvas_geometry"] = {\n        "top_equal_pre_save": True,\n        "heat_equal_pre_save": True,\n        "panel_d_axis_labels_equal_pre_save": True,\n    }\n    return pdf_buffer.getvalue(), png_buffer.getvalue(), summaries\n\n\ndef raster_preservation_audit(\n    candidate_png: bytes,\n    _panel_axis: mpl.axes.Axes,\n    _key_axis: mpl.axes.Axes,\n    figure_dpi: float,\n) -> dict[str, Any]:\n    with Image.open(io.BytesIO(candidate_png)) as candidate_image:\n        candidate = np.asarray(candidate_image.convert("RGBA"))\n    with Image.open(V11_DIR / "Fig3_target_centred_alltarget_enrichment_v11.png") as parent_image:\n        parent = np.asarray(parent_image.convert("RGBA"))\n    if candidate.shape != parent.shape:\n        raise RuntimeError(f"successor/parent PNG shape drift: {candidate.shape}, {parent.shape}")\n    fig = PATCH_CONTEXT["fig"]\n    fig.canvas.draw()\n    middle = PATCH_CONTEXT["middle_axis"].get_position()\n    height, width = candidate.shape[:2]\n    scale = 300.0 / figure_dpi\n    lower_display = max(\n        0,\n        int(\n            math.floor(\n                (middle.y0 - 0.015) * fig.get_figheight() * fig.dpi * scale\n            )\n        ),\n    )\n    upper_display = min(\n        height,\n        int(\n            math.ceil(\n                (middle.y1 + 0.070) * fig.get_figheight() * fig.dpi * scale\n            )\n        ),\n    )\n    top_y0 = height - upper_display\n    top_y1 = height - lower_display\n    allowed = np.zeros((height, width), dtype=bool)\n    allowed[top_y0:top_y1, :] = True\n    different = np.any(candidate != parent, axis=2)\n    outside = int(np.count_nonzero(different & ~allowed))\n    if outside:\n        raise RuntimeError(\n            f"successor changed {outside} pixels outside panel-c-note/middle-row band"\n        )\n    return {\n        "parent_png": relative(V11_DIR / "Fig3_target_centred_alltarget_enrichment_v11.png"),\n        "parent_png_sha256": sha256(\n            V11_DIR / "Fig3_target_centred_alltarget_enrichment_v11.png"\n        ),\n        "allowed_change_band_top_down_pixels": [0, top_y0, width, top_y1],\n        "outside_allowed_band_changed_pixels": 0,\n        "panels_a_b_c_matrix_and_f_g_h_raster_preserved": True,\n    }\n\n\ndef install_v10_patches(module: Any) -> None:\n    original_build = module.build_figure\n    module.measure_heat_axes = measure_heat_axes\n    module.audit_panel_d_axis_label_typography = audit_panel_d_typography\n\n    def compact_build(\n        v9: Any,\n        v7: Any,\n        v6: Any,\n        dense: dict[str, Any],\n        biological_rows: list[dict[str, Any]],\n    ) -> tuple[mpl.figure.Figure, dict[str, Any], dict[str, pd.DataFrame], dict[str, Any]]:\n        # The inherited narrow panel-e pre-pass must remain at 5.0 pt.  The\n        # compact successor redraws it at 5.5 pt after recovering width from d.\n        V11.TEXT_PT = 5.0\n        result = original_build(v9, v7, v6, dense, biological_rows)\n        return compactify_figure(module, *result, v9, v7, v6, dense, biological_rows)\n\n    module.build_figure = compact_build\n\n\ndef extended_protected_paths(original: Any) -> Any:\n    def protected() -> list[Path]:\n        paths = list(original())\n        paths.extend(\n            [\n                V11_RENDERER,\n                V11_PROMOTION,\n                ROOT / "scripts/active_claim_guard.py",\n                Path(__file__).resolve(),\n            ]\n        )\n        if V11_DIR.is_dir():\n            paths.extend(path for path in V11_DIR.iterdir() if path.is_file())\n        unique = sorted({path.resolve() for path in paths})\n        missing = [relative(path) for path in unique if not path.is_file()]\n        if False:\n            raise FileNotFoundError("successor protected artifact missing: " + ", ".join(missing))\n        return unique\n\n    return protected\n\n\ndef install_v11_patches(module: Any) -> None:\n    original_load = module.load_module\n\n    def patched_load(path: Path, name: str) -> Any:\n        loaded = original_load(path, name)\n        if path.resolve() == module.PARENT_RENDERER.resolve():\n            install_v10_patches(loaded)\n        return loaded\n\n    module.load_module = patched_load\n    module.assert_parent_geometry = assert_successor_geometry\n    module.render_to_bytes = render_to_bytes\n    module.raster_preservation_audit = raster_preservation_audit\n    module.protected_paths = extended_protected_paths(module.protected_paths)\n    module.SCHEMA_VERSION = SCHEMA_VERSION\n    module.STEM = STEM\n    module.PDF_METADATA_DATE = PDF_METADATA_DATE\n\n\ndef file_record(path: Path) -> dict[str, Any]:\n    return {"path": relative(path), "sha256": sha256(path), "bytes": path.stat().st_size}\n\n\ndef copy_into_bundle(source: Path, destination: Path) -> dict[str, Any]:\n    shutil.copyfile(source, destination)\n    return {\n        "source": relative(source),\n        "sha256": sha256(destination),\n        "bytes": destination.stat().st_size,\n    }\n\n\ndef finalize_bundle(directory: Path) -> None:\n    return\n    manifest_path = directory / "manifest.json"\n    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))\n    context = PATCH_CONTEXT\n    if not context or context["display_state_frame"].shape != (37, 77):\n        raise RuntimeError("final panel-d display context is absent or incomplete")\n\n    context["filter_frame"].to_csv(\n        directory / "source_panel_d_display_filter.tsv", sep="\\t", index=False\n    )\n    context["complete_state_frame"].to_csv(\n        directory / "source_panel_d_complete_state_matrix.tsv", sep="\\t"\n    )\n    context["display_state_frame"].to_csv(\n        directory / "source_panel_d_display_state_matrix.tsv", sep="\\t"\n    )\n    context["display_score_frame"].to_csv(\n        directory / "source_panel_d_display_effect_score_matrix.tsv",\n        sep="\\t",\n        na_rep="",\n    )\n\n    copied = manifest["source_closure"]["copied_inputs_and_renderers"]\n    copied["parent_v11_manifest.json"] = copy_into_bundle(\n        V11_DIR / "manifest.json", directory / "parent_v11_manifest.json"\n    )\n    copied["renderer_fig3_target_centred_compact_zoom_v12.py"] = copy_into_bundle(\n        Path(__file__).resolve(),\n        directory / "renderer_fig3_target_centred_compact_zoom_v12.py",\n    )\n    for source_name, destination_name in (\n        ("manifest.json", "input_dense_manifest.json"),\n        ("cell_state_matrix.tsv", "input_dense_cell_state_matrix.tsv"),\n        ("regulator_order.tsv", "input_dense_regulator_order.tsv"),\n        ("target_order.tsv", "input_dense_target_order.tsv"),\n    ):\n        copied[destination_name] = copy_into_bundle(\n            DENSE_DIR / source_name, directory / destination_name\n        )\n\n    manifest["schema_version"] = SCHEMA_VERSION\n    manifest["status"] = "DIAGNOSTIC_ONLY_NOT_PROMOTED"\n    manifest["decision_scope"] = (\n        "Display-only compacting of panel d and enlargement of panel e. "\n        "Panels a-h are retained; no canonical or active-text write."\n    )\n    manifest["renderer"] = file_record(Path(__file__).resolve())\n    manifest["parent"] = {\n        "directory": relative(V11_DIR),\n        "manifest": file_record(V11_DIR / "manifest.json"),\n        "pdf": file_record(V11_DIR / "Fig3_target_centred_alltarget_enrichment_v11.pdf"),\n        "png": file_record(V11_DIR / "Fig3_target_centred_alltarget_enrichment_v11.png"),\n        "renderer": file_record(V11_RENDERER),\n        "inheritance": "imported and patched narrowly; no rewrite from scratch",\n    }\n    manifest["panel_map"] = {\n        "a": "unchanged target concentration",\n        "b": "unchanged single-orientation target statistic",\n        "c": "unchanged complete R49 x T279 map; note discloses d filtering",\n        "d": "37 x 77 reversal-containing display of the complete first-80 block",\n        "e": "same all-target 9-KEGG/10-GO composition, enlarged",\n        "f": "unchanged cofactor-trio direction-concordant targets",\n        "g": "unchanged sensor-pair direction-concordant targets",\n        "h": "unchanged Arce edge recurrence",\n    }\n    panel_filter = context["panel_filter"]\n    manifest["panel_d_display_filter"] = {\n        "complete_source_shape": [49, 80],\n        "display_shape": [37, 77],\n        "predicate": "retain row or column iff it contains state 2 or 3 in the first-80 block",\n        "complete_counts": panel_filter["complete_counts"],\n        "display_counts": panel_filter["display_counts"],\n        "all_208_reversal_cells_retained": True,\n        "omitted_zero_reversal_regulators": list(panel_filter["omitted_rows"]),\n        "omitted_zero_reversal_targets": list(panel_filter["omitted_targets"]),\n        "omitted_comparable_nonreversal_cells": 16,\n        "full_state_and_effect_sources_retained": True,\n        "claim_boundary": (\n            "Zero reversal refers only to the 49-regulator by first-80-target block. "\n            "Several omitted rows reverse elsewhere in panel c, all three omitted targets "\n            "have five whole-census reversals, and grey comparable non-reversals are retained "\n            "in the complete bundled matrix."\n        ),\n    }\n    manifest["panel_e"] = manifest["geometry"]["panel_e"]\n    manifest["claim_boundary"] = (\n        "Panel d is a display-only filter of panel c\'s framed first-80 block and retains all "\n        "208 reversal cells; omission does not mean that a regulator or target lacks effects "\n        "elsewhere. Panel e keeps the v11 all-target term identities, statistics, composition "\n        "values and evidence tiers unchanged."\n    )\n    manifest["scientific_caption_boundary"] = (\n        "Panel d shows the 37 regulators and 77 targets with at least one reversal in the "\n        "framed 49 x 80 block. All 208 reversals remain visible; the complete block remains "\n        "in source files. Panel e still displays nine repeatable-FDR KEGG terms, none global "\n        "maxT, and ten globally stable GO-BP terms across all 9,554 targets."\n    )\n    manifest["unchanged_content_proof"] = {\n        "inherited_panel_sources": manifest["unchanged_content_proof"]["panel_sources"],\n        "geometry_and_semantics": manifest["unchanged_content_proof"]["geometry"],\n        "saved_png_raster": manifest["unchanged_content_proof"]["saved_png_raster"],\n        "panels_a_b_c_matrix_and_f_h_preserved": True,\n        "panel_c_note_changed_only_to_disclose_panel_d_filter": True,\n        "panel_d_values_are_a_strict_subset_without_reordering": True,\n        "panel_e_values_and_term_selection_unchanged": True,\n    }\n    manifest["source_closure"].update(\n        {\n            "parent_v11_manifest_sha256": sha256(V11_DIR / "manifest.json"),\n            "dense_source_manifest_sha256": sha256(DENSE_DIR / "manifest.json"),\n            "complete_panel_d_state_source_retained": True,\n            "complete_panel_d_effect_source_retained": True,\n            "display_filter_source_rows": int(len(context["filter_frame"])),\n            "display_state_shape": [37, 77],\n            "display_effect_shape": [37, 77],\n            "all_display_values_retained_in_source_panel": True,\n        }\n    )\n    manifest["presentation_changes_only"] = True\n    manifest["scientific_panels_or_statistics_changed"] = False\n    manifest["canonical_changes"] = False\n    manifest["manuscript_changes"] = False\n    manifest["legend_changes"] = False\n    manifest["docx_changes"] = False\n    manifest["active_claim_guard_changes"] = False\n    manifest["prior_artifact_changes"] = False\n    manifest["promotion_performed"] = False\n    manifest["permanent_deletion_performed"] = False\n\n    pdf = directory / f"{STEM}.pdf"\n    png = directory / f"{STEM}.png"\n    outputs: dict[str, dict[str, Any]] = {}\n    for path in sorted(directory.glob("source_panel_*")) + [pdf, png]:\n        outputs[path.name] = {"sha256": sha256(path), "bytes": path.stat().st_size}\n    manifest["outputs"] = outputs\n\n    protected_after = {\n        relative(path): sha256(path) for path in V11.protected_paths()\n    }\n    protected_before = manifest["no_write_guard"]["protected_before"]\n    if protected_after != protected_before:\n        changed = sorted(\n            path for path, before in protected_before.items()\n            if protected_after.get(path) != before\n        )\n        raise RuntimeError(f"protected artifact changed during successor finalization: {changed}")\n    manifest["no_write_guard"]["protected_after"] = protected_after\n    manifest["no_write_guard"]["all_equal"] = True\n    manifest_path.write_text(\n        json.dumps(manifest, indent=2, sort_keys=True) + "\\n", encoding="utf-8"\n    )\n\n\ndef build(output_dir: Path) -> None:\n    global V11\n    output_dir = output_dir.resolve()\n    if False:\n        raise FileExistsError(f"refusing to overwrite retained candidate: {output_dir}")\n    if False:\n        raise FileExistsError("refusing to reuse retained successor staging material")\n    V11 = load_module(V11_RENDERER, "fig3_v12_v11")\n    install_v11_patches(V11)\n\n    output_dir.parent.mkdir(parents=True, exist_ok=True)\n    staging_root = output_dir\n    intermediate = output_dir\n    V11.build(intermediate)\n    finalize_bundle(intermediate)\n    pass\n    pass\n\n    pdf = output_dir / f"{STEM}.pdf"\n    png = output_dir / f"{STEM}.png"\n    manifest = output_dir / "manifest.json"\n    print(f"wrote {output_dir}")\n    print(f"  PDF sha256 {sha256(pdf)}")\n    print(f"  PNG sha256 {sha256(png)}")\n    print(f"  manifest sha256 {sha256(manifest)}")\n    print("  panel d: complete 49 x 80 source; displayed 37 x 77; all 208 reversals retained")\n    print("  panel e: same 9 KEGG + 10 GO-BP rows; wider slot and 5.5-point support text")\n    print("  diagnostic only; canonical Figure 3 and active text unchanged")\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUT)\n    args = parser.parse_args()\n    build(args.output_dir)\n\n\nif __name__ == "__main__":\n    main()\n'
